/* Views of the shared 02005000 BG1 tilemap; scene effects also reuse it. */
#define COLLECTION_CARD_FRAME_DEST ((u16 *)0x02005058)
#define COLLECTION_CARD_NUMBER_DEST ((u16 *)0x020053A8)
#define COLLECTION_WIDE_CARD_NUMBER_DEST ((u16 *)0x020053B4)
#define MAP_TILEMAP_A ((u16 *)0x02004000)
#define MAP_TILEMAP_B ((u16 *)0x02004800)
#define SCENE_EFFECT_TILEMAP ((u16 *)0x02005000)
#define TITLE_CURSOR_TILES ((void *)0x06013800)
#define TITLE_OPTION_TILES ((void *)0x06017000)
#define SPRITE_NODE_SNAPSHOT ((void *)0x0203F000)
#define SPRITE_AFFINE_SNAPSHOT ((void *)0x0203FE00)

/* BSS: private definitions, in address order. */
static struct MenuCursor gMenuCursor;                           /* 0x03000048 */
static struct MenuEntry gMenuEntries[MENU_ENTRY_COUNT];         /* 0x03000058 */

static u8 sMenuDrawMode;                                        /* 0x03000184 */
static u8 sMenuHeaderRefreshPending;                            /* 0x03000185 */
static u8 gMenuPage;                                            /* 0x03000186 */
static u8 gMenuPhase;                                           /* 0x03000187 */
static u8 gMenuSavedSelections[MENU_SAVED_SELECTION_COUNT];     /* 0x03000188 */
static u8 gMenuTextBlinkCounter;                                /* 0x03000198 */
static u8 gMenuInventoryStartItem;                              /* 0x03000199 */
static u8 gMenuInventoryItems[MENU_INVENTORY_WINDOW_SIZE];      /* 0x030001A0 */
static u8 gMenuInventoryPreviousItems[2];                       /* 0x030001AA */
static u8 gMenuInventoryNextItems[2];                           /* 0x030001AC */
static u8 gMenuItemRecoveryType;                                /* 0x030001AE */
static u8 gMenuItemRecoveryAmount;                              /* 0x030001AF */
static u8 gMenuEffectDelay;                                     /* 0x030001B0 */
static u8 gMenuEquipmentStartItem;                              /* 0x030001B1 */
static u8 gMenuEquipmentCandidates[MENU_EQUIPMENT_WINDOW_SIZE]; /* 0x030001B4 */
static u8 gMenuEquipmentPreviousItem;                           /* 0x030001B9 */
static u8 gMenuEquipmentNextItem;                               /* 0x030001BA */
static u8 gMenuStatPreviewPalettes[PARTY_ATTRIBUTE_COUNT];      /* 0x030001BC */
static u8 gMenuFieldSkillId;                                    /* 0x030001C3 */
static u8 gMenuFieldSkillMpCost;                                /* 0x030001C4 */
static u8 gMenuFieldSkillTargetMode;                            /* 0x030001C5 */
static u8 gMenuFieldSkillRecoveryAmount;                        /* 0x030001C6 */
static u16 gMenuHintId;                                         /* 0x030001C8 */
static const u8 *gMenuHintBanks[MENU_HINT_BANK_COUNT];          /* 0x030001D0 */
static u8 gMenuDestinations[MENU_DESTINATION_COUNT];            /* 0x030001F0 */
static u8 gMenuDestinationScroll;                               /* 0x03000200 */
static u8 gSaveSummaryLevels[SAVE_SLOT_COUNT];                  /* 0x03000204 */
static u8 gSaveSummarySceneIds[SAVE_SLOT_COUNT];                /* 0x03000208 */
static u32 gSaveSummaryPlayTimes[SAVE_SLOT_COUNT];              /* 0x03000210 */
static u8 gMenuSaveSlot;                                        /* 0x03000220 */
static u8 gMenuSaveRequestKind;                                 /* 0x03000221 */
static u8 gMenuFormationFirstSelection;                         /* 0x03000222 */
static u8 gMenuFormationSecondSelection;                        /* 0x03000223 */
static u8 gMenuTacticsAction;                                   /* 0x03000224 */
static u8 gMenuTacticsActionId;                                 /* 0x03000225 */
static u8 gMenuTacticsPartySlot;                                /* 0x03000226 */
static u8 gMenuTacticsScroll;                                   /* 0x03000227 */
static u8 gShopBuyWindowStart;                                  /* 0x03000228; Buy-list window start. */
static u8 gShopSelectedItemId;                                  /* 0x03000229; Selected item, shared by buy/sell confirmation. */
static u8 gShopPreviewEquipmentSlot;                            /* 0x0300022A; Equipment slot selected for the purchase preview. */
static u8 gShopEquipPromptActive;                               /* 0x0300022B; Payment completed; waiting for the equip-or-keep choice. */
static u32 gShopSelectedItemPrice;                              /* 0x0300022C; Selected item's price in gold. */
static u16 gSoundTestSfxIndex;                                  /* 0x03000230; Title sound-test index 0..94; mapped through the SFX id table before playback. */
static u8 gSoundTestBgmId;                                      /* 0x03000232; Title sound-test selection 0..65; passed directly to Sound_PlayBgm. */
static u8 gSoundTestPlayingBgmIdPlusOne;                        /* 0x03000233; Zero means stopped; otherwise the playing sound-test selection plus one. */
static u8 gTitleIdleCyclesRemaining;                            /* 0x03000234; Title idle timeout in groups of sixty-four input updates. */
static u16 gCollectionCommittedRecordId;                        /* 0x03000236; Committed gallery image id; also the received-card temporary during exchange. */
static u16 gCollectionSelectedCardId;                           /* 0x03000238; Sixteen-bit selected card id; the quantity getter receives its low byte. */

/* Fifteen 0x14-byte records preserve the original 0x12C-byte allocation. */
typedef char MenuEntryArrayCheck[(sizeof(gMenuEntries) == 0x12C) ? 1 : -1];

/* COMMON: shared menu state, in address order. */
u8 gMenuContext;                                                /* 0x03004D40 */
u8 gSaveIoState;                                                /* 0x03004D44 */
u16 gMenuExtraFlags;                                            /* 0x03004D48 */
u8 gMenuState;                                                  /* 0x03004D4C */
u8 gSaveLastUsedSlot;                                           /* 0x03004D50 */
u8 gCollectionPackedCardCounts[90];                             /* 0x03004D60; Even ids use the low nibble, odd ids the high nibble. */
u16 gCollectionRatingAnimationCounter;                          /* 0x03004DBC; Draw counter: bits 2..3 animate stars; bits 4..5 cycle the complete rating palette. */
u8 gSceneEffectTilemapUploadPending;                            /* 0x03004DC0 */
u8 gShopActive;                                                 /* 0x03004DC4; Cleared on close; script opcode 3E waits while nonzero. */
u8 gCollectionEventFlags[8];                                    /* 0x03004DC8; Sixty-four collection event bits, also consumed by the gallery. */
u8 gSaveIoBlockIndex;                                           /* 0x03004DD0; 0x800-byte SRAM block cursor; bonus writes start at 12. */
u8 gShopId;                                                     /* 0x03004DD4; Index of an eight-item shop catalogue. */
u8 gShopTransactionOccurred;                                    /* 0x03004DD8; Reset on open; successful buy or sale sets 1. */
u16 gMenuSavedDisplayControl;                                   /* 0x03004DDC; Saved DISPCNT shared by the field menu and shop. */
u16 gMenuSavedBlendControl;                                     /* 0x03004DE0; Saved BLDCNT shared by the field menu and shop. */
u16 gCollectionOwnedCardTypeCount;                              /* 0x03004DE4; Distinct owned ordinary types 0..175; excludes four special cards. */
u16 gSaveBonusSlotValid;                                        /* 0x03004DE8; Fourth SRAM slot signature accepted; also selects the default title option. */

/**
 * @brief 菜单开闭状态机、窗口展开与关闭、头像资源加载
 *
 * @note 每次更新文字闪烁计数。
 * @address 0x0800ACC8
 */
void Menu_UpdateState(void)
{
    u16 index;

    switch (gMenuState)
    {
    case 0:
    {
        u16 *dest;
        u8 itemIndex;

        gMenuSavedDisplayControl = (*(vu16 *)REG_DISPCNT);
        gMenuSavedBlendControl = (*(vu16 *)REG_BLDCNT);
        (*(vu16 *)REG_BG0HOFS) = 0;
        (*(vu16 *)REG_BG0VOFS) = 0;
        (*(vu16 *)REG_BG0CNT) = 0x1F08;
        dest = gScriptTextTilemap;
        for (index = 0; index <= 1023; index++)
            *dest++ = 0;
        Menu_InitEntries(0);
        sMenuDrawMode = 0;
        gMenuState = 100;
        sMenuHeaderRefreshPending = 0;
        gMenuSaveRequestKind = 0;
        gMenuTextBlinkCounter = 0;
        for (itemIndex = 0; itemIndex <= 8; itemIndex++)
        {
            if (gPartyItemCounts[gMenuPreferredInventoryItems[itemIndex]] != 0)
            {
                gMenuInventoryStartItem = gMenuPreferredInventoryItems[itemIndex];
                break;
            }
        }
        if (itemIndex == 9)
            Menu_SelectFirstInventoryItem();
        gMenuEquipmentStartItem = 0;
        gMenuEffectDelay = 0;
        Sound_PlaySfx(4, 0, 0);
        break;
    }
    case 107:
        gMenuState = 1;
        break;
    case 104:
        gSceneState = 7;
        gMenuState++;
        break;
    case 100:
        (*(vu16 *)REG_DISPCNT) |= 0x100;
    case 101:
    case 102:
    case 103:
        Menu_DrawWindowTransition(gMenuState - 99);
        gMenuState++;
        break;
    case 1:
    {


        DmaCopy(3, gSpriteNodes, SPRITE_NODE_SNAPSHOT, sizeof(gSpriteNodes), 16);
        DmaCopy(3, gSpriteAffineMatrices, SPRITE_AFFINE_SNAPSHOT,
                                    sizeof(gSpriteAffineMatrices), 16);
        Menu_InitHintBanks();
        Menu_BuildTravelDestinations();
        (*(vu16 *)REG_DISPCNT) |= 0x100;
        gMenuState++;
        break;
    }
    case 62:
    case 63:
    case 64:
    case 65:
    {
        u16 *dest = gScriptTextTilemap;

        for (index = 0; index <= 1023; index++)
            *dest++ = 0;
        Menu_DrawWindowTransition(65 - gMenuState);
        gMenuState++;
        break;
    }
    case 67:
        (*(vu16 *)REG_DISPCNT) = gMenuSavedDisplayControl;
        (*(vu16 *)REG_BLDCNT) = gMenuSavedBlendControl;
        gMenuState = 0;
        break;
    case 7:
        Sprite_ClearDrawOrder();
    case 6:
    case 8:
    case 9:
    case 10:
        Menu_LoadPartyPortrait(gMenuState - 6);
        gMenuState++;
        break;
    case 11:
        Menu_LoadSharedSpriteGraphics();
        gMenuState++;
        break;
    case 12:
        Menu_InitSprites();
        (*(vu16 *)REG_DISPCNT) &= 0xF1FF;
        Menu_DrawContents();
        Menu_ShowHint(0);
        gMenuState++;
        break;
    case 52:
    {
        struct ActorState *actors;

        for (index = 0, actors = gActorStates; index <= 4; index++)
        {
            u32 actorSlot = index + CORE_MENU_ACTOR_FIRST;
            struct ActorState *actor =
                (struct ActorState *)(actorSlot * sizeof(struct ActorState) + (u32)actors);

            if (actor->spriteSlot != 0)
            {
                Sprite_FreeChain(&gSpriteNodes[actor->spriteSlot]);
                actor->spriteSlot = 0;
            }
        }
        (*(vu16 *)REG_DISPCNT) = gMenuSavedDisplayControl | 0x100;
        (*(vu16 *)REG_BLDCNT) = gMenuSavedBlendControl;
        Sound_PlaySfx(5, 0, 0);
    }
    case 53:
    case 54:
    case 55:
    case 56:
    case 57:
    case 58:
    case 59:
    case 60:
        Sprite_ClearDrawOrder();
        gMenuState++;
        break;
    case 61:
        gSceneState = 1;
    case 2:
    case 3:
    case 4:
    case 5:
    case 66:
    case 105:
    case 106:
        gMenuState++;
        break;
    }
    gMenuTextBlinkCounter++;
}

/**
 * @brief 按菜单或商店状态上传文本、头像和公共 OBJ 图块
 *
 * @note 无菜单时更新场景背景。
 * @address 0x0800B14C
 */
void Menu_UpdateVBlank(void)
{
    u8 portraitIndex;

    if (gMenuState != 0)
    {
        if ((portraitIndex = gMenuState - 7) <= 4)
        {
            Menu_UploadPartyPortrait(portraitIndex);
            return;
        }
        if (gMenuState == 12)
        {
            Menu_UploadSharedSpriteGraphics();
            Menu_ResetNavigation();
            return;
        }
        if ((u8)(gMenuState - 0x35) <= 7)
        {
            Actor_ReloadResourceSlot(gMenuState + 0xCD);
            return;
        }
        DmaCopy(3, gScriptTextTilemap, BG_SCREEN_ADDR(31), 0x800, 16);
        switch (gMenuState)
        {
        case 2:
            LZ77UnCompVram((void *)(gWorldMapUiTilemap0), BG_SCREEN_ADDR(26));
            break;
        case 3:
            LZ77UnCompVram((void *)(gWorldMapUiTilemap1), (u8 *)BG_SCREEN_ADDR(26) + 0x400);
            break;
        case 4:
            LZ77UnCompVram((void *)(gWorldMapUiTilemap2), BG_SCREEN_ADDR(27));
            break;
        case 5:
            LZ77UnCompVram((void *)(gWorldMapUiTilemap3), (u8 *)BG_SCREEN_ADDR(27) + 0x400);
            break;
        }
    }
    else if (gMenuContext != 0)
    {
        if ((portraitIndex = gMenuContext - 3) <= 4)
        {
            Menu_UploadPartyPortrait(portraitIndex);
            return;
        }
        if (gMenuContext == 2)
        {
            Menu_UploadSharedSpriteGraphics();
            Menu_ResetNavigation();
            return;
        }
        if ((u8)(gMenuContext + 15) <= 7)
        {
            Actor_ReloadResourceSlot(gMenuContext + 17);
            return;
        }
        DmaCopy(3, gScriptTextTilemap, BG_SCREEN_ADDR(31), 0x800, 16);
        switch (gMenuContext)
        {
        case 31:
            LZ77UnCompVram((void *)(gWorldMapUiTilemap0), BG_SCREEN_ADDR(26));
            break;
        case 32:
            LZ77UnCompVram((void *)(gWorldMapUiTilemap1), (u8 *)BG_SCREEN_ADDR(26) + 0x400);
            break;
        case 33:
            LZ77UnCompVram((void *)(gWorldMapUiTilemap2), BG_SCREEN_ADDR(27));
            break;
        case 34:
            LZ77UnCompVram((void *)(gWorldMapUiTilemap3), (u8 *)BG_SCREEN_ADDR(27) + 0x400);
            break;
        }
    }
    else
    {
        u16 sceneType = gSceneType;

        if (sceneType != 0xFF)
        {


            DmaCopy(3, MAP_TILEMAP_A, BG_SCREEN_ADDR(28), 0x800, 16);
            if (sceneType != 0xFE)
            {
                DmaCopy(3, MAP_TILEMAP_B, BG_SCREEN_ADDR(29), 0x800, 16);
            }
        }
    }
    return;
}

/**
 * @brief 重置菜单页、页面选择、软件光标和保存的导航位置
 *
 * @note 光标初始像素坐标为 (24,8)；清十六个页面选择，保留条目和库存数据。
 * @address 0x0800B2D0
 */
void Menu_ResetNavigation(void)
{
    u8 index;

    gMenuPage = 0;
    gMenuPhase = 0;
    gMenuCursor.flags = 1;
    gMenuCursor.blinkCounter = 0;
    gMenuCursor.transitionFrames = 0;
    gMenuCursor.reserved03 = 0;
    gMenuCursor.x = 24;
    gMenuCursor.y = 8;
    for (index = 0; index <= 15; index++)
        gMenuSavedSelections[index] = 0;
}

/**
 * @brief 按刷新标记更新场景技能页的队伍姓名和等级
 *
 * @note 仅绘制模式 4 重绘有效队员的表头；处理后清除表头刷新标记。
 * @address 0x0800B314
 */
void Menu_RefreshPartyHeaders(void)
{
    u8 index;
    u8 x;

    if (sMenuHeaderRefreshPending != 0)
    {
        if (sMenuDrawMode == MENU_DRAW_FIELD_SKILLS)
        {
            Menu_GetSelectedPartySlot();
            for (index = 0; index <= 4; index++)
            {
                if (gPartyMembers[index] != PARTY_NO_MEMBER)
                {
                    x = index * 5 + 5;
                    Menu_DrawCharacterName(gPartyMembers[index], x, 5);
                    Menu_DrawCharacterLevel(gPartyMembers[index], x, 6);
                }
            }
        }
        sMenuHeaderRefreshPending = 0;
    }
}

/**
 * @brief 按绘制模式重绘队伍、状态、物品、装备、技能、存档或队形内容
 *
 * @note 绘制模式 0..6 与页面编号不同；写软件文本缓冲，角色状态页还处理最高等级的经验字段。
 * @address 0x0800B374
 */
void Menu_DrawContents(void)
{
    u8 value;
    u8 index;
    struct PartyCharacter *character;
    u16 *dest;

    switch (sMenuDrawMode)
    {
    /* Party overview */
    case 0:
    {
        u8 x;

        for (index = 0; index <= 4; index++)
        {
            if (gPartyMembers[index] != PARTY_NO_MEMBER)
            {
                x = index * 5 + 5;
                Menu_DrawCharacterName(gPartyMembers[index], x, 5);
                Menu_DrawCharacterLevel(gPartyMembers[index], x, 6);
                Menu_DrawCharacterHp(gPartyMembers[index], x, 7);
                Menu_DrawCharacterMp(gPartyMembers[index], x, 8);
            }
        }
        Menu_DrawLayout(gMenuOverviewLayout);
        Menu_DrawDecimal(MENU_TEXT_ADDR(25, 14), gPartyGold, 11);
        Menu_DrawSceneNameWithClosingBracket(MENU_TEXT_ADDR(6, 14), gSceneId, 11);
        break;
    }
    /* Character status */
    case 1:
    {
        index = Menu_GetSelectedPartySlot();
        value = gPartyMembers[index];
        if (value != 0)
            value--;
        character = &gPartyCharacters[value];
        /* The reference reloads the member byte between drawing calls. */
        Menu_DrawCharacterName(gPartyMembers[index], 5, 1);
        Menu_DrawCharacterLevel(gPartyMembers[index], 5, 2);
        Menu_DrawCharacterHp(gPartyMembers[index], 5, 3);
        dest = MENU_TEXT_ADDR(9, 3);
        *dest = 0xB27E;
        dest += 3;
        Menu_DrawDefaultNumber3((s16)character->maxHp, dest);
        Menu_DrawCharacterMp(gPartyMembers[index], 5, 4);
        /* Move from the HP number to the next row's separator. */
        dest += 32 - 3;
        *dest = 0xB27E;
        dest += 3;
        Menu_DrawDefaultNumber3((s16)character->maxMp, dest);
        Menu_ClearTextRectInline(20, 1, 8, 4);
        Menu_DrawLayout(gMenuExperienceLayout);
        if (character->level < PARTY_MAX_INTERNAL_LEVEL)
        {
            Menu_DrawDecimal(MENU_TEXT_ADDR(28, 1), character->experience, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(28, 3), character->nextLevelExperience, 11);
        }
        else
        {
            u32 experience = Party_GetNextLevelExperience(character->level - 1);

            /* The status page writes capped experience back to the record. */
            character->experience = experience;
            Menu_DrawDecimal(MENU_TEXT_ADDR(28, 1), experience, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(28, 3), 0, 11);
        }
        Menu_DrawCharacterPanel(gMenuPhase);
        break;
    }
    /* Inventory and destinations */
    case 2:
    {
        index = Menu_GetSelectedPartySlot();
        if (index != 0xFF)
        {
            value = gPartyMembers[index];
            if (value != 0)
                value--;
            character = &gPartyCharacters[value];
            Menu_DrawCharacterName(gPartyMembers[index], 5, 1);
            Menu_DrawCharacterLevel(gPartyMembers[index], 5, 2);
            Menu_DrawCharacterHp(gPartyMembers[index], 5, 3);
            dest = MENU_TEXT_ADDR(9, 3);
            *dest = 0xB27E;
            dest += 3;
            Menu_DrawDefaultNumber3((s16)character->maxHp, dest);
            Menu_DrawCharacterMp(gPartyMembers[index], 5, 4);
            dest += 0x3A / 2;
            *dest = 0xB27E;
            dest += 3;
            Menu_DrawDefaultNumber3((s16)character->maxMp, dest);
        }
        Menu_DrawLayout(gMenuItemHeaderLayout);
        if (gMenuPhase > 10)
        {
            Menu_DrawItemName(0xB7, 16, 3, 13);
            Menu_DrawDestinations();
        }
        else
        {
            Menu_DrawInventory();
            if (gMenuHintId == 0)
            {
                if (gMenuPhase == 10)
                    Menu_ShowHint(0x26);
                else
                    Menu_ShowHint(0x28 + gMenuInventoryItems[gMenuPhase]);
            }
        }
        break;
    }
    /* Equipment and stat preview */
    case 3:
    {
        u16 hint;
        u32 selectedItem;

        index = Menu_GetSelectedPartySlot();
        value = gPartyMembers[index];
        if (value != 0)
            value--;
        character = &gPartyCharacters[value];
        Menu_DrawCharacterName(gPartyMembers[index], 5, 1);
        Menu_DrawCharacterLevel(gPartyMembers[index], 5, 2);
        Menu_DrawCharacterHp(gPartyMembers[index], 5, 3);
        Menu_DrawCharacterMp(gPartyMembers[index], 5, 4);
        Menu_ClearTextRectInline(5, 6, 3, 10);
        Menu_ClearTextRectInline(13, 6, 3, 4);
        Menu_ClearTextRectInline(17, 4, 11, 12);
        Menu_ClearTextRectInline(16, 1, 12, 4);
        Menu_DrawLayout(gMenuEquipmentStatsLayout);
        if (gMenuPhase <= 5)
        {
            switch (gMenuPhase)
            {
            case 0:
                selectedItem = character->equipSlot1;
                break;
            case 1:
                selectedItem = character->equipSlot2;
                break;
            case 2:
                selectedItem = character->equipSlot3;
                break;
            case 3:
                selectedItem = character->equipSlot4;
                break;
            case 4:
                selectedItem = character->equipSlot5;
                break;
            case 5:
                selectedItem = character->equipSlot6;
                break;
            }
            if (selectedItem == 0)
            {
                hint = gMenuPhase + 30;
                if (gMenuPhase == 5)
                    hint--;
                Menu_ShowHint(hint);
            }
            else
                Menu_ShowHint(selectedItem + 40);
            Menu_DrawLayout(gMenuItemHeaderLayout);
            Menu_DrawLayout(gMenuEquipmentSlotLabels);
            Menu_DrawItemName(character->equipSlot1, 20, 4, 11);
            Menu_DrawItemName(character->equipSlot2, 20, 6, 11);
            Menu_DrawItemName(character->equipSlot3, 20, 8, 11);
            Menu_DrawItemName(character->equipSlot4, 20, 10, 11);
            Menu_DrawItemName(character->equipSlot5, 20, 12, 11);
            Menu_DrawItemName(character->equipSlot6, 20, 14, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 6), character->atc, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 8), character->def, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 10), character->agl, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 12), character->men, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 14), character->res, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(14, 6), character->luc, 11);
            Menu_DrawDecimal(MENU_TEXT_ADDR(14, 8), character->noa, 11);
        }
        else
        {
            switch (gMenuSavedSelections[gMenuPage])
            {
            case 0: value = character->equipSlot1; break;
            case 1: value = character->equipSlot2; break;
            case 2: value = character->equipSlot3; break;
            case 3: value = character->equipSlot4; break;
            case 4: value = character->equipSlot5; break;
            default: value = character->equipSlot6; break;
            }
            Menu_DrawItemName(value, 20, 3, 12);
            dest = MENU_TEXT_ADDR(17, 3);
            value = gMenuSavedSelections[gMenuPage];
            if (value == 5)
                value = 4;
            value = value * 2 + 0xF4;
            Menu_DrawGlyph(dest++, value++, 11);
            Menu_DrawGlyph(dest, value, 11);
            Menu_BuildEquipmentCandidates();
            /* The preview helper updates these colors after the reset. */
            for (value = 0; value <= 6; value++)
                gMenuStatPreviewPalettes[value] = 11;
            Menu_PreviewSelectedEquipment();
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 6), character->baseAtc + gPartyEquipmentAtcBonus, gMenuStatPreviewPalettes[0]);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 8), character->baseDef + gPartyEquipmentDefBonus, gMenuStatPreviewPalettes[1]);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 10), character->baseAgl + gPartyEquipmentAglBonus, gMenuStatPreviewPalettes[2]);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 12), character->baseMen + gPartyEquipmentMenBonus, gMenuStatPreviewPalettes[3]);
            Menu_DrawDecimal(MENU_TEXT_ADDR(7, 14), character->baseRes + gPartyEquipmentResBonus, gMenuStatPreviewPalettes[4]);
            Menu_DrawDecimal(MENU_TEXT_ADDR(14, 6), character->baseLuc + gPartyEquipmentLucBonus, gMenuStatPreviewPalettes[5]);
            Menu_DrawDecimal(MENU_TEXT_ADDR(14, 8), character->baseNoa + gPartyEquipmentNoaBonus, gMenuStatPreviewPalettes[6]);
            value = gMenuEquipmentCandidates[gMenuPhase - 6];
            if (value == 0xFF)
                Menu_ShowHint(0x28);
            else
                Menu_ShowHint(value + 0x28);
        }
        break;
    }
    /* Field-skill HP/MP refresh */
    case 4:
    {
        u8 x;

        for (index = 0; index <= 4; index++)
        {
            if (gPartyMembers[index] != PARTY_NO_MEMBER)
            {
                x = index * 5 + 5;
                Menu_DrawCharacterHp(gPartyMembers[index], x, 7);
                Menu_DrawCharacterMp(gPartyMembers[index], x, 8);
            }
        }
        break;
    }
    /* Save menu */
    case 5:
    {
        for (index = 0; index <= 2; index++)
        {
            if (gMenuSavedSelections[gMenuPage] == index)
                value = 13;
            else
                value = 11;
            Menu_SetTextVisible(gMenuSaveOptionTexts[index], value, 1);
        }
        for (; index <= 4; index++)
        {
            if (gMenuPhase > 5)
            {
                if (gMenuPhase == index + 3)
                    value = 13;
                else
                    value = 11;
                Menu_SetTextVisible(gMenuSaveOptionTexts[index], value, 1);
            }
            else
                Menu_SetTextVisible(gMenuSaveOptionTexts[index], value, 0);
        }
        if (gSaveIoState == 0xFE)
            Menu_DrawSaveSlots();
        break;
    }
    /* Formation and tactics */
    case 6:
    {
        u8 x;

        for (index = 0; index <= 1; index++)
        {
            if (gMenuSavedSelections[gMenuPage] == index)
                value = 13;
            else
                value = 11;
            Menu_SetTextVisible(gMenuFormationOptionTexts[index], value, 1);
        }
        if (gMenuSavedSelections[gMenuPage] == 1 && gMenuPhase != 1)
        {
            for (index = 0; index <= 3; index++)
            {
                if (index == gMenuTacticsAction)
                    value = 13;
                else
                    value = 11;
                Menu_SetTextVisible(gMenuFormationOptionTexts[index + 2], value, 1);
            }
            index = gPartyMembers[gMenuTacticsPartySlot];
            if (index != 0)
                index--;
            value = gPartyCharacters[index].tacticsAction;
            Menu_SetTextVisible(gMenuFormationOptionTexts[value + 6], 15, 1);
            /* The tenth menu record displays the selected tactics action. */
            gMenuEntries[9].flags |= MENU_ENTRY_HIGHLIGHT;
            {
                u32 actionTile = value * 4 + 0x3A4;
                gMenuEntries[9].tile = actionTile;
            }
            Menu_ClearTextRectInline(16, 7, 11, 2);
            if (value == 2)
            {
                value = gPartyCharacters[index].tacticsActionId;
                if (Menu_CanReserveTacticsItem(index, value))
                    Menu_DrawItemName(value, 16, 7, 11);
                else
                    Menu_DrawItemName(value, 16, 7, 12);
                Menu_ClearTextRectInline(26, 7, 3, 2);
            }
            else if (value == 1)
            {
                value = gPartyCharacters[index].tacticsActionId;
                Menu_DrawSkillName(value, 16, 7, 11);
            }
        }
        else if (gMenuSavedSelections[gMenuPage] == 0)
        {
            if (gMenuPhase != 0)
            {
                /* The formation header ends at the first empty slot. */
                for (index = 0; index <= 4; index++)
                {
                    if (gPartyMembers[index] == PARTY_NO_MEMBER)
                        break;
                    {
                        u8 characterId = gPartyMembers[index];
                        x = index * 5 + 5;
                        Menu_DrawCharacterName(characterId, x, 1);
                    }
                    Menu_DrawCharacterLevel(gPartyMembers[index], x, 2);
                    Menu_DrawCharacterHp(gPartyMembers[index], x, 3);
                    Menu_DrawCharacterMp(gPartyMembers[index], x, 4);
                }
            }
            else
                Menu_ClearTextRectInline(5, 1, 24, 4);
        }
        break;
    }
    }
}

/**
 * @brief 绘制带左右括号的菜单提示，并清理提示行剩余字形
 *
 * @note text 以 FF 结束，FE 消耗一个扩展字节；文字使用传入 palette，括号和清空使用 palette 11。
 * @address 0x0800BEE4
 */
void Menu_DrawHintText(const u8 *text, u8 palette)
{
    u16 *dest = MENU_TEXT_ADDR(2, 17);
    u16 length;
    u16 glyph;

    Menu_DrawGlyph(dest++, 0xC8, 11);
    length = 1;
    while (*text != 0xFF)
    {
        glyph = *text++;
        if (glyph == 0xFE)
        {
            glyph = (*text << 8) | 0xFE;
            text++;
            Menu_DrawGlyph(dest++, glyph, palette);
        }
        else
            Menu_DrawGlyph(dest++, glyph, palette);
        length++;
    }
    Menu_DrawGlyph(dest++, 0xC9, 11);
    length++;
    while (length <= 28)
    {
        Menu_DrawGlyph(dest++, 0, 11);
        length++;
    }
}

/**
 * @brief 初始化十五条菜单记录
 *
 * @note 前五条对应有效队员，skipLabels=0 时建立主菜单标签。
 * @address 0x0800BF5C
 */
void Menu_InitEntries(u8 skipLabels)
{
    u16 index;

    for (index = 0; index <= 14; index++)
    {
        if (index <= 4 && gPartyMembers[index] != PARTY_NO_MEMBER)
        {
            gMenuEntries[index].x = index * 40 + 72;
            gMenuEntries[index].y = 8;
            gMenuEntries[index].flags = MENU_ENTRY_ACTIVE;
            gMenuEntries[index].tile = index * 48 + 0x200;
            gMenuEntries[index].spriteNodeIndex = index + 113;
        }
        else
        {
            gMenuEntries[index].x = 0;
            gMenuEntries[index].y = 0;
            gMenuEntries[index].flags = 0;
            gMenuEntries[index].spriteNodeIndex = 0;
        }
        gMenuEntries[index].blinkCounter = 0;
        gMenuEntries[index].transitionFrames = 0;
    }
    if (skipLabels == 0)
    {
        Menu_CreateLabelEntries(0);
        gMenuEntries[5].flags |= MENU_ENTRY_HIGHLIGHT;
    }
}

/**
 * @brief 将数值写成右对齐的三位菜单数字
 *
 * @note 数值和 paletteBits 使用低十六位；dest 指向个位，后两次写入向左；paletteBits 是已左移的调色板位。
 * @address 0x0800BFF8
 */
void Menu_DrawNumber3(s32 inputValue, u16 *dest, u32 inputPalette)
{
    u16 tiles[3];
    /* Keep the signed value and the 16-bit subtraction state as separate views. */
    u32 highValue = (u32)inputValue << 16;
    u16 paletteBits = inputPalette;
    s16 remaining = highValue >> 16;
    s32 value = (s32)highValue >> 16;
    u16 digit;

    if (value == 0)
    {
        tiles[0] = paletteBits + 0x27F;
        tiles[1] = paletteBits + 0x27F;
        tiles[2] = paletteBits + 0x25A;
        *dest-- = tiles[2];
    }
    else
    {
        u16 *previous;

        digit = 0;
        previous = dest - 1;
        if (value >= 0)
        {
            do
            {
                remaining = (s16)remaining - 100;
                digit++;
            } while ((s16)remaining >= 0);
        }
        remaining = (s16)remaining + 100;
        digit--;
        if (digit == 0)
            digit = 0x25;
        {
            u32 base;

            tiles[0] = digit + (base = paletteBits + 0x25A);
        }
        digit = 0;
        while ((s16)remaining >= 0)
        {
            remaining = (s16)remaining - 10;
            digit++;
        }
        remaining = (s16)remaining + 10;
        digit--;
        if (digit == 0 && tiles[0] == 0xB27F)
            digit = 0x25;
        {
            u32 base;

            tiles[1] = digit + (base = paletteBits + 0x25A);
            tiles[2] = remaining + base;
        }
        *dest = tiles[2];
        dest = previous;
    }
    *dest-- = tiles[1];
    *dest = tiles[0];
}

/**
 * @brief 建立光标及队伍头像精灵，并初始化菜单演员
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0800C0D8
 */
void Menu_InitSprites(void)
{
    struct SpriteNode *node = &gSpriteNodes[112];
    u16 i;
    u16 attr0;
    u16 attr1;
    u16 attr2;

    attr0 = gMenuCursor.y;
    attr1 = ((gMenuCursor.x - 32) & 0x1FF);
    attr1 += 0x8000;
    attr2 = 0x21C0;
    Sprite_InitNode(node, 1, attr0, attr1, attr2);
    gSpriteDrawOrder[0] = node;
    Actor_LoadAnimation(0x4C, 0, 9);
    for (i = 0; i <= 4; i++)
    {
        node++;
        if (gPartyMembers[i] != PARTY_NO_MEMBER)
        {
            attr0 = 8;
            attr1 = 0x8000 + (40 + i * 40);
            attr2 = ((i + 3) << 12) + ((0x200 + i * 48) & 0x3FF);
            Sprite_InitNode(node, 1, attr0, attr1, attr2);
            gSpriteDrawOrder[i + 1] = node;
        }
        Actor_InitMenu(i);
    }
}

/**
 * @brief 活动菜单逐帧更新输入、菜单演员、条目精灵、游戏时间及绘制队列
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0800C194
 */
void Menu_UpdateFrame(void)
{
    struct ActorState *actor;
    u16 index;
    u16 drawIndex;
    s32 x;
    s32 height;

    if (gMenuState > 0x33)
        return;
    if (gMenuState <= 12)
        return;
    Menu_UpdateInputAndCursor();
    for (index = 19; index <= 23; index++)
    {
        struct ActorState *actors = gActorStates;

        actor = &actors[index];
        if (actor->scriptEntryOrMenuState != 0x80)
        {
            Actor_UpdateAnimation(index);
            x = Actor_GetRenderX(actor);
            height = (s16)Actor_GetRenderHeight(actor);
            Sprite_QueueChain(x, (u16)actor->y, actor->spriteSlot, height, actor->flags);
            if (actor->customAnimationTimer == 0xFF)
            {
                actor->customAnimationTimer = 0;
                actor->scriptEntryOrMenuState = 0x80;
                if (actor->spriteSlot != 0)
                    Sprite_FreeChain(&gSpriteNodes[actor->spriteSlot]);
            }
        }
    }
    Menu_UpdateEntrySprites();
    if (gMenuPage <= 1)
        Menu_DrawPlayTime(MENU_TEXT_ADDR(12, 12), gPlayTimeFrames, 11);
    drawIndex = 0;
    for (; gSpriteDrawOrder[drawIndex] != 0; drawIndex++)
        ;
    gSpriteDrawOrder[drawIndex] =
        (struct SpriteNode *)((u32)gSpriteNodes + 112 * sizeof(struct SpriteNode));
    for (index = 0; index <= 14; index++)
    {
        if ((gMenuEntries[index].flags & 0xC0) == 0x80)
        {
            for (; gSpriteDrawOrder[drawIndex] != 0; drawIndex++)
                ;
            gSpriteDrawOrder[drawIndex] = &gSpriteNodes[gMenuEntries[index].spriteNodeIndex];
        }
    }
}

