/**
 * @brief 处理八个菜单页的输入、光标插值、滚动、确认、取消、队形及战术提交
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。 当前保留空函数，以上为原 ROM 行为。
 * @address 0x0800C2F8
 */
void Menu_UpdateInputAndCursor(void)
{
}
#endif
INCLUDE_ASM("asm/nonmatchings/menu", Menu_UpdateInputAndCursor);

/**
 * @brief 设置指定队伍条目的位置、隐藏和闪烁状态
 *
 * @note 三种布局与三种可见状态。
 * @address 0x0800E170
 */
void Menu_SetPartyEntryState(u8 mode, u8 state, u8 position)
{
    switch (mode)
    {
    case 0:
    {
        gMenuEntries[position].x = position * 40 + 0x48;
        gMenuEntries[position].y = 8;
        break;
    }
    case 1:
    {
        gMenuEntries[position].x = 0x28;
        gMenuEntries[position].y = 8;
        break;
    }
    case 2:
    {
        gMenuEntries[position].x = 0x30;
        gMenuEntries[position].y = 0x10;
        break;
    }
    }

    switch (state)
    {
    case 2:
    {
        gMenuEntries[position].flags &= ~MENU_ENTRY_HIDDEN;
        gMenuEntries[position].flags &= ~MENU_ENTRY_BLINK;
        break;
    }
    case 1:
    {
        gMenuEntries[position].flags &= ~MENU_ENTRY_HIDDEN;
        gMenuEntries[position].flags |= MENU_ENTRY_BLINK;
        break;
    }
    case 0:
    {
        gMenuEntries[position].flags |= MENU_ENTRY_HIDDEN;
        gMenuEntries[position].flags &= ~MENU_ENTRY_BLINK;
        break;
    }
    }
}

/**
 * @brief 光标移到目标后设置页面绘制模式、标签高亮、提示及战术列表，再重绘内容
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0800E244
 */
void Menu_OnCursorMoveFinished(void)
{
    gMenuCursor.flags |= 1;
    gMenuCursor.x = gMenuCursor.targetX;
    gMenuCursor.y = gMenuCursor.targetY;
    switch (gMenuPage)
    {
    case 0:
        if (gMenuPhase != 0)
        {
            gMenuEntries[gMenuPhase - 1].flags |= 1;
            Menu_ShowHintWithPalette(1, 11);
            Menu_CreateLabelEntries(1);
        }
        else
        {
            Menu_ShowHintWithPalette(0, 11);
            Menu_CreateLabelEntries(0);
            gMenuEntries[5].flags |= 8;
        }
        break;
    case 1:
        sMenuDrawMode = 0;
        if (gMenuSavedSelections[0] == 0)
        {
            Menu_CreateLabelEntries(0);
            Menu_ShowHintWithPalette(gMenuPhase + 2, 11);
        }
        else
        {
            Menu_CreateLabelEntries(1);
            Menu_ShowHintWithPalette(gMenuPartyActionHintIds[gMenuPhase], 11);
        }
        Menu_SetOtherEntriesVisible(gMenuSavedSelections[0] - 1, 1);
        gMenuEntries[gMenuPhase + 6].flags |= 8;
        break;
    case 2:
        sMenuDrawMode = 1;
        break;
    case 3:
        sMenuDrawMode = 2;
        break;
    case 4:
        sMenuDrawMode = 3;
        break;
    case 5:
        sMenuDrawMode = 4;
        if (gMenuPhase <= 3)
        {
            u8 slot = gMenuSavedSelections[0] - 1;

            Menu_DrawFieldSkillList(gPartyMembers[slot], gMenuSavedSelections[gMenuPage]);
        }
        else
        {
            Menu_ClearTextBufferInline(MENU_TEXT_ADDR(2, 15), 28, 2);
            gMenuHintId = 0x26;
        }
        break;
    case 6:
        switch (gMenuPhase)
        {
        case 0:
            gMenuHintId = 0x14;
            break;
        case 1:
            gMenuHintId = 0x15;
            break;
        case 2:
            gMenuHintId = 0x16;
            break;
        default:
            gMenuHintId = 0;
            switch (gMenuSavedSelections[gMenuPage])
            {
            case 0:
                if (gMenuPhase > 5)
                    gMenuHintId = 0x17;
                else
                    gMenuHintId = 0x14;
                break;
            case 1:
                if (gMenuPhase > 5)
                    gMenuHintId = 0x13;
                else
                    gMenuHintId = 0x15;
                break;
            case 2:
                gMenuHintId = 0x13;
                break;
            }
            break;
        }
        if (gMenuHintId != 0)
            Menu_ShowHintWithPalette(gMenuHintId, 11);
        sMenuDrawMode = 5;
        break;
    case 7:
        if (gMenuPhase == 0)
            gMenuHintId = 0x10;
        else if (gMenuPhase == 1)
            gMenuHintId = 0x11;
        else if (gMenuPhase <= 6)
        {
            if (gMenuFormationFirstSelection == 0)
                gMenuHintId = 1;
            else
                gMenuHintId = 0x12;
        }
        else
        {
            if (gMenuPhase <= 11)
                gMenuHintId = 0x1C0;
            else if (gMenuPhase <= 15)
            {
                switch (gMenuPhase)
                {
                case 12:
                    gMenuHintId = 0x1C1;
                    break;
                case 13:
                    gMenuHintId = 0x1C2;
                    break;
                case 14:
                    gMenuHintId = 0x1C3;
                    break;
                case 15:
                    gMenuHintId = 0x1C4;
                    break;
                }
            }
            if (gMenuPhase <= 15)
            {
                Menu_CreateLabelEntries(2);
                gMenuEntries[gMenuTacticsAction + 5].flags |= 8;
            }
            else if (gMenuTacticsAction == 1)
            {
                Menu_DrawTacticsSkillList();
                gMenuHintId = 0x128 + gMenuTacticsActionId;
            }
            else
            {
                Menu_DrawTacticsItemList();
                gMenuHintId = gMenuTacticsActionId + 0x28;
            }
        }
        {
            u16 hint = gMenuHintId;
            if (hint != 0)
                Menu_ShowHintWithPalette(hint, 11);
        }
        sMenuDrawMode = 6;
        break;
    }
    Menu_RefreshPartyHeaders();
    Menu_DrawContents();
    switch (gMenuPage)
    {
    case 5:
        Menu_ShowHintWithPalette(gMenuHintId, 11);
        break;
    case 3:
        if (gMenuPhase > 10)
            Menu_ShowHintWithPalette(0x1B, 11);
        break;
    }
}

/**
 * @brief 保存旧页选择、恢复新页选择并开始八次光标更新
 *
 * @note FF 保持当前页。
 * @address 0x0800E668
 */
void Menu_TransitionToPage(u8 page)
{
    const struct MenuCursorPosition *position;

    if (page != 0xFF)
    {
        gMenuSavedSelections[gMenuPage] = gMenuPhase;
        gMenuPage = page;
        gMenuPhase = gMenuSavedSelections[gMenuPage];
        Menu_SetRecoveryAnimation(0xFF, 0);
        sMenuHeaderRefreshPending = 1;
    }

    gMenuCursor.originX = gMenuCursor.x;
    gMenuCursor.originY = gMenuCursor.y;

    if (gTitlePresentationStage != 0)
        goto useTitleLayout;
    if (gMenuContext != 0)
        goto useContextLayout;
    position = gMenuCursorPositionTables[gMenuPage] + gMenuPhase;
    goto layoutReady;
useContextLayout:
    position = gMenuContextCursorPositionTables[gMenuPage] + gMenuPhase;
    goto layoutReady;
useTitleLayout:
    position = gTitleMenuCursorPositionTables[gMenuPage] + gMenuPhase;
layoutReady:
    gMenuCursor.targetX = position->x;
    gMenuCursor.targetY = position->y;
    gMenuCursor.transitionFrames = 8;
    gMenuCursor.flags &= ~1;
}

/**
 * @brief 将队伍条目移至概览、选中角色或队形坐标，保存起点并设八次插值
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0800E71C
 */
void Menu_MovePartyEntry(u8 position, u8 mode)
{
    struct MenuEntry *entry;
    u8 characterId;
    u8 index;
    u32 tableIndex;
    u16 targetX;
    u16 targetY;

    if (position == 0xFF)
        return;

    entry = &gMenuEntries[position];
    entry->originX = entry->x;
    entry->originY = entry->y;

    switch (mode)
    {
    case 1:
        targetX = 0x28;
        targetY = 8;
        break;
    case 0:
        targetX = position * 40 + 0x48;
        targetY = 8;
        break;
    default:
        characterId = gPartyMembers[position];
        index = 0;
        while (index <= 4 && gPartyCharacterSlots[index] != characterId)
            index++;
        /* Keep the two halfword address calculations; derive their layout from the record. */
        tableIndex = (index + 2) * (s32)(sizeof(struct MenuCursorPosition) / sizeof(u16));
        targetX = ((const u16 *)gMenuFormationPageCoordinates)[tableIndex] + 0x18;
        tableIndex += offsetof(struct MenuCursorPosition, y) / sizeof(u16);
        targetY = ((const u16 *)gMenuFormationPageCoordinates)[tableIndex] + 8;
        break;
    }

    entry->targetX = targetX;
    entry->targetY = targetY;
    entry->transitionFrames = 8;
}

/**
 * @brief 插值十五条活动条目，处理闪烁和高亮，再写软件精灵属性
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0800E7BC
 */
void Menu_UpdateEntrySprites(void)
{
    struct MenuEntry *entry = gMenuEntries;
    struct SpriteNode *node;
    u8 t;
    u16 index;
    u16 dx;
    u16 dy;
    u16 tile;

    for (index = 0; index <= 14; index++, entry++)
    {
        if (!(entry->flags & MENU_ENTRY_ACTIVE))
            continue;

        if (entry->transitionFrames != 0)
        {
            entry->transitionFrames--;
            if (entry->transitionFrames != 0)
            {
                dx = entry->targetX - entry->originX;
                dy = entry->targetY - entry->originY;
                t = 8 - entry->transitionFrames;
                entry->x = entry->originX + ((dx * t) >> 3);
                entry->y = entry->originY + ((dy * t) >> 3);
            }
            else
            {
                entry->x = entry->targetX;
                entry->y = entry->targetY;
            }
        }

        if (entry->flags & MENU_ENTRY_BLINK)
        {
            if (entry->flags & MENU_ENTRY_FIXED_SELECTED_FRAME)
            {
                tile = entry->tile + 0x60;
            }
            else
            {
                entry->blinkCounter++;
                tile = entry->tile + ((entry->blinkCounter & 8) << 1);
            }
        }
        else
        {
            tile = entry->tile;
        }

        node = &gSpriteNodes[entry->spriteNodeIndex];
        {
            u32 attr0 = node->attr0 & 0xFF00;

            attr0 += (u8)entry->y;
            node->attr0 = attr0;
        }
        node->attr1 = (node->attr1 & 0xFE00) + ((entry->x - 32) & 0x1FF);
        if (entry->flags & MENU_ENTRY_LABEL_PALETTE)
        {
            if (entry->flags & MENU_ENTRY_HIGHLIGHT)
                node->attr2 = (node->attr2 & 0xC00) + tile - 0x6000;
            else
                node->attr2 = (node->attr2 & 0xC00) + tile - 0x5000;
        }
        else
        {
            node->attr2 = (node->attr2 & 0xFC00) + tile;
        }
    }
}

/**
 * @brief 将累计游戏帧数绘制为三位小时和两位分钟
 *
 * @note 按每秒六十帧换算；五个数字使用双行字形，中间分隔格保留。
 * @address 0x0800E8F8
 */
void Menu_DrawPlayTime(u16 *dest, u32 frames, u8 palette)
{
    u32 remaining = frames;
    u8 hundredsHours = Menu_ExtractDecimalDigit((s32 *)&remaining, 21600000);
    u8 tensHours = Menu_ExtractDecimalDigit((s32 *)&remaining, 2160000);
    u8 hours = Menu_ExtractDecimalDigit((s32 *)&remaining, 216000);
    u8 tensMinutes = Menu_ExtractDecimalDigit((s32 *)&remaining, 36000);
    u8 minutes = Menu_ExtractDecimalDigit((s32 *)&remaining, 3600);

    Menu_DrawGlyphInline(dest++, hundredsHours + 0xA2, palette);
    Menu_DrawGlyphInline(dest++, tensHours + 0xA2, palette);
    Menu_DrawGlyphInline(dest++, hours + 0xA2, palette);
    dest++;
    Menu_DrawGlyphInline(dest++, tensMinutes + 0xA2, palette);
    Menu_DrawGlyphInline(dest, minutes + 0xA2, palette);
}

/**
 * @brief 绘制最多八位、抑制前导零的右对齐十进制数
 *
 * @note dest 指向个位；零仍绘制一位，未使用的左侧格不自动清除；palette 是调色板编号。
 * @address 0x0800EAE4
 */
void Menu_DrawDecimal(u16 *dest, u32 value, u8 palette)
{
    u8 visibleDigits = 0;
    s16 index;
    u8 digit;

    for (index = 7; index >= 0; index--)
    {
        digit = Menu_ExtractDecimalDigit((s32 *)&value, gMenuDecimalPowers[index]);
        if (visibleDigits != 0 || digit != 0 || index == 0)
        {
            visibleDigits++;
            Menu_DrawGlyphInline(dest - index, digit + 0xA2, palette);
        }
    }
}

/**
 * @brief 从布局表建立十条标签记录和对应软件精灵，停用未使用记录
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0800EB98
 */
void Menu_CreateLabelEntries(u8 layoutId)
{
    const u8 *layout = gMenuLabelLayouts[layoutId];
    u8 count = layout[0];
    u8 index;
    struct MenuEntry *entry;
    u32 y;

    layout++;
    entry = gMenuWidgetEntries;
    index = 0;
    while (index < count)
    {
        entry->x = layout[0];
        layout++;
        y = layout[0];
        entry->y = y;
        layout++;
        entry->flags = 0x84;
        entry->tile = 0x380 + layout[0];
        layout++;
        entry->spriteNodeIndex = index + 0x76;
        entry->blinkCounter = 0;
        entry->transitionFrames = 0;
        Sprite_InitNode(&gSpriteNodes[entry->spriteNodeIndex], 1,
            y, entry->x | 0x4000, (entry->tile & 0x3FF) | 0xB000);
        entry++;
        index++;
    }
    while (index <= 9)
    {
        entry->flags = 0;
        entry++;
        index++;
    }
}

static inline u8 Menu_GetSelectedPartySlotInline(void)
{
    return gMenuSavedSelections[0] - 1;
}

/**
 * @brief 绘制当前角色的属性装备面板或技能面板
 *
 * @note panel=0 显示属性和六槽装备，非零显示技能和特殊技能；未选队员时不清屏。
 * @note 普通技能遇到 FF 即结束；MP 消耗查询在名称绘制后重新读取当前队伍选择。
 * @address 0x0800EC54
 */
void Menu_DrawCharacterPanel(u8 panel)
{
    u8 value;
    u16 skillIndex;
    struct PartyCharacter *character;

    value = gMenuSavedSelections[0] - 1;
    if (value == 0xFF)
        return;

    value = gPartyMembers[value];
    if (value != 0)
        value--;
    character = &gPartyCharacters[value];

    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(2, 6), 28, 12);
    if (panel == 0)
    {
        Menu_DrawLayoutInline(gMenuCharacterStatsLayout);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 6), character->atc, 11);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 8), character->def, 11);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 10), character->agl, 11);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 12), character->men, 11);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 14), character->res, 11);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 16), character->luc, 11);
        Menu_DrawDecimal(MENU_TEXT_ADDR(14, 6), character->noa, 11);
        Menu_DrawLayoutInline(gMenuCharacterEquipmentLayout);
        Menu_DrawItemNameInline(character->equipSlot1, 20, 6, 11);
        Menu_DrawItemNameInline(character->equipSlot2, 20, 8, 11);
        Menu_DrawItemNameInline(character->equipSlot3, 20, 10, 11);
        Menu_DrawItemNameInline(character->equipSlot4, 20, 12, 11);
        Menu_DrawItemNameInline(character->equipSlot5, 20, 14, 11);
        Menu_DrawItemNameInline(character->equipSlot6, 20, 16, 11);
        *MENU_TEXT_ADDR(26, 19) = 0xB25B;
    }
    else
    {
        for (skillIndex = 0; skillIndex < PARTY_SKILL_SLOT_COUNT; skillIndex++)
        {
            value = character->skills[skillIndex];
            if (value == 0xFF)
                break;
            Menu_DrawSkillNameInline(value, (skillIndex & 1) * 13 + 3,
                (skillIndex & 0xFE) + 6, 11);
            {
                s32 x = (skillIndex & 1) * 13 + 13;
                u16 *dest = MENU_TEXT_ADDR(x, (skillIndex & ~1) + 6);

                Menu_DrawDecimal(dest,
                    Menu_GetAdjustedSkillMpCost(gPartyMembers[Menu_GetSelectedPartySlotInline()], value), 14);
            }
        }
        value = character->specialSkill;
        if (value != 0xFF)
        {
            Menu_DrawSkillNameInline(value, (skillIndex & 1) * 13 + 3,
                (skillIndex & 0xFE) + 6, 11);
            {
                s32 x = (skillIndex & 1) * 13 + 13;
                u16 *dest = MENU_TEXT_ADDR(x, (skillIndex & ~1) + 6);

                Menu_DrawGlyphInline(dest, 0xCF, 14);
            }
        }
        *MENU_TEXT_ADDR(26, 19) = 0xB25C;
    }

    *MENU_TEXT_ADDR(27, 19) = 0xB27E;
    *MENU_TEXT_ADDR(28, 19) = 0xB25C;
}

/**
 * @brief 绘制可在场景中使用的技能及 MP 消耗，保存当前选中技能
 *
 * @note 无施术者时显示 Nall 技能。
 * @address 0x0800F128
 */
void Menu_DrawFieldSkillList(u8 characterId, u8 selection)
{
    u16 index;
    u16 entryIndex;
    u8 skill;
    u8 palette;
    u8 selectedSkill;
    struct PartyCharacter *character;

    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(2, 9), 28, 8);
    selectedSkill = 0;
    if (gMenuSavedSelections[0] == 0)
    {
        skill = 0x3E;
        if (selection == 0)
        {
            selectedSkill = skill;
            palette = 13;
        }
        else
            palette = 11;
        if ((gPlayerFieldFlags & 0x80) == 0)
            palette = 12;
        Menu_DrawSkillNameInline(skill, 3, 10, palette);
    }
    else
    {
        skill = characterId;
        if (skill != 0)
            skill--;
        character = &gPartyCharacters[skill];
        entryIndex = 0;
        for (index = 0; index <= 7; index++)
        {
            const u8 *skills;
            s32 offset;

            skill = character->skills[index];
            if (skill == 0xFF)
                break;
            skills = (const u8 *)gPartySkillTable;
            offset = (skill - 1) * sizeof(struct PartySkillInfo) +
                     offsetof(struct PartySkillInfo, effectAndFlags);
            if ((skills[offset] & PARTY_SKILL_FIELD_DISABLED) != 0)
                continue;
            if (entryIndex == selection)
            {
                selectedSkill = skill;
                palette = 13;
            }
            else
                palette = 11;
            Menu_DrawSkillNameInline(skill, (entryIndex & 1) * 13 + 3, (entryIndex & 0xFE) + 10,
                                     palette);
            {
                s32 x = (entryIndex & 1) * 13 + 13;
                Menu_DrawDecimal(MENU_TEXT_ADDR(x, (entryIndex & ~1) + 10),
                                 Menu_GetAdjustedSkillMpCost(characterId, skill), 14);
            }
            entryIndex++;
        }
    }
    gMenuHintId = selectedSkill + 0x128;
    gMenuFieldSkillId = selectedSkill;
    if (gMenuPhase <= 3)
        Menu_DrawLayoutInline(gMenuFieldSkillLayout);
}

/**
 * @brief 绘制当前滚动窗口中的五个移动目的地
 *
 * @note 零编号为空项；根据当前选择高亮；地点 8 和 24 的颜色还受剧情标志限制。
 * @address 0x0800F3AC
 */
void Menu_DrawDestinations(void)
{
    u8 index;
    u8 sceneId;
    u8 palette;

    Menu_ClearTextRectInline(3, 6, 24, 10);
    for (index = 0; index <= 4; index++)
    {
        sceneId = gMenuDestinations[index + gMenuDestinationScroll];
        if (sceneId != 0)
        {
            s32 offset;

            {
                s32 selection = gMenuPhase - 11;

                palette = 11;
                if (selection == index)
                    palette = 13;
            }
            switch (sceneId)
            {
            case 8:
                if (EventFlags_GetMask(0x10D) == 0)
                    palette = 12;
                break;
            case 24:
                if (EventFlags_GetMask(0xFF) != 0)
                    palette = 12;
                break;
            }
            offset = (index * 2 + 6) * 32;
            Menu_DrawGlyphInline(MENU_TEXT_ADDR(8, 0) + offset, 0xC8, 11);
            Menu_DrawSceneNameWithClosingBracketInline(offset + (gScriptTextTilemap + 9), sceneId, palette);
        }
    }
}

/**
 * @brief 扫描库存并绘制两列十格物品窗口和数量
 *
 * @note 记录有库存的物品编号，零为空；更新库存起点，使用当前页面选择决定高亮。
 * @address 0x0800F4A8
 */
void Menu_DrawInventory(void)
{
    u8 itemId;
    u8 index;
    u8 quantity;

    Menu_ClearTextRectInline(3, 6, 24, 10);
    do {
    itemId = gMenuInventoryStartItem;
    if (itemId == 0)
        itemId = 1;
    index = 0;
    while (itemId <= 0xFD)
    {
        quantity = gPartyItemCounts[itemId];
        if (quantity != 0)
        {
            gMenuInventoryItems[index] = itemId;
            if (gMenuSavedSelections[gMenuPage] == index)
                Menu_DrawItemNameInline(itemId, (index & 1) * 13 + 3, (index & 0xFE) + 6, 13);
            else
                Menu_DrawItemNameInline(itemId, (index & 1) * 13 + 3, (index & 0xFE) + 6, 11);
            {
                u8 x = (index & 1) * 13 + 13;
                s32 column = x * 2;
                s32 row = (index & ~1) * 64;
                u16 *base = (u16 *)(row + (u32)MENU_TEXT_ADDR(0, 6));

                Menu_DrawDecimal((u16 *)(column + (u32)base), quantity, 12);
            }
            index++;
        }
        itemId++;
        if (index > 9)
            break;
    }
    while (index <= 9)
    {
        gMenuInventoryItems[index] = 0;
        index++;
    }
    gMenuInventoryStartItem = gMenuInventoryItems[0];
    } while (0);
}

/**
 * @brief 寻找当前十格库存窗口前后的各两个有库存物品
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0800F670
 */
void Menu_RefreshInventoryScrollItems(void)
{
    u8 itemId;
    u8 found;

    itemId = gMenuInventoryItems[0];
    gMenuInventoryPreviousItems[0] = 0;
    gMenuInventoryPreviousItems[1] = 0;
    itemId--;
    if (itemId != 0xFF)
    {
        found = 0;
        while (found <= 1 && itemId != 0)
        {
            if (gPartyItemCounts[itemId] != 0)
            {
                gMenuInventoryPreviousItems[found] = itemId;
                found++;
            }
            itemId--;
        }
    }

    gMenuInventoryNextItems[0] = 0;
    gMenuInventoryNextItems[1] = 0;
    itemId = gMenuInventoryItems[9];
    if (itemId != 0 && itemId != 0xFF)
    {
        itemId++;
        found = 0;
        while (found <= 1 && itemId <= 0xFD)
        {
            if (gPartyItemCounts[itemId] != 0)
            {
                gMenuInventoryNextItems[found] = itemId;
                found++;
            }
            itemId++;
        }
    }
}

/**
 * @brief 处理恢复道具、移动道具、逃离道具等选择，返回要显示的提示编号
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0800F70C
 */
u16 Menu_SelectInventoryItem(u8 itemId)
{
    const struct PartyItemInfo *item;

    gMenuItemRecoveryType = 0;
    if (itemId == 0)
    {
        Sound_PlaySfx(3, 0, 0);
        return 0x27;
    }
    item = &gPartyItemTable[itemId];
    switch (itemId)
    {
    case 0xB7:
        if (gSceneId == 0x38 || gSceneId == 0x3C || EventFlags_GetMask(0xFE) != 0 ||
            gSceneEncounterConfigId != 0)
        {
            Sound_PlaySfx(3, 0, 0);
            return 0x27;
        }
        Menu_SetTextTileInline(15, 5, 0x3F, 0xB240);
        Menu_SetTextTileInline(15, 16, 0x3F, 0xB240);
        Menu_ClearTextBufferInline(MENU_TEXT_ADDR(3, 6), 24, 10);
        gMenuSavedSelections[gMenuPage] = gMenuPhase;
        gMenuPhase = 11;
        Menu_TransitionToPage(0xFF);
        Sound_PlaySfx(1, 0, 0);
        return 0x1B;
    case 0xDD:
    case 0xDE:
    case 0xDF:
    case 0xE0:
        gMenuItemRecoveryType = item->equipmentTypeAndSet >> 4;
        gMenuItemRecoveryAmount = ((const u8 *)item)[6];
        gMenuSavedSelections[gMenuPage] = gMenuPhase;
        gMenuPhase = 10;
        if ((u8)(gMenuSavedSelections[0] - 1) == 0xFF)
        {
            u8 slot;

            gMenuSavedSelections[0] = 1;
            slot = Menu_GetSelectedPartySlot();
            if (slot != 0xFF)
                Menu_SetPartyEntryState(1, 1, slot);
            Menu_DrawContents();
        }
        Menu_TransitionToPage(0xFF);
        Sound_PlaySfx(1, 0, 0);
        return 0x26;
    case 0xE5:
        if (Menu_TryEscapeDungeon() == 0)
        {
            Sound_PlaySfx(3, 0, 0);
            return 0x27;
        }
        Party_RemoveItem(gMenuInventoryItems[gMenuSavedSelections[gMenuPage]], 1);
        return 0x10D;
    case 0xEA:
        if (gSceneEncounterConfigId != 0 && EventFlags_GetMask(0xBB) == 0 &&
            gWalkingEncounterCountdown <= 0x707)
        {
            gWalkingEncounterCountdown += 300;
            if (gWalkingEncounterCountdown > 1800)
                gWalkingEncounterCountdown = 1800;
            Party_RemoveItem(gMenuInventoryItems[gMenuSavedSelections[gMenuPage]], 1);
            Sound_PlaySfx(1, 0, 0);
            return 0x23;
        }
        Sound_PlaySfx(3, 0, 0);
        return 0x27;
    case 0xEB:
    default:
        Sound_PlaySfx(3, 0, 0);
        return 0x25;
    }
    Sound_PlaySfx(3, 0, 0);
    return 0x27;
}

/**
 * @brief 恢复所选队员 HP 或 MP、消耗物品、启动效果动画，返回成功或失败提示编号
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。 当前返回零的函数体仍是占位。
 * @address 0x0800FA24
 */
u16 Menu_UseRecoveryItem(void)
{
    struct PartyCharacter *character;
    u8 memberIndex;
    u16 amount;

    gMenuHintId = 0;
    gMenuEffectDelay = 16;
    memberIndex = gMenuSavedSelections[0] - 1;
    if (memberIndex == 0xFF)
        return 0x27;

    memberIndex = gPartyMembers[memberIndex];
    if (memberIndex != 0)
        memberIndex--;
    character = &gPartyCharacters[memberIndex];

    if (gMenuItemRecoveryType == 1)
    {
        if (character->hp == character->maxHp)
            return 0x24;
        character->hp += gMenuItemRecoveryAmount;
        if (character->hp > character->maxHp)
            character->hp = character->maxHp;
    }
    else
    {
        if (character->mp == character->maxMp)
            return 0x24;
        amount = gMenuItemRecoveryAmount;
        if (amount == 0)
            amount = 999;
        character->mp += amount;
        if (character->mp > character->maxMp)
            character->mp = character->maxMp;
    }

    Party_RemoveItem(gMenuInventoryItems[gMenuSavedSelections[gMenuPage]], 1);
    if (gPartyItemCounts[gMenuInventoryItems[gMenuSavedSelections[gMenuPage]]] == 0)
    {
        gMenuPhase = gMenuSavedSelections[gMenuPage];
        Menu_TransitionToPage(0xFF);
    }
    Menu_SetRecoveryAnimation(0xFF, 1);
    Sound_PlaySfx(0x17, 1, 0);
    return 0x23;
}

/**
 * @brief 筛选并绘制当前角色和装备槽的五个候选物品
 *
 * @note 角色适用位和物品类别必须匹配；0 表示卸下，FF 表示空行；第六装备槽按类别 4 筛选。
 * @address 0x0800FB2C
 */
void Menu_BuildEquipmentCandidates(void)
{
    u8 characterId;
    u8 equipmentType;
    u8 characterMask;
    u8 itemId;
    u8 index;

    Menu_ClearTextRectInline(20, 6, 8, 10);
    characterId = gPartyMembers[(u8)(gMenuSavedSelections[0] - 1)];
    equipmentType = gMenuSavedSelections[gMenuPage];
    if (equipmentType == 5)
        equipmentType = 4;
    if (characterId <= 8)
    {
        if (characterId != 0)
            characterId--;
        characterMask = 1 << characterId;
        itemId = gMenuEquipmentStartItem;
        index = 0;
        while (itemId <= 0xFD)
        {
            u8 quantity = gPartyItemCounts[itemId];
            const struct PartyItemInfo *item = &gPartyItemTable[itemId];

            if ((quantity != 0 && (item->characterMask & characterMask) != 0
                    && (item->equipmentTypeAndSet & 0xF) == equipmentType) || itemId == 0)
            {
                gMenuEquipmentCandidates[index] = itemId;
                if (gMenuPhase - 6 == index)
                {
                    if (itemId != 0)
                        Menu_DrawItemNameInline(itemId, 20, index * 2 + 6, 13);
                    else
                        Menu_DrawLayoutInline(gMenuSelectedUnequipLayout);
                }
                else
                {
                    if (itemId != 0)
                        Menu_DrawItemNameInline(itemId, 20, index * 2 + 6, 11);
                    else
                        Menu_DrawLayoutInline(gMenuUnequipLayout);
                }
                index++;
            }
            itemId++;
            if (index > 4)
                break;
        }
    }
    else
        index = 0;
    while (index <= 4)
    {
        gMenuEquipmentCandidates[index] |= 0xFF;
        index++;
    }
    gMenuEquipmentStartItem = gMenuEquipmentCandidates[0];
}

/**
 * @brief 寻找当前装备候选窗口前后、符合角色和槽位限制的物品
 *
 * @address 0x0800FDEC
 */
void Menu_RefreshEquipmentScrollItems(void)
{
    u8 characterId;
    u8 characterMask;
    u8 equipmentType;
    u8 itemId;
    u8 found;
    const struct PartyItemInfo *item;

    gMenuEquipmentPreviousItem = 0xFF;
    gMenuEquipmentNextItem = 0xFF;

    characterId = gPartyMembers[(u8)(gMenuSavedSelections[0] - 1)];
    if (characterId > 8)
        return;
    if (characterId != 0)
        characterId--;
    characterMask = 1 << characterId;

    equipmentType = gMenuSavedSelections[gMenuPage];
    if (equipmentType == 5)
        equipmentType = 4;

    itemId = gMenuEquipmentCandidates[0];
    if (gMenuEquipmentStartItem != 0)
    {
        itemId--;
        if (itemId != 0xFF)
        {
            found = 0;
            while (itemId != 0)
            {
                item = &gPartyItemTable[itemId];
                if ((item->characterMask & characterMask) &&
                    (item->equipmentTypeAndSet & 0xF) == equipmentType &&
                    gPartyItemCounts[itemId] != 0)
                {
                    gMenuEquipmentPreviousItem = itemId;
                    found++;
                }
                itemId--;
                if (found != 0)
                    break;
            }
        }
        if (found == 0)
            gMenuEquipmentPreviousItem = found;
    }

    itemId = gMenuEquipmentCandidates[4];
    if (itemId != 0 && itemId != 0xFF)
    {
        itemId++;
        found = 0;
        while (itemId <= 0xFD)
        {
            item = &gPartyItemTable[itemId];
            if ((item->characterMask & characterMask) &&
                (item->equipmentTypeAndSet & 0xF) == equipmentType &&
                gPartyItemCounts[itemId] != 0)
            {
                gMenuEquipmentNextItem = itemId;
                found++;
            }
            itemId++;
            if (found != 0)
                break;
        }
    }
}

/**
 * @brief 计算候选装备的属性预览并设置增减颜色
 *
 * @note characterIndex 是角色记录索引；临时替换槽位后恢复；FF 使用现有装备加成，属性增减分别用 palette 13/12。
 * @address 0x0800FF10
 */
void Menu_PreviewEquipment(u8 itemId, u8 slot, u8 characterIndex)
{
    u8 savedItem;
    struct PartyCharacter *character = &gPartyCharacters[characterIndex];

    if (itemId == 0xFF)
    {
        gPartyEquipmentAtcBonus = character->equipAtc;
        gPartyEquipmentDefBonus = character->equipDef;
        gPartyEquipmentAglBonus = character->equipAgl;
        gPartyEquipmentMenBonus = character->equipMen;
        gPartyEquipmentResBonus = character->equipRes;
        gPartyEquipmentNoaBonus = character->equipNoa;
        gPartyEquipmentLucBonus = character->equipLuc;
    }
    else
    {
        switch (slot)
        {
        case 0: savedItem = character->equipSlot1; character->equipSlot1 = itemId; break;
        case 1: savedItem = character->equipSlot2; character->equipSlot2 = itemId; break;
        case 2: savedItem = character->equipSlot3; character->equipSlot3 = itemId; break;
        case 3: savedItem = character->equipSlot4; character->equipSlot4 = itemId; break;
        case 4: savedItem = character->equipSlot5; character->equipSlot5 = itemId; break;
        case 5: savedItem = character->equipSlot6; character->equipSlot6 = itemId; break;
        }
        Party_CalculateEquipmentBonuses(gPartyMembers[(u8)(gMenuSavedSelections[0] - 1)]);
        switch (slot)
        {
        case 0: character->equipSlot1 = savedItem; break;
        case 1: character->equipSlot2 = savedItem; break;
        case 2: character->equipSlot3 = savedItem; break;
        case 3: character->equipSlot4 = savedItem; break;
        case 4: character->equipSlot5 = savedItem; break;
        case 5: character->equipSlot6 = savedItem; break;
        }
        gPartyEquipmentAtcBonus += gPartyEquipmentSetAtcBonus;
        gPartyEquipmentDefBonus += gPartyEquipmentSetDefBonus;
        {
            if (character->equipAtc > gPartyEquipmentAtcBonus)
                gMenuStatPreviewPalettes[0] = 12;
            else if (character->equipAtc < gPartyEquipmentAtcBonus)
                gMenuStatPreviewPalettes[0] = 13;
        }
        {
            if (character->equipDef > gPartyEquipmentDefBonus)
                gMenuStatPreviewPalettes[1] = 12;
            else if (character->equipDef < gPartyEquipmentDefBonus)
                gMenuStatPreviewPalettes[1] = 13;
        }
        {
            if (character->equipAgl > gPartyEquipmentAglBonus)
                gMenuStatPreviewPalettes[2] = 12;
            else if (character->equipAgl < gPartyEquipmentAglBonus)
                gMenuStatPreviewPalettes[2] = 13;
        }
        {
            if (character->equipMen > gPartyEquipmentMenBonus)
                gMenuStatPreviewPalettes[3] = 12;
            else if (character->equipMen < gPartyEquipmentMenBonus)
                gMenuStatPreviewPalettes[3] = 13;
        }
        {
            if (character->equipRes > gPartyEquipmentResBonus)
                gMenuStatPreviewPalettes[4] = 12;
            else if (character->equipRes < gPartyEquipmentResBonus)
                gMenuStatPreviewPalettes[4] = 13;
        }
        {
            if (character->equipNoa > gPartyEquipmentNoaBonus)
                gMenuStatPreviewPalettes[6] = 12;
            else if (character->equipNoa < gPartyEquipmentNoaBonus)
                gMenuStatPreviewPalettes[6] = 13;
        }
        {
            if (character->equipLuc > gPartyEquipmentLucBonus)
                gMenuStatPreviewPalettes[5] = 12;
            else if (character->equipLuc < gPartyEquipmentLucBonus)
                gMenuStatPreviewPalettes[5] = 13;
        }
    }
}

/**
 * @brief 交换库存与当前队员装备，重算特殊技能和属性
 *
 * @note FF 候选失败，返回 0 或 1。 当前返回零的函数体仍是占位。
 * @address 0x08010170
 */
s32 Menu_EquipItem(u8 slot, u8 itemId)
{
    struct PartyCharacter *character;
    u8 characterId;
    u8 oldEquip;

    characterId = gPartyMembers[(u8)(gMenuSavedSelections[0] - 1)];
    if (characterId != 0)
        characterId--;
    character = &gPartyCharacters[characterId];

    if (itemId == 0xFF)
    {
        Menu_ShowHintWithPalette(0x27, 0x0B);
        return 0;
    }

    if (itemId != 0)
        Party_RemoveItem(itemId, 1);

    switch (slot)
    {
    case 0:
        oldEquip = character->equipSlot1;
        character->equipSlot1 = itemId;
        break;
    case 1:
        oldEquip = character->equipSlot2;
        character->equipSlot2 = itemId;
        break;
    case 2:
        oldEquip = character->equipSlot3;
        character->equipSlot3 = itemId;
        break;
    case 3:
        oldEquip = character->equipSlot4;
        character->equipSlot4 = itemId;
        break;
    case 4:
        oldEquip = character->equipSlot5;
        character->equipSlot5 = itemId;
        break;
    default:
        oldEquip = character->equipSlot6;
        character->equipSlot6 = itemId;
        break;
    }

    if (oldEquip != 0)
        Party_AddItem(oldEquip, 1);

    characterId = gPartyMembers[(u8)(gMenuSavedSelections[0] - 1)];
    character->specialSkill = Party_GetSpecialSkill(characterId);
    Party_CalculateEquipmentBonuses(characterId);
    Party_ApplyEquipmentBonuses(characterId);
    gMenuPhase = gMenuSavedSelections[gMenuPage];
    return 1;
}

/**
 * @brief 计算技能经过装备修正后的 MP 消耗
 *
 * @note 饰物 AF 优先减半；指定装备可逐项减二；发生装备修正时消耗至少为一。
 * @address 0x0801026C
 */
u8 Menu_GetAdjustedSkillMpCost(u8 characterId, u8 skillId)
{
    struct PartyCharacter *character;
    u8 cost;

    if (characterId != 0)
        characterId--;
    character = &gPartyCharacters[characterId];
    cost = Party_GetSkillMpCost(skillId);
    if (character->equipSlot5 == 0xAF)
    {
        cost /= 2;
        if (cost == 0)
            cost = 1;
    }
    else if (character->equipSlot6 == 0xAF)
    {
        cost /= 2;
        if (cost == 0)
            cost = 1;
    }
    else
    {
        if (character->equipSlot2 == 0x63)
        {
            if (cost > 2)
                cost -= 2;
            else
                cost = 1;
        }
        if (character->equipSlot3 == 0x83)
        {
            if (cost > 2)
                cost -= 2;
            else
                cost = 1;
        }
        if (character->equipSlot3 == 0x84)
        {
            if (cost > 2)
                cost -= 2;
            else
                cost = 1;
        }
    }
    return cost;
}

/**
 * @brief 检查施术者 MP、Nall 可用标志、逃离条件和队伍 HP，设置效果参数与提示
 *
 * @address 0x08010300
 */
u8 Menu_PrepareFieldSkill(u8 skillId)
{
    u8 member;
    u8 characterIndex;
    u16 mpCost;
    u8 actualCost;
    u8 injuredCount;
    u16 i;
    struct PartyCharacter *character;
    const struct PartySkillInfo *skill;

    if (skillId == 0)
    {
        gMenuHintId = 0x27;
        return 0;
    }

    if (skillId == 0x3E)
    {
        if (!(gPlayerFieldFlags & 0x80))
        {
            gMenuHintId = 0x24;
            return 0;
        }
    }
    else
    {
        member = gPartyMembers[(u8)(gMenuSavedSelections[0] - 1)];
        characterIndex = member;
        if (member != 0)
            characterIndex = member - 1;

        character = &gPartyCharacters[characterIndex];
        mpCost = Menu_GetAdjustedSkillMpCost(member, skillId);
        if (mpCost > character->mp)
            actualCost = 0;
        else
            actualCost = mpCost;

        gMenuFieldSkillMpCost = actualCost;
        if (actualCost == 0)
        {
            gMenuHintId = 0x1D;
            return 0;
        }
    }

    {
        s32 offset = (skillId - 1) * sizeof(struct PartySkillInfo);
        skill = (const struct PartySkillInfo *)((u32)gPartySkillTable + offset);
    }
    gMenuFieldSkillTargetMode = skill->characterGroupBits & 0xF;
    gMenuFieldSkillRecoveryAmount = skill->unknown03;

    if (skillId == 0x26)
    {
        if (Menu_TryEscapeDungeon())
            return 1;
        gMenuHintId = 0x27;
        return 0;
    }

    injuredCount = 0;
    i = 0;
    member = gPartyMembers[0];
    while (member != 0xFF)
    {
        if (member != 0)
            member--;
        if (gPartyCharacters[member].hp < gPartyCharacters[member].maxHp)
            injuredCount++;
        i++;
        if (i > 4)
            break;
        member = gPartyMembers[i];
    }

    if (injuredCount != 0)
        return 2;

    gMenuHintId = 0x1C;
    return 0;
}

/**
 * @brief 按当前场景查询逃离目的地，设置场景过渡参数并关闭菜单
 *
 * @address 0x08010434
 */
u8 Menu_TryEscapeDungeon(void)
{
    u8 offset;
    u8 val;

    if (EventFlags_GetMask(0xBA))
        return 0;

    offset = 0;
    while ((val = gDungeonEscapeDestinations[offset]) != 0)
    {
        if (val == gSceneId)
        {
            offset++;
            gPendingSceneId = gDungeonEscapeDestinations[offset++];
            gSceneEntryTileX = gDungeonEscapeDestinations[offset++];
            gSceneEntryTileY = gDungeonEscapeDestinations[offset++];
            gSceneEntryDirection = gDungeonEscapeDestinations[offset++];
            gSceneCameraRegionId =
                gDungeonEscapeDestinations[offset] + (gDungeonEscapeDestinations[offset + 1] << 8);
            gPlayerTransitionStage = 1;
            gMenuState = 0x34;
            return 1;
        }
        offset += 7;
    }

    return 0;
}

/**
 * @brief 校验所选地点及剧情限制，读取六字节目的地记录并开始场景过渡
 *
 * @address 0x080104F8
 */
u8 Menu_ConfirmTravelDestination(void)
{
    s8 eventFlag;
    u8 destination;
    u8 offset;
    // const u8 *records;
    s32 regionOffset;
    u16 region;

    destination = gMenuDestinations[gMenuPhase - 11 + gMenuDestinationScroll];
    if (destination == 0)
    {
        gMenuHintId = 0x27;
        Sound_PlaySfx(3, 0, 0);
        return 0;
    }

    if (destination == 8)
    {
        eventFlag = EventFlags_GetMask(0x10D);
        if (eventFlag == 0)
        {
            gMenuHintId = 0x1A;
            Sound_PlaySfx(3, 0, 0);
            return 0;
        }
    }
    if (destination == 0x18)
    {
        eventFlag = EventFlags_GetMask(0xFF);
        if (eventFlag != 0)
        {
            gMenuHintId = 0x1A;
            Sound_PlaySfx(3, 0, 0);
            return 0;
        }
    }


    offset = 0;

    // while (gMenuTravelDestinationRecords[offset] != destination) {
    //     offset+=6;
    // }
    // // records = gMenuTravelDestinationRecords;
    // do
    // {
    //     if (gMenuTravelDestinationRecords[offset] == destination)
    //         break;
    //     offset += 6;
    // } while (1);

    do {
        if(gMenuTravelDestinationRecords[offset] != destination)
        {
            offset += 6;
            continue;
        }
        gPendingSceneId = gMenuTravelDestinationRecords[offset++];
        gSceneEntryTileX = gMenuTravelDestinationRecords[offset++];
        gSceneEntryTileY = gMenuTravelDestinationRecords[offset++];
        gSceneEntryDirection = gMenuTravelDestinationRecords[offset++];
        gSceneCameraRegionId = gMenuTravelDestinationRecords[offset] + (gMenuTravelDestinationRecords[offset + 1] << 8);
        gPlayerTransitionStage = 1;
        gMenuState = 0x34;
        SystemFlags_ClearLocal();
        break;
    }while (1);
    return 1;
}

static inline void Menu_ClearRecoveryActor(u32 actorIndex)
{
    if (gActorStates[actorIndex].scriptEntryOrMenuState != 0x80)
    {
        gActorStates[actorIndex].customAnimationTimer = 0;
        gActorStates[actorIndex].scriptEntryOrMenuState = 0x80;
        if (gActorStates[actorIndex].spriteSlot != 0)
            Sprite_FreeChain(&gSpriteNodes[gActorStates[actorIndex].spriteSlot]);
    }
}

/**
 * @brief 清理旧恢复动画，或为指定队伍位置／Nall 启动恢复效果
 *
 * @note 模式 0 清理全部并返回；1 清理全部后启动指定位置；2 仅清理该位置后启动。
 *       position=FF 使用 Nall 坐标；菜单角色从 19 起，清除状态 0x13 并释放精灵链。
 * @address 0x08010624
 */
void Menu_SetRecoveryAnimation(u8 position, u8 mode)
{
    u16 index;
    u16 x;
    u16 y;
    u32 actorIndex;

    if (mode == 0)
    {
        index = 0;
        do
        {
            Menu_ClearRecoveryActor(index + CORE_MENU_ACTOR_FIRST);
            index++;
        } while (index <= 4);
        return;
    }

    if (mode == 1)
    {
        index = 0;
        do
        {
            Menu_ClearRecoveryActor(index + CORE_MENU_ACTOR_FIRST);
            index++;
        } while (index <= 4);
    }

    if (position == 0xFF)
    {
        x = gCameraX + 0x18;
        y = gCameraY + 0x30;
        actorIndex = 0;
    }
    else
    {
        actorIndex = position;
        x = (position * 5 + 7) * 8 + gCameraX;
        y = gCameraY + 0x30;
    }

    actorIndex += CORE_MENU_ACTOR_FIRST;

    if (mode == 2)
        Menu_ClearRecoveryActor(actorIndex);

    Actor_StartCustomAnimation(actorIndex, 0);
    gActorStates[actorIndex].x = x;
    gActorStates[actorIndex].y = y;
    gActorStates[actorIndex].scriptEntryOrMenuState = 0;
}

/**
 * @brief 检查技能，进入单体目标选择或恢复单体／全队 HP
 *
 * @note 成功后扣施术者 MP，Nall 技能清可用位。
 * @address 0x08010770
 */
void Menu_UseFieldSkill(u8 mode)
{
    u8 success = 0;
    u16 index;
    u8 member;
    struct PartyCharacter *character;
    struct PartyCharacter *target;

    if (Menu_PrepareFieldSkill(gMenuFieldSkillId) != 0)
    {
        if (gMenuFieldSkillId != 0x26)
        {
            gMenuEffectDelay = 16;
            if (mode == 0)
            {
                if (gMenuFieldSkillTargetMode == 5)
                {
                    for (index = 0; index <= 4; index++)
                    {
                        member = gPartyMembers[index];
                        if (member == 0xFF)
                            break;
                        if (member != 0)
                            member--;
                        if (gMenuFieldSkillRecoveryAmount != 0)
                        {
                            character = &gPartyCharacters[member];
                            character->hp += gMenuFieldSkillRecoveryAmount;
                            if (character->hp > character->maxHp)
                                character->hp = character->maxHp;
                        }
                        else
                            gPartyCharacters[member].hp = gPartyCharacters[member].maxHp;
                        Menu_SetRecoveryAnimation(index, 2);
                    }
                    Sound_PlaySfx(0x17, 1, 0);
                    success++;
                }
                else
                {
                    gMenuSavedSelections[gMenuPage] = gMenuPhase;
                    gMenuPhase = gMenuSavedSelections[15];
                    if (gMenuPhase <= 3)
                        gMenuPhase = 4;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(1, 0, 0);
                    return;
                }
            }
            else
            {
                member = gPartyMembers[gMenuPhase - 4];
                if (member != 0)
                    member--;
                {
                    struct PartyCharacter *characters = gPartyCharacters;
                    target = &characters[member];
                }
                if (target->hp < target->maxHp)
                {
                    if (gMenuFieldSkillRecoveryAmount != 0)
                    {
                        target->hp += gMenuFieldSkillRecoveryAmount;
                        if (target->hp > target->maxHp)
                            target->hp = target->maxHp;
                    }
                    else
                        target->hp = target->maxHp;
                    Menu_SetRecoveryAnimation(gMenuPhase - 4, 1);
                    Sound_PlaySfx(0x17, 1, 0);
                    success++;
                }
                else
                {
                    gMenuHintId = 0x24;
                    Sound_PlaySfx(3, 0, 0);
                }
            }
        }
        else
            success = 1;
        if (success != 0)
        {
            if (gMenuFieldSkillId == 0x3E)
            {
                gPlayerFieldFlags &= 0x7F;
                Menu_DrawFieldSkillList(0, gMenuSavedSelections[gMenuPage]);
            }
            else
            {
                member = gPartyMembers[(u8)(gMenuSavedSelections[0] - 1)];
                if (member != 0)
                    member--;
                gPartyCharacters[member].mp -= gMenuFieldSkillMpCost;
            }
        }
    }
    else
        Sound_PlaySfx(3, 0, 0);
}

/**
 * @brief 将存档中的已到达地点位图转换为菜单地点编号列表，并清滚动起点
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08010978
 */
void Menu_BuildTravelDestinations(void)
{
    u8 index;
    u8 count;

    if (EventFlags_GetMask(0xFD) != 0)
        gVisitedDestination[1] |= 0x20;
    index = 0;
    count = 0;
    for (; index <= 14; index++)
    {
        if ((gVisitedDestination[index >> 3] >> (index & 7)) & 1)
        {
            gMenuDestinations[count] = gTravelDestinationSceneIds[index];
            count++;
        }
    }
    while (count <= 15)
    {
        gMenuDestinations[count] = 0;
        count++;
    }
    gMenuDestinationScroll = 0;
}

/**
 * @brief 每次处理一个 SRAM 读写／验证状态及四槽校验
 *
 * @note 1 表示仍忙，0 表示就绪。
 * @address 0x080109F8
 */
u8 Save_UpdateIo(u8 suppressSlotDraw)
{
    switch (gSaveIoState)
    {
    case 1:
        ReadSram((u8 *)0x0E000000 + gSaveIoBlockIndex * 0x800,
                      SAVE_SLOT_BUFFER + gSaveIoBlockIndex * 0x800, 0x800);
        gSaveIoState++;
        return 1;
    case 2:
        if (VerifySram(SAVE_SLOT_BUFFER + gSaveIoBlockIndex * 0x800,
                          (u8 *)0x0E000000 + gSaveIoBlockIndex * 0x800, 0x800) != 0)
            gSaveIoState = 0xFD;
        else
        {
            if (gSaveIoBlockIndex <= 14)
                gSaveIoState--;
            else
                gSaveIoState = 0xF9;
            gSaveIoBlockIndex++;
        }
        return 1;
    case 3:
        WriteSram(SAVE_SLOT_BUFFER + gSaveIoBlockIndex * 0x800,
                      (u8 *)0x0E000000 + gSaveIoBlockIndex * 0x800, 0x800);
        gSaveIoState++;
        return 1;
    case 4:
        if (VerifySram(SAVE_SLOT_BUFFER + gSaveIoBlockIndex * 0x800,
                          (u8 *)0x0E000000 + gSaveIoBlockIndex * 0x800, 0x800) != 0)
        {
            gSaveIoState = 0xFD;
            Menu_ShowHintWithPalette(0x27, 11);
            if (gMenuPhase > 5)
            {
                gMenuPhase = gMenuSaveSlot + 3;
                Menu_TransitionToPage(0xFF);
            }
        }
        else
        {
            if (gSaveIoBlockIndex <= 14)
                gSaveIoState--;
            else
            {
                gSaveIoState = 0xFF;
                Menu_ShowHintWithPalette(0x19, 11);
                if (gMenuPhase > 5)
                {
                    gMenuPhase = gMenuSaveSlot + 3;
                    Menu_TransitionToPage(0xFF);
                }
            }
            gSaveIoBlockIndex++;
        }
        return 1;
    case 0xF9:
        Save_VerifySlotChecksum(0);
        gSaveIoState = 0xFA;
        return 1;
    case 0xFA:
        Save_VerifySlotChecksum(1);
        gSaveIoState = 0xFB;
        return 1;
    case 0xFB:
        Save_VerifySlotChecksum(2);
        gSaveIoState = 0xFC;
        return 1;
    case 0xFC:
        Save_VerifySlotChecksum(3);
        gSaveIoState = 0xFF;
        return 1;
    case 0xFD:
        SAVE_SLOT_BUFFER[0] = 0xFF;
        SAVE_SLOT_BUFFER[SAVE_SLOT_SIZE] = 0xFF;
        SAVE_SLOT_BUFFER[2 * SAVE_SLOT_SIZE] = 0xFF;
        SAVE_SLOT_BUFFER[3 * SAVE_SLOT_SIZE] = 0xFF;
        gSaveIoState = 0xFF;
        return 1;
    case 0xFF:
        if (suppressSlotDraw == 0)
            Menu_DrawSaveSlots();
        gSaveIoState = 0xFE;
        return 1;
    default:
        return 0;
    }
    return 1;
}

/**
 * @brief 检查十二字节签名及字段字节和
 *
 * @note 校验和错误清槽首字节，返回 0/1/FF。
 * @address 0x08010BEC
 */
u8 Save_VerifySlotChecksum(u8 slot)
{
    u8 *buffer;
    u8 *text;
    u8 index;
    u16 offset;
    u16 field;
    u16 remaining;
    u8 checksum;

    if (slot > 3)
        return 0xFF;
    text = SAVE_SLOT_BUFFER + slot * SAVE_SLOT_SIZE;
    buffer = text;
    for (index = 0; index <= 11; index++)
    {
        if (*text != gSaveSlotSignature[index])
            return 1;
        text++;
    }
    offset = 12;
    field = 0;
    checksum = 0;
    if (slot != 3)
    {
        for (; (remaining = gSaveNormalFieldSizes[field]) != 0; field++)
        {
            while (remaining != 0)
            {
                checksum += buffer[offset];
                offset++;
                remaining--;
            }
        }
    }
    else
    {
        for (; (remaining = gSaveBonusFieldSizes[field]) != 0; field++)
        {
            while (remaining != 0)
            {
                checksum += buffer[offset];
                offset++;
                remaining--;
            }
        }
    }
    if (buffer[offset] != checksum)
    {
        text = SAVE_SLOT_BUFFER + slot * SAVE_SLOT_SIZE;
        *text = 0xFF;
    }
    else
        return 0;
    return 1;
}

/**
 * @brief 把普通游戏字段按地址与长度表打包到槽缓冲，写字节和及签名，记录正常槽编号
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08010CCC
 */
void Save_PackGameSlot(u8 slot)
{
    u8 *buffer;
    u8 *source;
    u16 offset;
    u16 field;
    u16 remaining;
    u8 checksum;

    if (slot <= 3)
    {
        if (slot <= 2)
            gSaveLastUsedSlot = slot;
        buffer = SAVE_SLOT_BUFFER + slot * SAVE_SLOT_SIZE;
        for (offset = 0; offset <= 11; offset++)
            buffer[offset] = 0xFF;
        checksum = 0;
        offset = 12;
        for (field = 0; (remaining = gSaveNormalFieldSizes[field]) != 0; field++)
        {
            source = gSaveNormalFieldPointers[field];
            while (remaining != 0)
            {
                buffer[offset] = *source;
                checksum += buffer[offset];
                offset++;
                source++;
                remaining--;
            }
        }
        buffer[offset] = checksum;
        for (offset = 0; offset <= 11; offset++)
            buffer[offset] = gSaveSlotSignature[offset];
    }
}

/**
 * @brief 从普通槽恢复字段，重置跟随和场景过渡状态并清文本背景
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08010D80
 */
void Save_LoadGameSlot(u8 slot)
{
    u8 *buffer;
    u8 *dest;
    u16 offset;
    u16 field;
    u16 remaining;

    if (slot <= 3)
    {
        if (slot <= 2)
            gSaveLastUsedSlot = slot;
        buffer = SAVE_SLOT_BUFFER + slot * SAVE_SLOT_SIZE;
        offset = 12;
        for (field = 0; (remaining = gSaveNormalFieldSizes[field]) != 0; field++)
        {
            dest = gSaveNormalFieldPointers[field];
            while (remaining != 0)
            {
                *dest = buffer[offset];
                offset++;
                dest++;
                remaining--;
            }
        }
        SystemFlags_ClearLocal();
        gScriptedBattleState = 0;
        Player_ResetFollowing();
        gSceneState = 12;
        gVBlankUpdateMode = 1;
        System_SuspendAudioAndBlankDisplay();
        {
            u16 *tile = gScriptTextTilemap;

            for (offset = 0; offset <= 0x3FF; offset++)
                *tile++ = 0;
        }
        DmaCopy(3, gScriptTextTilemap, BG_SCREEN_ADDR(31), 0x800, 16);
    }
}

/**
 * @brief 从槽缓冲提取等级、场景和游戏时间摘要
 *
 * @note 检查十二字节签名；无效槽头记等级 FF、场景零和时间零；读取缓冲，不执行 SRAM I/O。
 * @address 0x08010E58
 */
void Save_ReadSlotSummary(u8 slot)
{
    if (slot <= 3)
    {
        const u8 *text = SAVE_SLOT_BUFFER + slot * SAVE_SLOT_SIZE;
        u8 invalid;

        invalid = Save_CompareSlotSignature(text);
        if (invalid)
        {
            gSaveSummaryLevels[slot] = 0xFF;
            gSaveSummarySceneIds[slot] = 0;
            gSaveSummaryPlayTimes[slot] = 0;
        }
        else
        {
            const u8 *header = SAVE_SLOT_BUFFER + slot * SAVE_SLOT_SIZE;

            gSaveSummaryLevels[slot] = header[0x1A];
            gSaveSummarySceneIds[slot] = header[0x14];
            gSaveSummaryPlayTimes[slot] = header[0xC] + (header[0xD] << 8)
                + (header[0xE] << 16) + (header[0xF] << 24);
        }
    }
}

/**
 * @brief 在指定菜单位置绘制一个存档槽的摘要
 *
 * @note 读取已缓存的等级、场景和时间；无效槽绘制空存档文字；palette 是字形调色板编号。
 * @address 0x08010F10
 */
void Save_DrawSlotSummary(u8 slot, u8 x, u8 y, u8 palette)
{
    u16 *origin;
    u16 *dest;
    u16 index;

    if (slot <= 3)
    {
        origin = MENU_TEXT_ADDR(x, y);
        dest = origin;
        Menu_DrawGlyphInline(dest - 2, slot + 0xA3, palette);
        Menu_DrawGlyphInline(dest - 1, 0xD7, palette);
        Menu_DrawGlyphInline(dest++, 0xC8, 11);
        for (index = 0; index <= 19; index++)
            Menu_DrawGlyphInline(dest++, 0, 11);
        Menu_DrawGlyphInline(dest, 0xC9, 11);
        dest = origin + 1;
        if (gSaveSummarySceneIds[slot] == 0)
        {
            index = 0;
            do
                Menu_DrawGlyphInline(dest++, gMenuEmptySaveText[index++], 12);
            while (index <= 9);
        }
        else
        {
            Menu_DrawGlyphInline(dest++, 0xB7, palette);
            Menu_DrawGlyphInline(dest++, 0xC1, palette);
            dest++;
            Menu_DrawDecimal(dest++, gSaveSummaryLevels[slot] + 1, palette);
            dest++;
            Menu_DrawSceneNameInline(dest, gSaveSummarySceneIds[slot], palette);
            dest = origin + 15;
            Menu_DrawPlayTime(dest, gSaveSummaryPlayTimes[slot], palette);
            Menu_DrawGlyphInline(origin + 18, 0xD7, palette);
        }
    }
}


/**
 * @brief 绘制三行战术技能窗口，遇 FF 或逃离技能 26 停止，并记录选中技能
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0801114C
 */
void Menu_DrawTacticsSkillList(void)
{
    struct PartyCharacter *character;
    u16 index;
    u8 skill;
    u8 palette;

    skill = gPartyMembers[gMenuTacticsPartySlot];
    if (skill != 0)
        skill--;
    character = &gPartyCharacters[skill];
    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(16, 10), 8, 6);
    for (index = 0; index <= 2; index++)
    {
        skill = character->skills[index + gMenuTacticsScroll];
        if (skill == 0xFF || skill == 0x26)
            break;
        if (index == gMenuPhase - 16)
        {
            gMenuTacticsActionId = skill;
            palette = 13;
        }
        else
            palette = 11;
        Menu_DrawSkillNameInline(skill, 16, index * 2 + 10, palette);
    }
}

/**
 * @brief 从十六项白名单中绘制三行有库存的战术物品及数量，并记录选中物品
 *
 * @note 先清除名称与数量两列；跳过无库存项，最多三行。选中行用调色板 13 并保存物品编号，
 *       其余行用 11，数量固定用 12。名称在 x=16，数量在 x=28。
 * @address 0x08011268
 */
void Menu_DrawTacticsItemList(void)
{
    u16 index;
    u16 entryIndex;
    u8 itemId;

    Menu_ClearTextRectInline(16, 10, 8, 6);
    Menu_ClearTextRectInline(27, 10, 2, 6);

    for (index = gMenuTacticsScroll, entryIndex = 0;
         entryIndex <= 2 && index <= 15;
         index++)
    {
        itemId = Menu_GetTacticsItemAtIndex(index);
        if (itemId != 0xFF)
        {
            u8 palette;

            if (entryIndex == gMenuPhase - 0x10)
            {
                gMenuTacticsActionId = itemId;
                palette = 13;
            }
            else
                palette = 11;
            Menu_DrawItemNameInline(itemId, 16, entryIndex * 2 + 10, palette);
            Menu_DrawDecimal(MENU_TEXT_ADDR(28, entryIndex * 2 + 10),
                gPartyItemCounts[itemId], 12);
            entryIndex++;
        }
    }
}

/**
 * @brief 查找下一个可组成三行的战术物品窗口
 *
 * @note 0 无可推进项，FF 剩余不足三行，其余为白名单索引。
 * @address 0x080113CC
 */
u8 Menu_FindNextFullTacticsItemWindow(void)
{
    u8 first = gMenuTacticsScroll + 1;
    u8 index;
    u8 following;

    while (first <= 15 && gPartyItemCounts[gTacticsItemIds[first]] == 0)
        first++;
    if (first > 14)
        return 0;
    following = 0;
    index = first + 1;
    while (index <= 15)
    {
        if (gPartyItemCounts[gTacticsItemIds[index]] != 0)
        {
            following++;
            if (following == 2)
                return first;
        }
        index++;
    }
    return 0xFF;
}

/**
 * @brief 标题、新游戏、读取、声音测试、卡片、画廊和通信交换的状态机
 *
 * @note 输入仅在交互阶段开放；转场期间继续更新菜单动画和存档通信。
 * @address 0x08011454
 */
void TitleMenu_UpdateState(void)
{
    u16 index;
    u16 *dest;

    if (gScreenTransitionType != 0)
    {
        gKeysPressed = 0;
        gKeysHeld = 0;
    }
    switch (gScenePhase)
    {
    case 29:
    case 36:
    case 37:
        if (gVBlankUpdateMode == 5)
            break;
    case 8:
    case 9:
    case 14:
    case 20:
    case 25:
    case 30:
    case 35:
        if (gScreenTransitionType == 0)
            break;
    default:
        gKeysPressed = 0;
        gKeysHeld = 0;
        break;
    }

    switch (gScenePhase)
    {
    case 0:
        gSceneEffectTilemapUploadPending = 0;
        gVBlankUpdateMode = 0;
        Sound_StopBgm();
        gSaveLastUsedSlot = 0;
        Save_LoadBonusData();
        gTitlePresentationStage = 1;
        gScenePhase = 1;
        break;
    case 1:
    {
        const u8 *source;

        System_SuspendAudioAndBlankDisplay();
        System_ClearGameState(0);
        gTitleIdleCyclesRemaining = 16;
        gVBlankUpdateMode = 4;
        (*(vu16 *)REG_DISPCNT) = 0x11E0;
        (*(vu16 *)REG_BG0CNT) = 0x1E01;
        if (gTitlePresentationStage == 1)
        {
            source = (const u8 *)&gTitlePresentationResources;
            LZ77UnCompVram((void *)(source), ((void *)VRAM));
            LZ77UnCompVram((void *)(source + offsetof(struct TitlePresentationResources, firstPalette)), PALETTE_RAM);
            source += offsetof(struct TitlePresentationResources, firstTilemap);
            LZ77UnCompWram((void *)(source), gScriptTextTilemap);
        }
        else
        {
            source = (const u8 *)&gTitlePresentationResources
                + offsetof(struct TitlePresentationResources, secondTiles);
            LZ77UnCompVram((void *)(source), ((void *)VRAM));
            LZ77UnCompVram((void *)(source + offsetof(struct TitlePresentationResources, secondPalette)
                - offsetof(struct TitlePresentationResources, secondTiles)), PALETTE_RAM);
            source += offsetof(struct TitlePresentationResources, secondTilemap)
                - offsetof(struct TitlePresentationResources, secondTiles);
            LZ77UnCompWram((void *)(source), gScriptTextTilemap);
        }
        DmaCopy(3, gScriptTextTilemap, BG_SCREEN_ADDR(30), 0x800, 16);
        gBlendControl = 0;
        gBlendCoefficients = 0;
        (*(vu16 *)REG_BLDCNT) = 0;
        (*(vu16 *)REG_BLDALPHA) = 0;
        Palette_SaveTransitionSource();
        Transition_Start(3);
        gScenePhase = 2;
        System_ResumeAudioAndDisplay();
        Sound_PlayBgm(22, 0);
        break;
    }
    case 2:
    case 4:
        if (gScreenTransitionType == 0)
        {
            if (gScenePhase == 2)
            {
                gScenePhase = 3;
                gSceneTransitionCounter = 64;
            }
            else if (++gTitlePresentationStage > 2)
                gScenePhase = 5;
            else
                gScenePhase = 1;
        }
        break;
    case 3:
        if (--gSceneTransitionCounter == 0 && gScenePhase == 3)
        {
            gScenePhase = 4;
            Transition_Start(4);
        }
        break;
    case 5:
    {
        const u8 *text;
        u32 count;
        u32 bankMask;
        const u8 **banks;

        System_SuspendAudioAndBlankDisplay();
        gTitleIdleCyclesRemaining = 16;
        gVBlankUpdateMode = 4;
        gCameraX = 8;
        gCameraY = 32;
        Scene_LoadResources(12);
        LZ77UnCompVram((void *)(gMenuSpriteGraphicsSources[11]), TITLE_CURSOR_TILES);
        DmaCopy(3, gMenuSharedSpritePalette, OBJ_PALETTES[2], 32, 16);
        LZ77UnCompVram((void *)(gTitleOptionTiles), TITLE_OPTION_TILES);
        DmaCopy(3, gTitleOptionPalettes, OBJ_PALETTES[10], 64, 16);
        DmaCopy(3, gMenuTextPalettes, PALETTE_RAM[14], 64, 16);
        Menu_ResetNavigation();
        TitleMenu_CreateCursorSprite();
        (*(vu16 *)REG_DISPCNT) = 0x15E0;
        (*(vu16 *)REG_BG0CNT) = 0x1F09;
        *(vu16 *)REG_BG2CNT = 0x3C02;
        LZ77UnCompVram((void *)(gTitleMenuTilemap), BG_SCREEN_ADDR(24));
        DmaCopy(3, gSceneSharedPalettes, PALETTE_RAM[15], 32, 16);
        TitleMenu_DrawMainOptions();
        DmaCopy(3, gScriptTextTilemap, BG_SCREEN_ADDR(30), 0x800, 16);
        DmaCopy(3, MAP_TILEMAP_A, BG_SCREEN_ADDR(28), 0x800, 16);
        DmaCopy(3, MAP_TILEMAP_B, BG_SCREEN_ADDR(29), 0x800, 16);
        LZ77UnCompVram((void *)(gWorldMapUiTilemap0), BG_SCREEN_ADDR(26));
        LZ77UnCompVram((void *)(gWorldMapUiTilemap1), (u8 *)BG_SCREEN_ADDR(26) + 0x400);
        LZ77UnCompVram((void *)(gWorldMapUiTilemap2), BG_SCREEN_ADDR(27));
        gBlendControl = 0x441;
        gBlendCoefficients = 0;
        (*(vu16 *)REG_BLDCNT) = 0x441;
        (*(vu16 *)REG_BLDALPHA) = 0;
        Palette_SaveTransitionSource();
        Transition_Start(3);
        gSceneTransitionCounter = 0;
        gCoreUnknown2608 = 0;
        gScenePhase++;
        text = gMenuHintText;
        gMenuHintBanks[0] = text;
        count = 0;
        bankMask = 63;
        banks = gMenuHintBanks;
        do
        {
            while (*text != 0xFF)
                text++;
            text++;
            count++;
            if ((count & bankMask) == 0)
                banks[count >> 6] = text;
        } while (*text != 0xFF);
        System_ResumeAudioAndDisplay();
        Sound_PlayBgm(22, 0);
        Sound_FadeInBgm(32);
        break;
    }
    case 6:
        if (gScreenTransitionType != 0)
        {
            gBlendCoefficients = ((gSceneTransitionCounter >> 3) << 8)
                + (gCoreUnknown2608 >> 3);
            break;
        }
        if (++gSceneTransitionCounter == 56)
            gScenePhase = 7;
    case 7:
        if (gScenePhase == 7 && ++gCoreUnknown2608 == 120)
        {
            gScenePhase = 8;
            gBlendCoefficients = ((gSceneTransitionCounter >> 3) << 8)
                + (gCoreUnknown2608 >> 3);
            gSceneTransitionCounter = 0;
        }
        else
            gBlendCoefficients = ((gSceneTransitionCounter >> 3) << 8)
                + (gCoreUnknown2608 >> 3);
        break;
    case 8:
        gSceneTransitionCounter++;
        goto updateInput;
    case 10:
    case 11:
    case 13:
    case 15:
    case 16:
    case 17:
    case 18:
    case 19:
    case 21:
        TitleMenu_UpdateInputAndCursor();
        if (gScreenTransitionType == 0)
        {
            if (gScenePhase == 10)
            {
                gSceneState = 0;
                gVBlankUpdateMode = 1;
                gTitlePresentationStage = 0;
            }
            else if (gScenePhase == 11)
            {
                gScenePhase = 12;
                Menu_TransitionToPage(2);
                gMenuSaveSlot = gMenuPhase;
                Menu_ClearTextRectInline(0, 0, 30, 20);
                gSaveIoState = 1;
                gSaveIoBlockIndex = 0;
            }
            else if (gScenePhase == 13)
                gScenePhase = 14;
            else if (gScenePhase == 15)
            {
                TitleMenu_DrawMainOptions();
                Menu_TransitionToPage(1);
                Transition_Start(5);
                gScenePhase = 16;
            }
            else if (gScenePhase == 16)
                gScenePhase = 9;
            else if (gScenePhase == 17)
            {
                gScenePhase = 0;
                gTitlePresentationStage = 0;
                Save_LoadGameSlot(gMenuSaveSlot);
            }
            else if (gScenePhase == 18)
            {
                gScenePhase = 19;
                gSoundTestBgmId = 0;
                gSoundTestPlayingBgmIdPlusOne = 0;
                gSoundTestSfxIndex = 0;
                Menu_TransitionToPage(3);
                Menu_ClearTextRectInline(0, 0, 30, 20);
                Menu_DrawLayoutInline(gTitleOptionsHeaderLayout);
                TitleMenu_DrawOptions();
                Transition_Start(5);
            }
            else if (gScenePhase == 19)
                gScenePhase = 20;
            else if (gScenePhase == 21)
            {
                System_SuspendAudioAndBlankDisplay();
                gSceneState = 0;
                gVBlankUpdateMode = 1;
            }
        }
        break;
    case 12:
        TitleMenu_UpdateInputAndCursor();
        if (Save_UpdateIo(0) == 0)
        {
            Transition_Start(5);
            gScenePhase = 13;
        }
        break;
    case 14:
        TitleMenu_UpdateInputAndCursor();
        if (gSaveIoState == 0xFE)
        {
            u8 slot;
            for (slot = 0; slot < 3; slot++)
            {
                u8 palette;

                Save_ReadSlotSummary(slot);
                palette = gMenuSaveSlot == slot ? 13 : 11;
                Save_DrawSlotSummary(slot, 8, slot * 2 + 5, palette);
            }
        }
        break;
    case 20:
        TitleMenu_UpdateInputAndCursor();
        TitleMenu_DrawOptions();
        break;
    case 22:
        TitleMenu_UpdateInputAndCursor();
        if (gScreenTransitionType == 0)
        {
            System_SuspendAudioAndBlankDisplay();
            Scene_LoadResources(gGalleryUnlockEventIds[gCollectionCommittedRecordId] + 0x82);
            (*(vu16 *)REG_DISPCNT) = 0x13E0;
            (*(vu16 *)REG_BG0CNT) = 0x1F09;
            gBlendControl = 0;
            gBlendCoefficients = 0;
            (*(vu16 *)REG_BLDCNT) = 0;
            (*(vu16 *)REG_BLDALPHA) = 0;
            Palette_SaveTransitionSource();
            Transition_Start(3);
            gScenePhase = 23;
            Menu_TransitionToPage(4);
            Menu_ClearTextRectInline(0, 0, 30, 20);
            index = 0;
            dest = MENU_TEXT_ADDR(0, 4);
            for (; index < 384; index++)
                *dest++ = 0;
            Menu_DrawLayoutInline(gGalleryHeaderLayout);
            Menu_DrawDecimal(gScriptTextTilemap + 60, gCollectionCommittedRecordId, 11);
            System_ResumeAudioAndDisplay();
        }
        break;
    case 23:
    case 25:
        TitleMenu_UpdateInputAndCursor();
        if (gScreenTransitionType == 0)
            gScenePhase = 25;
        break;
    case 24:
        if (gScreenTransitionType == 0)
            gScenePhase = 26;
        break;
    case 26:
        TitleMenu_UpdateInputAndCursor();
        System_SuspendAudioAndBlankDisplay();
        Scene_LoadResources(12);
        LZ77UnCompVram((void *)(gTitleMenuTilemap), BG_SCREEN_ADDR(24));
        DmaCopy(3, gSceneSharedPalettes, PALETTE_RAM[15], 32, 16);
        LZ77UnCompVram((void *)(gMenuSpriteGraphicsSources[11]), TITLE_CURSOR_TILES);
        DmaCopy(3, gMenuSharedSpritePalette, OBJ_PALETTES[2], 32, 16);
        LZ77UnCompVram((void *)(gTitleOptionTiles), TITLE_OPTION_TILES);
        DmaCopy(3, gTitleOptionPalettes, OBJ_PALETTES[10], 64, 16);
        DmaCopy(3, gMenuTextPalettes, PALETTE_RAM[14], 64, 16);
        (*(vu16 *)REG_DISPCNT) = 0x15E0;
        (*(vu16 *)REG_BG0CNT) = 0x1F09;
        *(vu16 *)REG_BG2CNT = 0x3C02;
        Menu_ClearTextRectInline(0, 0, 30, 20);
        Menu_DrawLayoutInline(gTitleOptionsHeaderLayout);
        TitleMenu_DrawOptions();
        DmaCopy(3, gScriptTextTilemap, BG_SCREEN_ADDR(30), 0x800, 16);
        DmaCopy(3, MAP_TILEMAP_A, BG_SCREEN_ADDR(28), 0x800, 16);
        DmaCopy(3, MAP_TILEMAP_B, BG_SCREEN_ADDR(29), 0x800, 16);
        gBlendControl = 0x441;
        gBlendCoefficients = 0x70F;
        (*(vu16 *)REG_BLDCNT) = 0x441;
        (*(vu16 *)REG_BLDALPHA) = 0x70F;
        Palette_SaveTransitionSource();
        Transition_Start(3);
        gScenePhase = 19;
        System_ResumeAudioAndDisplay();
        Sound_PlayBgm(22, 255);
        break;
    case 27:
        TitleMenu_UpdateInputAndCursor();
        if (gScreenTransitionType == 0)
            gScenePhase = 28;
        break;
    case 28:
        TitleMenu_UpdateInputAndCursor();
        if (gScreenTransitionType == 0)
        {
            const u8 *source;

            System_SuspendAudioAndBlankDisplay();
            Scene_LoadSharedTiles(0);
            LZ77UnCompVram((void *)(gMenuSpriteGraphicsSources[11]), TITLE_CURSOR_TILES);
            DmaCopy(3, gMenuSharedSpritePalette, OBJ_PALETTES[2], 32, 16);
            LZ77UnCompVram((void *)(gTitleOptionTiles), TITLE_OPTION_TILES);
            DmaCopy(3, gTitleOptionPalettes, OBJ_PALETTES[10], 64, 16);
            DmaCopy(3, gMenuTextPalettes, PALETTE_RAM[14], 64, 16);
            source = (const u8 *)&gCollectionCardBackgroundResources;
            LZ77UnCompVram((void *)(source), BG_SCREEN_ADDR(24));
            source += offsetof(struct CollectionCardBackgroundResources, palettes);
            DmaCopy(3, source, PALETTE_RAM[8], 96, 16);
            DmaCopy(3, gMenuTextPalettes, PALETTE_RAM[14], 64, 16);
            (*(vu16 *)REG_BG0CNT) = 0x1F08;
            *(vu16 *)REG_BG1CNT = 0x1E09;
            gBlendControl = 0;
            gBlendCoefficients = 15;
            (*(vu16 *)REG_BLDCNT) = 0;
            (*(vu16 *)REG_BLDALPHA) = 15;
            (*(vu16 *)REG_DISPCNT) = 0x13E0;
            Menu_ClearTextRectInline(0, 0, 30, 20);
            DmaCopy(3, MENU_TEXT_ADDR(0, 0), BG_SCREEN_ADDR(31), 0x800, 16);
            index = 0;
            dest = SCENE_EFFECT_TILEMAP;
            for (; index < 640; index++)
                *dest++ = 0;
            Collection_DrawCardPreview(gCollectionSelectedCardId);
            DmaCopy(3, SCENE_EFFECT_TILEMAP, BG_SCREEN_ADDR(30), 0x800, 16);
            Menu_TransitionToPage(5);
            Palette_SaveTransitionSource();
            Transition_Start(3);
            gScenePhase = 29;
            (*(vu16 *)REG_BG0HOFS) = 0;
            (*(vu16 *)REG_BG0VOFS) = 0;
            System_ResumeAudioAndDisplay();
        }
        break;
    case 29:
        TitleMenu_UpdateInputAndCursor();
        if (gScreenTransitionType == 0)
        {
            gBlendControl = 0x1241;
            gBlendCoefficients = 15;
            gScenePhase = 30;
        }
        break;
    case 9:
    case 30:
    updateInput:
        TitleMenu_UpdateInputAndCursor();
        break;
    case 33:
        TitleMenu_UpdateInputAndCursor();
        if ((gBlendCoefficients & 0x1F00) == 0x1E00)
        {
            gBlendCoefficients |= 0x1F00;
            gScenePhase = 30;
        }
        else
            gBlendCoefficients += 0x300;
        break;
    case 32:
        TitleMenu_UpdateInputAndCursor();
        if ((gBlendCoefficients & 0x1F00) == 0x100)
        {
            gBlendCoefficients &= 0xFF;
            gScenePhase = 30;
        }
        else
            gBlendCoefficients -= 0x300;
        break;
    case 38:
        TitleMenu_UpdateInputAndCursor();
        if ((gBlendCoefficients & 0x1F00) == 0x100)
        {
            gBlendCoefficients &= 0xFF;
            gScenePhase = 31;
        }
        else
            gBlendCoefficients -= 0x300;
        break;
    case 31:
        gLinkServiceState = 9;
        gLinkTransferStatus = 255;
        TitleMenu_UpdateInputAndCursor();
        Collection_DrawCardPreview(gCollectionSelectedCardId);
        gScenePhase = 33;
        break;
    case 34:
        TitleMenu_UpdateInputAndCursor();
        if ((gBlendCoefficients & 0x1F00) == 0x100)
        {
            gBlendCoefficients &= 0xFF;
            gCardLinkSendBuffer[0] = gCollectionSelectedCardId;
            gCardLinkSendBuffer[1] = (gCollectionSelectedCardId & 0xFF00) >> 8;
            gLinkTransferStatus = 0;
            gLinkServiceState = 8;
            gCardLinkTimeoutFrames = 600;
            gScenePhase = 35;
        }
        else
            gBlendCoefficients -= 0x300;
        break;
    case 35:
    {
        TitleMenu_UpdateInputAndCursor();
        index = 0;
        switch ((s32)gLinkTransferStatus)
        {
        case 1:
            Menu_ShowHintWithPalette(0x16C, 11);
            break;
        case 2:
            Menu_ShowHintWithPalette(0x16F, 11);
            if (gKeysPressed & 3)
            {
                index = 1;
                Sound_PlaySfx(2, 0, 0);
            }
            break;
        case 0:
        case 255:
            Menu_ShowHintWithPalette(0x16B, 11);
            break;
        case 3:
            Menu_ShowHintWithPalette(0x16D, 11);
            if (gKeysPressed & 3)
            {
                index = 1;
                Sound_PlaySfx(3, 0, 0);
            }
            break;
        case 5:
            Menu_ShowHintWithPalette(0x16C, 11);
            gMenuPhase = 2;
            Menu_TransitionToPage(255);
            gCollectionCommittedRecordId = gCardLinkReceiveBuffer[0]
                + (gCardLinkReceiveBuffer[1] << 8);
            if (gCollectionCommittedRecordId > 175)
                gCollectionCommittedRecordId = 0;
            Collection_RemoveCard(gCollectionSelectedCardId);
            Collection_AddCard(gCollectionCommittedRecordId);
            Collection_RefreshOwnedCardCount();
            gCollectionSelectedCardId = gCollectionCommittedRecordId;
            Save_PackBonusSlot();
            gSaveIoState = 3;
            gSaveIoBlockIndex = 12;
            gMenuSaveRequestKind = 0;
            Menu_ShowHintWithPalette(24, 11);
            gScenePhase = 37;
            break;
        }
        if (index != 0)
        {
            gMenuPhase = 2;
            Menu_TransitionToPage(255);
            gScenePhase = 36;
        }
        break;
    }
    case 36:
        TitleMenu_UpdateInputAndCursor();
        gScenePhase = 31;
        break;
    case 37:
        TitleMenu_UpdateInputAndCursor();
        if (Save_UpdateIo(1) == 0)
            gScenePhase = 31;
        break;
    default:
        gScenePhase = 0;
        break;
    }
}

/**
 * @brief 按卡片描述绘制卡框、编号及角色／龙／敌人动画预览
 *
 * @note kind 2 为角色，1 为龙，0/3 为敌人；标志 0x80 选择横向扩展卡框。
 *       动画资源来自传入卡片的描述，显示编号读取全局选中卡号。
 * @address 0x08012530
 */
void Collection_DrawCardPreview(u16 cardId)
{
    const u8 *cards = gCollectionCardDescriptors;
    s32 offset = cardId * 4;
    u16 animationId;
    s32 kind = cards[offset];
    s32 fieldOffset = offset + 1;
    u32 flags;
    const u16 *layout;
    u32 paletteBits;
    u32 numberPalette;
    u16 *dest;
    u16 row;
    u16 column;
    struct ActorState *actor;

    animationId = cards[fieldOffset];
    fieldOffset = offset + 2;
    animationId |= cards[fieldOffset] << 8;
    offset += 3;
    flags = cards[offset];

    switch (kind)
    {
    case 2:
        layout = gCollectionCharacterCardFrameTiles;
        paletteBits = 0xA000;
        break;
    case 1:
        layout = gCollectionDragonCardFrameTiles;
        paletteBits = 0x9000;
        break;
    case 0:
    case 3:
        layout = gCollectionEnemyCardFrameTiles;
        paletteBits = 0x8000;
        break;
    }

    dest = COLLECTION_CARD_FRAME_DEST;
    row = 0;
    flags &= 0x80;
    numberPalette = paletteBits >> 12;
    if (flags == 0)
    {
        for (; row < 16; row++)
        {
            for (column = 0; column < 16; column++)
            {
                if (column < 10)
                {
                    *dest = (*layout & 0xC3F) | paletteBits | 0x200;
                    layout++;
                }
                else
                    *dest = 0;
                dest++;
            }
            dest += 16;
        }
        Menu_DrawDecimal(COLLECTION_CARD_NUMBER_DEST, gCollectionSelectedCardId, numberPalette &= 15);
    }
    else
    {
        s32 firstFooterRow = 13;
        s32 lastFooterRow = 14;

        for (; row < 16; row++)
        {
            u16 repeats;
            u16 repeatColumn;

            column = 0;
            repeats = 7;
            repeatColumn = 8;
            if (row <= lastFooterRow && row >= firstFooterRow)
                repeatColumn = 1;
            for (; column < 10; column++)
            {
                if (column != repeatColumn)
                {
                    *dest = (*layout & 0xC3F) | paletteBits | 0x200;
                    layout++;
                    dest++;
                }
                else
                {
                    const u16 *next = layout + 1;

                    while (repeats != 0)
                    {
                        *dest = (*layout & 0xC3F) | paletteBits | 0x200;
                        dest++;
                        repeats--;
                    }
                    layout = next;
                }
            }
            dest += 16;
        }
        Menu_DrawDecimal(COLLECTION_WIDE_CARD_NUMBER_DEST, gCollectionSelectedCardId, numberPalette &= 15);
    }

    gSceneEffectTilemapUploadPending = 1;
    actor = &gActorStates[0];
    Sprite_FreeChain(&gSpriteNodes[actor->spriteSlot]);
    Actor_InitSprite(0);
    switch (kind)
    {
    default:
        Actor_LoadPreviewAnimation(animationId, 0);
        Actor_StartCustomAnimation(0, 0);
        actor->scriptEntryOrMenuState = 0;
        break;
    case 1:
        Actor_LoadAnimation(animationId, 0, 5);
        Actor_StartCustomAnimation(0, 0);
        actor->x = gCameraX + 0x88;
        actor->y = gCameraY + 0x4C;
        actor->scriptEntryOrMenuState = 0;
        break;
    case 2:
        Actor_LoadAnimation(animationId, 0, 5);
        Actor_StartCustomAnimation(0, 0);
        actor->x = gCameraX + 0x88;
        actor->y = gCameraY + 0x58;
        actor->scriptEntryOrMenuState = 0;
        break;
    }
}

/* The title input routine inlines the slot and signature checks. */
static inline u8 TitleMenu_CheckSlotSignatureInline(u8 slot)
{
    const u8 *slotData;
    u8 index;

    if (slot > 3)
        return 0xFF;
    slotData = SAVE_SLOT_BUFFER + slot * SAVE_SLOT_SIZE;
    for (index = 0; index <= 0xB; index++)
    {
        if (*slotData != gSaveSlotSignature[index])
            return 1;
        slotData++;
    }
    return 0;
}

/**
 * @brief 处理标题、读档、选项、画廊、卡片及通信交换页输入、光标移动与精灵提交
 *
 * @note 保留六个页面的按键优先级；移动结束时刷新页面，画廊 A 键控制 BG0 显示。
 * @address 0x08012790
 */
void TitleMenu_UpdateInputAndCursor(void)
{
    u16 tile;
    u8 changed;
    u8 index;

    gMenuCursor.blinkCounter++;
    tile = ((u8)(gMenuCursor.blinkCounter & 8) * 2) | 0x1C0;
    if (gMenuCursor.flags & 1)
        tile += 0x20;
    changed = 0;

    if (gMenuCursor.transitionFrames != 0)
    {
        gMenuCursor.transitionFrames--;
        if (gMenuCursor.transitionFrames == 0)
        {
            switch (gMenuPage)
            {
            case 1:
                Menu_EraseSingleRowText(Menu_GetTextAddress(3, 18), gTitleGameArtsCreditText);
                Menu_EraseSingleRowText(Menu_GetTextAddress(3, 19), gTitleMediaRingsCreditText);
                break;
            case 5:
                Collection_DrawCardMenu();
                break;
            }
            gMenuCursor.flags |= 1;
            gMenuCursor.x = gMenuCursor.targetX;
            gMenuCursor.y = gMenuCursor.targetY;
        }
        else
        {
            u16 deltaX = gMenuCursor.targetX - gMenuCursor.originX;
            u16 deltaY = gMenuCursor.targetY - gMenuCursor.originY;

            index = 8 - gMenuCursor.transitionFrames;

            gMenuCursor.x = gMenuCursor.originX + ((deltaX * index) >> 3);
            gMenuCursor.y = gMenuCursor.originY + ((deltaY * index) >> 3);
        }
    }
    else
    {
        switch (gMenuPage)
        {
        case 0:
            if (gKeysPressed & 9)
            {
                Sound_PlaySfx(1, 0, 0);
                gSceneTransitionCounter = 0x20;
                gScenePhase = 9;
                gMenuPhase = 0;
                gMenuSavedSelections[1] = gSaveBonusSlotValid;
                Menu_TransitionToPage(1);
            }
            if ((gSceneTransitionCounter & 0x20) == 0)
                Menu_DrawSingleRowText(Menu_GetTextAddress(6, 14), gTitlePressStartText, 11);
            else
                Menu_EraseSingleRowText(Menu_GetTextAddress(6, 14), gTitlePressStartText);
            Menu_DrawSingleRowText(Menu_GetTextAddress(3, 18), gTitleGameArtsCreditText, 11);
            Menu_DrawSingleRowText(Menu_GetTextAddress(3, 19), gTitleMediaRingsCreditText, 11);
            if ((gSceneTransitionCounter & 0x3F) == 0)
            {
                gTitleIdleCyclesRemaining--;
                if (gTitleIdleCyclesRemaining == 0)
                {
                    gScenePhase = 0x15;
                    Transition_Start(4);
                }
            }
            break;

        case 1:
            if (gKeysHeld & 0xC0)
            {
                if (gKeysHeld & 0x40)
                {
                    if (gMenuPhase != 0)
                    {
                        gMenuPhase--;
                        changed++;
                    }
                }
                else if (gKeysHeld & 0x80)
                {
                    if (gMenuPhase < 2)
                    {
                        gMenuPhase++;
                        changed++;
                    }
                }
                if (changed != 0)
                {
                    Sound_PlaySfx(0, 0, 0);
                    Menu_TransitionToPage(0xFF);
                }
            }
            else if (gKeysPressed & 1)
            {
                switch (gMenuPhase)
                {
                case 0:
                    gScenePhase = 0xA;
                    Palette_SaveTransitionSource();
                    Transition_Start(4);
                    break;
                case 1:
                    gScenePhase = 0xB;
                    Palette_SaveTransitionSource();
                    Transition_Start(6);
                    break;
                case 2:
                    gScenePhase = 0x12;
                    Palette_SaveTransitionSource();
                    Transition_Start(6);
                    break;
                }
                Sound_PlaySfx(1, 0, 0);
            }
            else if (gKeysPressed & 2)
            {
                Menu_EraseSingleRowText(Menu_GetTextAddress(12, 10), gTitleNewGameText);
                Menu_EraseSingleRowText(Menu_GetTextAddress(12, 12), gTitleLoadGameText);
                Menu_EraseSingleRowText(Menu_GetTextAddress(12, 14), gTitleOptionText);
                gSceneTransitionCounter = 0;
                gTitleIdleCyclesRemaining = 16;
                gScenePhase = 8;
                Sound_PlaySfx(2, 0, 0);
                Menu_TransitionToPage(0);
                break;
            }
            for (index = 0; index <= 2; index++)
            {
                if (index == gMenuPhase)
                    changed = 13;
                else
                    changed = 11;
                {
                    u16 *address = Menu_GetTextAddress(12, index * 2 + 10);
                    const u8 *const *texts = gMenuLabelLayouts + 4;

                    Menu_DrawSingleRowText(address, texts[index], changed);
                }
            }
            break;

        case 2:
            if (gKeysHeld & 0xF0)
            {
                if (gMenuPhase <= 2)
                {
                    if (gKeysHeld & 0x40)
                    {
                        if (gMenuPhase != 0)
                        {
                            gMenuPhase--;
                            changed++;
                        }
                    }
                    else if (gKeysHeld & 0x80)
                    {
                        if (gMenuPhase < 2)
                        {
                            gMenuPhase++;
                            changed++;
                        }
                    }
                    gMenuSaveSlot = gMenuPhase;
                }
                else
                {
                    if (gKeysHeld & 0x20)
                    {
                        if (gMenuPhase == 4)
                        {
                            gMenuPhase--;
                            changed++;
                        }
                    }
                    else if (gKeysHeld & 0x10)
                    {
                        if (gMenuPhase == 3)
                        {
                            gMenuPhase++;
                            changed++;
                        }
                    }
                }
                if (changed != 0)
                {
                    Sound_PlaySfx(0, 0, 0);
                    Menu_TransitionToPage(0xFF);
                }
            }
            else if (gKeysPressed & 1)
            {
                if (gMenuPhase <= 2)
                {
                    u8 invalid;

                    invalid = TitleMenu_CheckSlotSignatureInline(gMenuSaveSlot);
                    if (invalid != 0)
                        Sound_PlaySfx(3, 0, 0);
                    else
                    {
                        gMenuPhase = 4;
                        Sound_PlaySfx(1, 0, 0);
                        Menu_TransitionToPage(0xFF);
                    }
                }
                else
                {
                    if (gMenuPhase == 3)
                    {
                        gScenePhase = 0x11;
                        Palette_SaveTransitionSource();
                        Transition_Start(4);
                        Sound_FadeOutBgm(0x2E);
                    }
                    else
                    {
                        gMenuPhase = gMenuSaveSlot;
                        Menu_TransitionToPage(0xFF);
                    }
                    Sound_PlaySfx(1, 0, 0);
                }
            }
            else if (gKeysPressed & 2)
            {
                if (gMenuPhase <= 2)
                {
                    gScenePhase = 0xF;
                    Palette_SaveTransitionSource();
                    Transition_Start(6);
                }
                else
                {
                    gMenuPhase = gMenuSaveSlot;
                    Menu_TransitionToPage(0xFF);
                }
                Sound_PlaySfx(2, 0, 0);
            }
            Menu_SetTextVisibleInline(gMenuSaveOptionTexts[1], 11, 1);
            for (index = 0; index <= 1; index++)
            {
                if (gMenuPhase > 2)
                {
                    if (gMenuPhase == index + 3)
                        changed = 13;
                    else
                        changed = 11;
                    Menu_SetTextVisibleInline(gMenuSaveOptionTexts[index + 3], changed, 1);
                }
                else
                    Menu_SetTextVisibleInline(gMenuSaveOptionTexts[index + 3], 11, 0);
            }
            break;

        case 3:
            if (gKeysHeld & 0x3F0)
            {
                if (gKeysHeld & 0x40)
                {
                    if (gMenuPhase != 0)
                    {
                        gMenuPhase--;
                        changed++;
                    }
                }
                else if (gKeysHeld & 0x80)
                {
                    if (gMenuPhase < 3)
                    {
                        gMenuPhase++;
                        changed++;
                    }
                }
                else if (((gKeysPressed & 0x10) || (gKeysHeld & 0x100))
                    && (gMenuExtraFlags & 1))
                {
                    switch (gMenuPhase)
                    {
                    case 0:
                        gSoundTestBgmId++;
                        if (gSoundTestBgmId > 65)
                            gSoundTestBgmId = 0;
                        Sound_PlaySfx(0, 0, 0);
                        break;
                    case 1:
                        gSoundTestSfxIndex++;
                        if (gSoundTestSfxIndex > 94)
                            gSoundTestSfxIndex = 0;
                        Sound_PlaySfx(0, 0, 0);
                        break;
                    }
                }
                else if (((gKeysPressed & 0x20) || (gKeysHeld & 0x200))
                    && (gMenuExtraFlags & 1))
                {
                    switch (gMenuPhase)
                    {
                    case 0:
                        if (gSoundTestBgmId == 0)
                            gSoundTestBgmId = 66;
                        gSoundTestBgmId--;
                        Sound_PlaySfx(0, 0, 0);
                        break;
                    case 1:
                        if (gSoundTestSfxIndex == 0)
                            gSoundTestSfxIndex = 95;
                        gSoundTestSfxIndex--;
                        Sound_PlaySfx(0, 0, 0);
                        break;
                    }
                }
                if (changed != 0)
                {
                    Sound_PlaySfx(0, 0, 0);
                    Menu_TransitionToPage(0xFF);
                }
            }
            else if (gKeysPressed & 1)
            {
                switch (gMenuPhase)
                {
                case 0:
                    if (gMenuExtraFlags & 1)
                    {
                        if (gSoundTestPlayingBgmIdPlusOne == 0 || gSoundTestPlayingBgmIdPlusOne - 1 != gSoundTestBgmId)
                        {
                            Sound_PlayBgm(gSoundTestBgmId, 0xFF);
                            gSoundTestPlayingBgmIdPlusOne = gSoundTestBgmId + 1;
                        }
                        else
                        {
                            Sound_StopBgm();
                            gSoundTestPlayingBgmIdPlusOne = 0;
                        }
                    }
                    break;
                case 1:
                    if (gMenuExtraFlags & 1)
                        Sound_PlaySfx(gSoundTestSfxIds[gSoundTestSfxIndex], 0, 0);
                    break;
                case 2:
                    for (index = 0; index <= 179; index++)
                    {
                        if ((u8)Collection_GetCardCount(index) != 0)
                        {
                            gCollectionSelectedCardId = index;
                            break;
                        }
                    }
                    if (index == 180)
                    {
                        Menu_TransitionToPage(0xFF);
                        Sound_PlaySfx(3, 0, 0);
                    }
                    else
                    {
                        gCollectionCommittedRecordId = gCollectionSelectedCardId;
                        Sound_PlaySfx(1, 0, 0);
                        gScenePhase = 0x1B;
                        Palette_SaveTransitionSource();
                        Transition_Start(4);
                        Sound_FadeOutBgm(0x2E);
                        Collection_RefreshOwnedCardCount();
                    }
                    break;
                case 3:
                    for (index = 0; index <= 48; index++)
                    {
                        if (Collection_GetEventFlag(gGalleryUnlockEventIds[index]) != 0)
                        {
                            gCollectionCommittedRecordId = index;
                            gCollectionSelectedCardId = index;
                            Sound_PlaySfx(1, 0, 0);
                            gScenePhase = 0x16;
                            Palette_SaveTransitionSource();
                            Transition_Start(4);
                            Sound_FadeOutBgm(0x2E);
                            break;
                        }
                    }
                    if (index > 48)
                    {
                        Menu_TransitionToPage(0xFF);
                        Sound_PlaySfx(3, 0, 0);
                    }
                    break;
                }
            }
            else if (gKeysPressed & 2)
            {
                gScenePhase = 0xF;
                Palette_SaveTransitionSource();
                Transition_Start(6);
                Sound_PlaySfx(2, 0, 0);
                Sound_PlayBgm(0x16, 0xFF);
            }
            break;

        case 4:
            if ((gKeysHeld & 1) && gCollectionSelectedCardId == gCollectionCommittedRecordId)
                (*(vu16 *)REG_DISPCNT) &= 0xFEFF;
            else
            {
                (*(vu16 *)REG_DISPCNT) |= 0x100;
                if (gKeysPressed & 0x200)
                {
                    index = gCollectionCommittedRecordId;
                    index--;
                    while (index != gCollectionSelectedCardId)
                    {
                        if (index == 0xFF)
                            index = 48;
                        if (Collection_GetEventFlag(gGalleryUnlockEventIds[index]) != 0)
                            break;
                        index--;
                    }
                    gCollectionSelectedCardId = index;
                    gCollectionCommittedRecordId = index;
                    changed++;
                }
                else if (gKeysPressed & 0x100)
                {
                    index = gCollectionCommittedRecordId;
                    index++;
                    while (index != gCollectionSelectedCardId)
                    {
                        if (index > 48)
                            index = 0;
                        if (Collection_GetEventFlag(gGalleryUnlockEventIds[index]) != 0)
                            break;
                        index++;
                    }
                    gCollectionSelectedCardId = index;
                    gCollectionCommittedRecordId = index;
                    changed++;
                }
                else if (gKeysPressed & 0x20)
                {
                    index = gCollectionSelectedCardId;
                    do
                    {
                        index--;
                        if (index == gCollectionSelectedCardId)
                            break;
                        if (index == 0xFF)
                            index = 48;
                        if (Collection_GetEventFlag(gGalleryUnlockEventIds[index]) != 0)
                            break;
                    } while (1);
                    gCollectionSelectedCardId = index;
                    Sound_PlaySfx(0, 0, 0);
                }
                else if (gKeysPressed & 0x10)
                {
                    index = gCollectionSelectedCardId;
                    do
                    {
                        index++;
                        if (index == gCollectionSelectedCardId)
                            break;
                        if (index > 48)
                            index = 0;
                        if (Collection_GetEventFlag(gGalleryUnlockEventIds[index]) != 0)
                            break;
                    } while (1);
                    gCollectionSelectedCardId = index;
                    Sound_PlaySfx(0, 0, 0);
                }
                else if (gKeysPressed & 2)
                {
                    Palette_SaveTransitionSource();
                    Transition_Start(4);
                    Menu_TransitionToPage(3);
                    gScenePhase = 0x18;
                    Sound_PlaySfx(2, 0, 0);
                }
                else if (gKeysPressed & 1)
                {
                    gCollectionCommittedRecordId = gCollectionSelectedCardId;
                    changed++;
                }
            }
            if (changed != 0)
            {
                Sound_PlaySfx(1, 0, 0);
                gScenePhase = 0x16;
                Palette_SaveTransitionSource();
                Transition_Start(4);
            }
            Menu_ClearTextBufferInline(MENU_TEXT_ADDR(15, 17), 2, 2);
            Menu_DrawDecimal(MENU_TEXT_ADDR(16, 17), gCollectionSelectedCardId, 12);
            {
                u8 frame = (gMenuTextBlinkCounter >> 3) & 1;
                u16 arrow = frame | 0x428;

                *MENU_TEXT_ADDR(14, 18) = arrow + 0xB240;
                arrow = frame + 0x28;
                *MENU_TEXT_ADDR(17, 18) = arrow + 0xB240;
            }
            break;

        case 5:
            Collection_DrawCompletionRating(gCollectionOwnedCardTypeCount);
            if ((gBlendCoefficients & 0x1F00) == 0x1F00)
            {
                if (gMenuSavedSelections[gMenuPage] == 0)
                {
                    if (gKeysPressed & 3)
                    {
                        gScenePhase = 0x20;
                        Sound_PlaySfx(1, 0, 0);
                        break;
                    }
                }
                else if (gMenuPhase == 2)
                {
                    if (gKeysPressed & 2)
                    {
                        gScenePhase = 0x20;
                        Menu_TransitionToPage(0xFF);
                        Sound_PlaySfx(2, 0, 0);
                        break;
                    }
                    else if (gKeysPressed & 1)
                    {
                        gMenuPhase = 4;
                        Menu_TransitionToPage(0xFF);
                        Sound_PlaySfx(1, 0, 0);
                        break;
                    }
                }
            }
            if (gKeysPressed & 0x40)
            {
                if (gMenuPhase == 1)
                {
                    gMenuPhase--;
                    gMenuSavedSelections[gMenuPage] = gMenuPhase;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(0, 0, 0);
                }
            }
            else if (gKeysPressed & 0x80)
            {
                if (gMenuPhase == 0)
                {
                    gMenuPhase++;
                    gMenuSavedSelections[gMenuPage] = gMenuPhase;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(0, 0, 0);
                }
            }
            else if (gKeysHeld & 0x20)
            {
                if (gMenuPhase == 2)
                {
                    gCollectionSelectedCardId--;
                    if ((gBlendCoefficients & 0x1F00) == 0x1F00)
                    {
                        for (;; gCollectionSelectedCardId--)
                        {
                            if (gCollectionSelectedCardId > 175)
                                gCollectionSelectedCardId = 175;
                            if ((u8)Collection_GetCardCount(gCollectionSelectedCardId) != 0)
                                break;
                        }
                    }
                    else if (gCollectionSelectedCardId > 175)
                        gCollectionSelectedCardId = 175;
                    goto cardChanged;
                }
                else if (gMenuPhase == 4)
                {
                    gMenuPhase--;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(0, 0, 0);
                }
            }
            else if (gKeysHeld & 0x10)
            {
                if (gMenuPhase == 2)
                {
                    gCollectionSelectedCardId++;
                    if ((gBlendCoefficients & 0x1F00) == 0x1F00)
                    {
                        for (;; gCollectionSelectedCardId++)
                        {
                            if (gCollectionSelectedCardId > 175)
                                gCollectionSelectedCardId = 0;
                            if ((u8)Collection_GetCardCount(gCollectionSelectedCardId) != 0)
                                break;
                        }
                    }
                    else if (gCollectionSelectedCardId > 175)
                        gCollectionSelectedCardId = 0;
                    goto cardChanged;
                }
                else if (gMenuPhase == 3)
                {
                    gMenuPhase++;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(0, 0, 0);
                }
            }
            else if (gKeysPressed & 1)
            {
                if (gMenuPhase <= 1)
                {
                    if (gMenuPhase == 1)
                    {
                        System_SetCardLinkIrqMode(1);
                        gLinkServiceState = 8;
                        gLinkTransferStatus = 0xFF;
                    }
                    gMenuSavedSelections[gMenuPage] = gMenuPhase;
                    gMenuPhase = 2;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(1, 0, 0);
                }
                else if (gMenuPhase == 2)
                {
                    if ((u8)Collection_GetCardCount(gCollectionSelectedCardId) != 0)
                    {
                        gScenePhase = 0x1F;
                        Sound_PlaySfx(1, 0, 0);
                    }
                    else
                        Sound_PlaySfx(3, 0, 0);
                }
                else if (gMenuPhase == 4)
                {
                    gMenuPhase = 2;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(1, 0, 0);
                }
                else if (gMenuPhase == 3)
                {
                    gScenePhase = 0x22;
                    gMenuPhase = 5;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(1, 0, 0);
                }
            }
            else if (gKeysPressed & 2)
            {
                if (gMenuPhase <= 1)
                {
                    Sound_PlaySfx(1, 0, 0);
                    Menu_TransitionToPage(3);
                    gScenePhase = 0x18;
                    gBlendControl = 0;
                    Palette_SaveTransitionSource();
                    Transition_Start(4);
                }
                else if (gMenuPhase == 2)
                {
                    gMenuPhase = gMenuSavedSelections[gMenuPage];
                    if (gMenuPhase == 1)
                        System_SetCardLinkIrqMode(0);
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(2, 0, 0);
                }
                else if (gMenuPhase <= 4)
                {
                    gMenuPhase = 2;
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(2, 0, 0);
                }
            }
            else if (gKeysPressed & 0x100)
            {
                if (gMenuPhase == 2)
                {
                    if (gCollectionSelectedCardId <= 54)
                        gCollectionSelectedCardId = 55;
                    else if (gCollectionSelectedCardId <= 59)
                        gCollectionSelectedCardId = 60;
                    else
                        gCollectionSelectedCardId = 0;
                    if ((gBlendCoefficients & 0x1F00) == 0x1F00)
                    {
                        for (;; gCollectionSelectedCardId++)
                        {
                            if (gCollectionSelectedCardId > 175)
                                gCollectionSelectedCardId = 0;
                            if ((u8)Collection_GetCardCount(gCollectionSelectedCardId) != 0)
                                break;
                        }
                    }
                    goto cardChanged;
                }
            }
            else if (gKeysPressed & 0x200)
            {
                if (gMenuPhase == 2)
                {
                    gCollectionSelectedCardId += 10;
                    if (gCollectionSelectedCardId > 175)
                        gCollectionSelectedCardId -= 176;
                    if ((gBlendCoefficients & 0x1F00) == 0x1F00)
                    {
                        for (;; gCollectionSelectedCardId++)
                        {
                            if (gCollectionSelectedCardId > 175)
                                gCollectionSelectedCardId = 0;
                            if ((u8)Collection_GetCardCount(gCollectionSelectedCardId) != 0)
                                break;
                        }
                    }
                    goto cardChanged;
                }
            }
            break;

cardChanged:
            Menu_TransitionToPage(0xFF);
            Sound_PlaySfx(0, 0, 0);
            if ((gBlendCoefficients & 0x1F00) == 0x1F00)
                gScenePhase = 0x26;
            break;
        }
    }
    {
        struct SpriteNode *node = &gSpriteNodes[112];
        u32 attr0 = node->attr0 & 0xFF00;

        attr0 += (u8)gMenuCursor.y;
        node->attr0 = attr0;
        node->attr1 = (node->attr1 & 0xFE00) + ((gMenuCursor.x - 32) & 0x1FF);
        node->attr2 = (node->attr2 & 0xFC00) + tile;
        gSpriteDrawOrder[0] = node;
    }
    if ((u16)(gScenePhase - 0x1E) <= 7 && (gBlendCoefficients & 0x1F00) != 0)
    {
        struct ActorState *actor = &gActorStates[0];

        if (actor->spriteSlot != 0 && actor->scriptEntryOrMenuState != 0x80)
        {
            s32 x;
            s32 height;

            Actor_UpdateAnimation(0);
            x = (s16)Actor_GetRenderX(actor);
            height = (s16)Actor_GetRenderHeight(actor);
            Sprite_QueueChain(x, (u16)actor->y, actor->spriteSlot, height, actor->flags);
        }
    }
    if (gVBlankUpdateMode == 5)
        Link_UpdateCardExchange();
    gMenuTextBlinkCounter++;
}

/**
 * @brief 清文本背景并绘制 New Game、Load Game、Option 等标题选项
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。 当前保留空函数，以上为原 ROM 行为。
 * @address 0x08013870
 */
void TitleMenu_DrawMainOptions(void)
{
    Menu_ClearTextRectInline(0, 0, 30, 20);
    Menu_DrawLayoutInline(gTitleLunarLogoLayout);
    Menu_DrawSingleRowText(Menu_GetTextAddress(12, 7), gTitleLogoSubtitleGlyphs, 11);
}

/**
 * @brief 绘制标题选项页的 BGM、SE、CARD 和 GALLERY
 *
 * @note 当前项使用调色板 13，其余使用 11；声音测试未解锁时 BGM/SE 显示问号，
 *       解锁后分别绘制八位曲目编号和十六位音效编号。
 * @address 0x08013934
 */
void TitleMenu_DrawOptions(void)
{
    u8 index;
    u8 palette;

    for (index = 0; index < 4; index++)
    {
        if (index == gMenuPhase)
            palette = 13;
        else
            palette = 11;

        if (index < 2)
        {
            if ((gMenuExtraFlags & 1) == 0)
                Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[index + 10], palette, 1);
            else
            {
                Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[index], palette, 1);
                if (index == 0)
                {
                    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(25, 4), 3, 2);
                    Menu_DrawDecimal(MENU_TEXT_ADDR(27, 4), gSoundTestBgmId, palette);
                }
                else
                {
                    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(25, 7), 3, 2);
                    Menu_DrawDecimal(MENU_TEXT_ADDR(27, 7), gSoundTestSfxIndex, palette);
                }
            }
        }
        else
            Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[index], palette, 1);
    }
}

/**
 * @brief 按普通卡片的已收集种类数绘制完成度星级
 *
 * @note 每次递增十六位动画计数；36/71/106/141 种依次增加普通旋转星，
 *       恰为 176 种时绘制五星，各星循环使用调色板 12..15。
 * @address 0x08013B0C
 */
void Collection_DrawCompletionRating(u16 ownedTypes)
{
    u16 frame;
    u32 palette;
    u16 flip;
    u32 tileBase = 0x204;
    u16 *dest;

    gCollectionRatingAnimationCounter++;
    flip = 0;
    dest = Menu_GetTextAddress(10, 2);
    if (ownedTypes == 176)
    {
        u32 firstTile;

        palette = (gCollectionRatingAnimationCounter >> 4) & 3;
        firstTile = (palette + 12) << 12;
        *dest-- = firstTile + tileBase;
        *dest-- = ((((palette + 1) & 3) + 12) << 12) + tileBase;
        *dest-- = ((((palette + 2) & 3) + 12) << 12) + tileBase;
        *dest-- = ((((palette + 3) & 3) + 12) << 12) + tileBase;
        *dest = ((((palette + 4) & 3) + 12) << 12) + tileBase;
    }
    else
    {
        frame = (gCollectionRatingAnimationCounter >> 2) & 3;
        if (frame == 3)
        {
            frame = 1;
            flip = 0x400;
        }
        frame += tileBase;
        palette = 0xD000;
        *dest-- = 0xB001;
        *dest = ownedTypes > 140 ? flip + (frame + palette) : 0xB001;
        dest--;
        *dest = ownedTypes > 105 ? flip + (frame + palette) : 0xB001;
        dest--;
        *dest = ownedTypes > 70 ? flip + (frame + palette) : 0xB001;
        dest--;
        *dest = ownedTypes > 35 ? flip + (frame + palette) : 0xB001;
    }
}

/**
 * @brief 绘制查看／交换选项、所选卡号、持有数量、确认文字及阶段提示
 *
 * @note 显示完整十六位卡号，持有数按卡号低八位查询；阶段 3/4 显示确认选项，其余阶段擦除。
 * @address 0x08013C00
 */
void Collection_DrawCardMenu(void)
{
    u8 index;
    u8 palette;
    u8 count;

    Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[4], 11, 1);
    for (index = 0; index < 2; index++)
    {
        if (index == gMenuSavedSelections[gMenuPage])
            palette = 13;
        else
            palette = 11;
        Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[index + 5], palette, 1);
    }

    count = (u8)Collection_GetCardCount(gCollectionSelectedCardId);
    palette = 12;
    if (count != 0)
        palette = 13;
    Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[7], 11, 1);
    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(4, 11), 6, 2);
    Menu_DrawDecimal(MENU_TEXT_ADDR(6, 11), gCollectionSelectedCardId, palette);
    *Menu_GetTextAddress(8, 12) = 0xB26D;
    Menu_DrawDecimal(MENU_TEXT_ADDR(9, 11), count, 12);

    if ((u8)(gMenuPhase - 3) <= 1)
    {
        for (index = 0; index < 2; index++)
        {
            if (index + 3 == gMenuPhase)
                palette = 13;
            else
                palette = 11;
            Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[index + 8], palette, 1);
        }
    }
    else
    {
        Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[8], 11, 0);
        Menu_SetTextVisibleInline(gTitleOptionLabelLayouts[9], 11, 0);
    }

    switch (gMenuPhase)
    {
    case 2:
        if (palette == 12)
            Menu_ShowHintWithPalette(0x172, 11);
        else
        {
            const u8 *cards = gCollectionCardDescriptors;
            s32 offset = gCollectionSelectedCardId * 4;

            switch (cards[offset])
            {
            default:
            {
                s32 flagOffset = offset + 3;

                Menu_ShowHintWithPalette((cards[flagOffset] & 0x7F) + 0x184, 11);
                break;
            }
            case 3:
            {
                s32 lowOffset = offset + 1;
                s32 value = cards[lowOffset];
                s32 highOffset = offset + 2;

                value += cards[highOffset] << 8;
                Menu_ShowHintWithPalette((u16)(value + 0xF3), 11);
                break;
            }
            case 0:
            {
                s32 lowOffset = offset + 1;
                s32 value = cards[lowOffset];
                s32 highOffset = offset + 2;

                value += cards[highOffset] << 8;
                Menu_DrawHintText(gEnemyNames + value * 9, 11);
                break;
            }
            }
        }
        break;
    case 0:
        Menu_ShowHintWithPalette(0x168, 11);
        break;
    case 1:
        Menu_ShowHintWithPalette(0x169, 11);
        break;
    case 3:
    case 4:
        Menu_ShowHintWithPalette(0x16A, 11);
        break;
    }
}

/**
 * @brief 同步读 SRAM 并检查奖励槽签名
 *
 * @note 只检查十二字节签名；有效则解包奖励数据，否则清有效标志、额外标志、卡数及收集事件位。
 * @address 0x08013F3C
 */
void Save_LoadBonusData(void)
{
    u8 invalid;
    u16 index;

    gSaveIoState = 1;
    gSaveIoBlockIndex = 0;
    while (Save_UpdateIo(1) != 0)
    {
    }

    invalid = Save_CompareSlotSignature(SAVE_SLOT_BUFFER + 3 * SAVE_SLOT_SIZE);
    if (invalid == 0)
    {
        Save_UnpackBonusSlot();
        gSaveBonusSlotValid = 1;
    }
    else
    {
        gSaveBonusSlotValid = 0;
        gMenuExtraFlags = 0;
        for (index = 0; index < sizeof(gCollectionPackedCardCounts);)
            gCollectionPackedCardCounts[index++] = 0;
        for (index = 0; index < sizeof(gCollectionEventFlags);)
            gCollectionEventFlags[index++] = 0;
    }
}

/**
 * @brief 将额外菜单标志、九十字节卡片数量和八字节事件位打包到第四槽
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08013FE8
 */
void Save_PackBonusSlot(void)
{
    u8 *buffer = SAVE_SLOT_BUFFER + 3 * SAVE_SLOT_SIZE;
    u8 *source;
    u16 offset;
    u16 field;
    u16 remaining;
    u8 checksum;

    for (offset = 0; offset <= 11; offset++)
        buffer[offset] = 0xFF;
    checksum = 0;
    offset = 12;
    for (field = 0; (remaining = gSaveBonusFieldSizes[field]) != 0; field++)
    {
        source = gSaveBonusFieldPointers[field];
        while (remaining != 0)
        {
            buffer[offset] = *source;
            checksum += buffer[offset];
            offset++;
            source++;
            remaining--;
        }
    }
    buffer[offset] = checksum;
    for (offset = 0; offset <= 11; offset++)
        buffer[offset] = gSaveSlotSignature[offset];
}

/**
 * @brief 重新统计前 176 种普通卡片中非零数量的种类，四种特殊卡不计入完成度
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08014084
 */
void Collection_RefreshOwnedCardCount(void)
{
    u16 cardId;

    gCollectionOwnedCardTypeCount = 0;
    for (cardId = 0; cardId <= 175; cardId++)
    {
        if (cardId & 1)
        {
            if (gCollectionPackedCardCounts[cardId >> 1] & 0xF0)
                gCollectionOwnedCardTypeCount++;
        }
        else
        {
            if (gCollectionPackedCardCounts[cardId >> 1] & 0x0F)
                gCollectionOwnedCardTypeCount++;
        }
    }
}

/**
 * @brief 增加卡片的四位持有数，封顶为 5，保留相邻卡片的半字节
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x080140D0
 */
void Collection_AddCard(u8 cardId)
{
    u8 count;
    u8 value = gCollectionPackedCardCounts[cardId >> 1];

    if ((cardId & 1) != 0)
    {
        count = (value >> 4) + 1;
        if (count > 5)
            count = 5;
        count <<= 4;
        value = (value & 15) | count;
    }
    else
    {
        count = (value & 15) + 1;
        if (count > 5)
            count = 5;
        value = (value & 0xF0) | count;
    }
    gCollectionPackedCardCounts[cardId >> 1] = value;
}

/**
 * @brief 减少卡片的四位持有数，下限为 0，保留相邻卡片的半字节
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08014124
 */
void Collection_RemoveCard(u8 cardId)
{
    u8 value = gCollectionPackedCardCounts[cardId >> 1];
    u8 count;

    if ((cardId & 1) != 0)
    {
        count = value >> 4;
        if (count == 0)
            count = 1;
        count--;
        count <<= 4;
        value = (value & 15) | count;
    }
    else
    {
        count = value & 15;
        if (count == 0)
            count = 1;
        count--;
        value = (value & 0xF0) | (count );
    }
    gCollectionPackedCardCounts[cardId >> 1] = value;
}

/**
 * @brief 内联建立每六十四条提示文本的分组指针
 *
 * @note 提示以 FF 分隔，连续两个 FF 标记末尾；对应 Menu_InitHintBanks 的展开。
 */
static inline void Menu_InitHintBanksInline(void)
{
    const u8 *text = gMenuHintText;
    u32 index;
    u32 bankMask;
    const u8 **banks;

    gMenuHintBanks[0] = text;
    index = 0;
    bankMask = 0x3F;
    banks = gMenuHintBanks;
    do
    {
        while (*text != 0xFF)
            text++;
        text++;
        index++;
        if ((index & bankMask) == 0)
            banks[index >> 6] = text;
    } while (*text != 0xFF);
}

/**
 * @brief 内联解压指定队伍位置的头像图块
 *
 * @note FF 空队员跳过；对应 Menu_LoadPartyPortrait 的展开，使用同一 EWRAM 临时区。
 */
static inline void Menu_LoadPartyPortraitInline(u8 partySlot)
{
    u8 member = gPartyMembers[partySlot];

    if (member != 0xFF)
        LZ77UnCompWram((void *)(gMenuSpriteGraphicsSources[member]), (void *)0x02020000);
}

/**
 * @brief 推进商店开闭状态，准备提示及头像资源并切换背景音乐
 *
 * @note 开店保存显示和混合控制，分帧解压五个头像；关店释放菜单角色、清空 1024 个文本半字并恢复场景。
 *       状态 9 等待商店输入处理；每次调用递增文字闪烁计数并更新商店帧。
 * @address 0x0801417C
 */
void Shop_UpdateState(void)
{
    u16 index;
    u8 *context = &gMenuContext;

    switch (*context)
    {
    case 9:
        break;
    case 40:
        gMenuSavedDisplayControl = (*(vu16 *)REG_DISPCNT);
        gMenuSavedBlendControl = (*(vu16 *)REG_BLDCNT);
        (*(vu16 *)REG_BG0HOFS) = 0;
        (*(vu16 *)REG_BG0VOFS) = 0;
        (*(vu16 *)REG_BG0CNT) = 0x1F08;
        (*(vu16 *)REG_DISPCNT) |= 0x100;
        gShopEquipPromptActive = 0;
        Menu_InitEntries(1);
        Sprite_ClearDrawOrder();
        Sound_PlaySfx(4, 0, 0);
        gMenuContext = 1;
        break;
    case 1:
    {
        Sound_FadeOutBgm(4);
        Menu_InitHintBanksInline();
        LZ77UnCompWram((void *)(gMenuSpriteGraphicsSources[11]), (void *)0x02020000);
        LZ77UnCompWram((void *)(gTitleOptionTiles), (void *)0x02020800);
        gMenuContext++;
        break;
    }
    case 8:
        gMenuContext = 30;
        break;
    case 2:
    case 3:
    case 4:
    case 6:
        Menu_LoadPartyPortraitInline(gMenuContext - 2);
        context = &gMenuContext;
    case 7:
        gMenuContext++;
        goto finish;
    case 5:
    {
        Menu_LoadPartyPortraitInline(3);
        Shop_InitSprites();
        Sound_StopBgm();
        gMenuContext++;
        break;
    }
    case 30:
        Sound_PlayBgm(51, 0);
        gMenuContext++;
        break;
    case 31:
        Sound_FadeInBgm(8);
        gMenuContext++;
        break;
    case 32:
        gMenuContext = 33;
        break;
    case 33:
    case 34:
        gMenuContext++;
        break;
    case 35:
        gMenuContext = 9;
        break;
    case 240:
    {
        struct ActorState *actors;

        for (index = 0, actors = gActorStates; index <= 4; index++)
        {
            u32 actorSlot = index + CORE_MENU_ACTOR_FIRST;

            if (actors[actorSlot].spriteSlot != 0)
            {
                Sprite_FreeChain(&gSpriteNodes[actors[actorSlot].spriteSlot]);
                actors[actorSlot].spriteSlot = 0;
            }
        }
        (*(vu16 *)REG_DISPCNT) = gMenuSavedDisplayControl | 0x100;
        (*(vu16 *)REG_BLDCNT) = gMenuSavedBlendControl;
        Sound_FadeOutBgm(4);
        Sound_PlaySfx(5, 0, 0);
    }
    case 241:
    case 242:
    case 243:
    case 244:
    case 246:
    case 247:
    case 248:
        gMenuContext++;
        break;
    case 245:
        Sound_StopBgm();
        gMenuContext++;
        break;
    case 249:
    {
        u16 *dest;

        Sound_PlayBgm(gSceneBgmId, 0);
        Sound_FadeInBgm(8);
        gMenuContext++;
        dest = gScriptTextTilemap;
        for (index = 0; index <= 1023; index++)
            *dest++ = 0;
        break;
    }
    case 250:
        (*(vu16 *)REG_DISPCNT) = gMenuSavedDisplayControl;
        (*(vu16 *)REG_BLDCNT) = gMenuSavedBlendControl;
        gMenuContext = 0;
        gShopActive = 0;
        gSceneState = 1;
        break;
    }
finish:
    gMenuTextBlinkCounter++;
    Shop_UpdateFrame();
}

/**
 * @brief 活动商店更新输入、条目精灵和绘制队列
 *
 * @note 非活动阶段清软件精灵队列。
 * @address 0x08014488
 */
void Shop_UpdateFrame(void)
{
    u16 drawIndex;
    u16 entryIndex;

    if ((u8)(gMenuContext - 9) > 0xE6)
    {
        Sprite_ClearDrawOrder();
        return;
    }
    Shop_UpdateInputAndCursor();
    Menu_UpdateEntrySprites();
    drawIndex = 0;
    while (gSpriteDrawOrder[drawIndex] != 0)
        drawIndex++;
    gSpriteDrawOrder[drawIndex] =
        (struct SpriteNode *)((u32)gSpriteNodes + 112 * sizeof(struct SpriteNode));
    for (entryIndex = 0; entryIndex <= 14; entryIndex++)
    {
        if ((gMenuEntries[entryIndex].flags & 0xC0) == 0x80)
        {
            for (; gSpriteDrawOrder[drawIndex] != 0; drawIndex++)
                ;
            gSpriteDrawOrder[drawIndex] = &gSpriteNodes[gMenuEntries[entryIndex].spriteNodeIndex];
        }
    }
}

/**
 * @brief 重置导航、建立商店标签、光标和队伍头像软件精灵
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0801455C
 */
void Shop_InitSprites(void)
{
    struct SpriteNode *node;
    u16 index;
    u16 attr0;
    u16 attr1;
    u16 attr2;

    Menu_ResetNavigation();
    gMenuCursor.x = 0x60;
    gMenuCursor.y = 0x2C;
    Menu_TransitionToPage(1);

    for (index = 0; index <= 14; index++)
    {
        if (index <= 4 && gPartyMembers[index] != PARTY_NO_MEMBER)
        {
            gMenuEntries[index].x = index * 40 + 72;
            gMenuEntries[index].y = 8;
            gMenuEntries[index].flags = MENU_ENTRY_ACTIVE;
            gMenuEntries[index].tile = index * 48 + 0x200;
            gMenuEntries[index].spriteNodeIndex = index + 113;
        }
        else
        {
            gMenuEntries[index].x = 0;
            gMenuEntries[index].y = 0;
            gMenuEntries[index].flags = 0;
            gMenuEntries[index].spriteNodeIndex = 0;
        }
        gMenuEntries[index].blinkCounter = 0;
        gMenuEntries[index].transitionFrames = 0;
    }

    Menu_CreateLabelEntries(3);
    gMenuEntries[5].flags |= MENU_ENTRY_HIGHLIGHT;

    node = &gSpriteNodes[112];
    attr0 = gMenuCursor.y;
    attr1 = ((gMenuCursor.x - 32) & 0x1FF);
    attr1 += 0x8000;
    attr2 = 0x21C0;
    Sprite_InitNode(node, 1, attr0, attr1, attr2);
    gSpriteDrawOrder[0] = node;

    for (index = 0; index <= 4; index++)
    {
        node++;
        if (gPartyMembers[index] != PARTY_NO_MEMBER)
        {
            Sprite_InitNode(node, 1, 8, attr1 = 0x8028 + index * 40, attr2 = ((index + 3) << 12) + ((0x200 + index * 48) & 0x3FF));
            gSpriteDrawOrder[index + 1] = node;
        }
    }
}

/**
 * @brief 商店光标落位后刷新购买、出售、装备预览和确认界面
 *
 * @note 按当前页面和选择阶段更新布局、金币、列表与提示；不执行交易。
 * @address 0x080146A8
 */
void Shop_OnCursorMoveFinished(void)
{
    gMenuCursor.flags |= 1;
    gMenuCursor.x = gMenuCursor.targetX;
    gMenuCursor.y = gMenuCursor.targetY;

    switch (gMenuPage)
    {
    case 1:
    {
        u32 hint = gMenuPhase + 14;

        if (gMenuPhase == 2)
            hint = 19;
        Menu_ShowHintWithPalette(hint, 11);
        break;
    }
    case 2:
        /* This one-pass block preserves agbcc's allocation in both gold clears. */
        do
        {
            Menu_DrawLayoutInline(gShopBuyTitleLayout);
        } while (0);
        Menu_DrawLayoutInline(gMenuItemHeaderLayout);
        Menu_DrawLayoutInline(gMenuEquipmentStatsLayout);
        Menu_ClearTextRectInline(6, 3, 6, 2);
        Menu_DrawDecimal(MENU_TEXT_ADDR(12, 3), gPartyGold, 11);
        Menu_DrawGlyphInline(MENU_TEXT_ADDR(13, 3), 0xDC, 11);
        Menu_DrawGlyphInline(MENU_TEXT_ADDR(14, 3), 0xDD, 11);
        Menu_DrawGlyphInline(MENU_TEXT_ADDR(15, 3), 0xDE, 11);
        Shop_DrawBuyList();
        if (gMenuPhase <= 3)
        {
            Shop_SetConfirmationLabels(0);
            Menu_ShowHintWithPalette(gShopSelectedItemId + 40, 11);
        }
        else
        {
            Shop_SetConfirmationLabels(1);
            if (gShopEquipPromptActive != 0)
            {
                Menu_ClearTextRectInline(16, 1, 12, 2);
                Menu_ShowHintWithPalette(11, 11);
            }
            else
                Menu_ShowHintWithPalette(19, 11);
        }
        break;
    case 3:
        Menu_DrawLayoutInline(gShopSellTitleLayout);
        Menu_ClearTextRectInline(6, 3, 6, 2);
        Menu_DrawDecimal(MENU_TEXT_ADDR(12, 3), gPartyGold, 11);
        Menu_DrawGlyphInline(MENU_TEXT_ADDR(13, 3), 0xDC, 11);
        Menu_DrawGlyphInline(MENU_TEXT_ADDR(14, 3), 0xDD, 11);
        Menu_DrawGlyphInline(MENU_TEXT_ADDR(15, 3), 0xDE, 11);
        Shop_DrawSellList();
        if (gMenuPhase <= 3)
        {
            Shop_SetConfirmationLabels(2);
            if (gPartyItemCounts[gShopSelectedItemId] != 0)
                Menu_ShowHintWithPalette(gShopSelectedItemId + 40, 11);
            else
                Menu_ShowHintWithPalette(40, 11);
        }
        else
        {
            Shop_SetConfirmationLabels(3);
            Menu_ShowHintWithPalette(19, 11);
        }
        break;
    }
}

/**
 * @brief 处理商店导航、确认交易和购买后装备，并更新移动／闪烁光标
 *
 * @note 每次买卖一个物品；光标八帧移动期间暂停输入，结束时刷新页面。
 * @address 0x08014A68
 */
void Shop_UpdateInputAndCursor(void)
{
    u16 tile;
    u8 changed;

    gMenuCursor.blinkCounter++;
    tile = ((u8)(gMenuCursor.blinkCounter & 8) * 2) | 0x1C0;
    if (gMenuCursor.flags & 1)
        tile += 0x20;
    changed = 0;

    if (gMenuCursor.transitionFrames != 0)
    {
        gMenuCursor.transitionFrames--;
        if (gMenuCursor.transitionFrames == 0)
            Shop_OnCursorMoveFinished();
        else
        {
            u16 deltaX = gMenuCursor.targetX - gMenuCursor.originX;
            u16 deltaY = gMenuCursor.targetY - gMenuCursor.originY;
            u8 elapsed = 8 - gMenuCursor.transitionFrames;

            gMenuCursor.x = gMenuCursor.originX + ((deltaX * elapsed) >> 3);
            gMenuCursor.y = gMenuCursor.originY + ((deltaY * elapsed) >> 3);
        }
    }
    else
    {
        switch (gMenuPage)
        {
        case 1:
            if (gKeysHeld & 0xC0)
            {
                if (gKeysHeld & 0x40)
                {
                    if (gMenuPhase != 0)
                    {
                        gMenuPhase--;
                        changed = 1;
                    }
                }
                else if (gKeysHeld & 0x80)
                {
                    if (gMenuPhase < 2)
                    {
                        gMenuPhase++;
                        changed = 1;
                    }
                }
                if (changed != 0)
                {
                    Sound_PlaySfx(0, 0, 0);
                    Menu_TransitionToPage(0xFF);
                }
            }
            else if (gKeysPressed & 1)
            {
                if (gMenuPhase == 2)
                {
                    gMenuContext = 0xF0;
                    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(0, 0), 30, 20);
                    return;
                }
                else if (gMenuPhase == 0)
                {
                    Menu_TransitionToPage(2);
                    gShopBuyWindowStart = 0;
                    gMenuSavedSelections[0] = 0;
                    gMenuSavedSelections[2] = 0;
                    Menu_MovePartyEntry(0xFF, 1);
                    {
                        u8 position = gMenuSavedSelections[0] - 1;
                        u8 index;
                        struct MenuEntry *entry;

                        if (gMenuContext != 0 && position == 0xFF)
                            position = 5;
                        entry = gMenuEntries;
                        for (index = 0; index <= 14; index++)
                        {
                            if (entry->flags != 0 && index != position)
                                entry->flags |= MENU_ENTRY_HIDDEN;
                            entry++;
                        }
                    }
                }
                else
                {
                    Menu_SelectFirstInventoryItem();
                    Menu_TransitionToPage(3);
                    gShopBuyWindowStart = 0;
                    gMenuSavedSelections[0] = 0;
                    gMenuSavedSelections[3] = 0;
                    Menu_MovePartyEntry(0xFF, 1);
                    {
                        u8 position = gMenuSavedSelections[0] - 1;
                        u8 index;
                        struct MenuEntry *entry;

                        if (gMenuContext != 0 && position == 0xFF)
                            position = 5;
                        entry = gMenuEntries;
                        for (index = 0; index <= 14; index++)
                        {
                            if (entry->flags != 0 && index != position)
                                entry->flags |= MENU_ENTRY_HIDDEN;
                            entry++;
                        }
                    }
                }
                Sound_PlaySfx(1, 0, 0);
                Shop_SetActionLabelsVisible(0);
                return;
            }
            else if (gKeysPressed & 2)
            {
                gMenuContext = 0xF0;
                Menu_ClearTextBufferInline(MENU_TEXT_ADDR(0, 0), 30, 20);
                return;
            }
            Shop_SetActionLabelsVisible(1);
            break;

        case 2:
            Shop_UpdateBuyScrollArrows();
            if (gKeysHeld & 0xF0)
            {
                if (gMenuPhase <= 3)
                {
                    if (gKeysHeld & 0x40)
                    {
                        if (gMenuPhase != 0)
                        {
                            gMenuPhase--;
                            changed = 1;
                        }
                        else if (gShopBuyWindowStart != 0)
                        {
                            gShopBuyWindowStart--;
                            changed = 1;
                        }
                    }
                    else if (gKeysHeld & 0x80)
                    {
                        if (gShopItemCatalogs[gShopId * 8
                            + gMenuSavedSelections[gMenuPage] + gShopBuyWindowStart + 1] != 0xFF)
                        {
                            if (gMenuPhase < 3)
                            {
                                gMenuPhase++;
                                changed = 1;
                            }
                            else if (gShopBuyWindowStart < 4)
                            {
                                gShopBuyWindowStart++;
                                changed = 1;
                            }
                        }
                    }
                    gMenuSavedSelections[gMenuPage] = gMenuPhase;
                }
                else
                {
                    if (gKeysHeld & 0x20)
                    {
                        if (gMenuPhase == 5)
                        {
                            gMenuPhase--;
                            changed = 1;
                        }
                    }
                    else if (gKeysHeld & 0x10)
                    {
                        if (gMenuPhase == 4)
                        {
                            gMenuPhase++;
                            changed = 1;
                        }
                    }
                }
                if (changed != 0)
                {
                    Sound_PlaySfx(0, 0, 0);
                    Menu_TransitionToPage(0xFF);
                }
            }
            else if (gKeysPressed & 0x200)
            {
                if (gShopEquipPromptActive == 0)
                {
                    {
                        u8 mode = 0;
                        u8 position = Menu_GetSelectedPartySlot();

                        if (position == 0xFF)
                        {
                            position = 5;
                            mode = 2;
                        }
                        Menu_SetPartyEntryState(mode, 0, position);
                    }
                    gMenuSavedSelections[0]--;
                    if (gMenuSavedSelections[0] > 5)
                    {
                        gMenuSavedSelections[0] = 5;
                        while (gPartyMembers[gMenuSavedSelections[0] - 1] == 0xFF)
                            gMenuSavedSelections[0]--;
                    }
                    {
                        u8 mode = 1;
                        u8 position = Menu_GetSelectedPartySlot();

                        if (position == 0xFF)
                        {
                            position = 5;
                            mode = 2;
                        }
                        Menu_SetPartyEntryState(mode, 2, position);
                    }
                    Shop_DrawBuyList();
                    Sound_PlaySfx(0, 0, 0);
                }
            }
            else if (gKeysPressed & 0x100)
            {
                if (gShopEquipPromptActive == 0)
                {
                    {
                        u8 mode = 0;
                        u8 position = Menu_GetSelectedPartySlot();

                        if (position == 0xFF)
                        {
                            position = 5;
                            mode = 2;
                        }
                        Menu_SetPartyEntryState(mode, 0, position);
                    }
                    gMenuSavedSelections[0]++;
                    if (gPartyMembers[gMenuSavedSelections[0] - 1] == 0xFF)
                        gMenuSavedSelections[0] = 0;
                    {
                        u8 mode = 1;
                        u8 position = Menu_GetSelectedPartySlot();

                        if (position == 0xFF)
                        {
                            position = 5;
                            mode = 2;
                        }
                        Menu_SetPartyEntryState(mode, 2, position);
                    }
                    Shop_DrawBuyList();
                    Sound_PlaySfx(0, 0, 0);
                }
            }
            else if (gKeysPressed & 2)
            {
                if (gMenuPhase <= 3)
                {
                    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(0, 0), 30, 20);
                    gMenuPhase = 0;
                    Menu_TransitionToPage(1);
                    {
                        u8 mode = 0xFF;
                        u8 position = Menu_GetSelectedPartySlot();

                        if (position == 0xFF)
                        {
                            position = 5;
                            mode = 2;
                        }
                        Menu_SetPartyEntryState(mode, 2, position);
                    }
                    Menu_MovePartyEntry(gMenuSavedSelections[0] - 1, 0);
                    {
                        u8 position = gMenuSavedSelections[0] - 1;
                        u8 index;
                        struct MenuEntry *entry;

                        if (gMenuContext != 0 && position == 0xFF)
                            position = 5;
                        entry = gMenuEntries;
                        for (index = 0; index <= 14; index++)
                        {
                            if (entry->flags != 0 && index != position)
                                entry->flags &= ~MENU_ENTRY_HIDDEN;
                            entry++;
                        }
                    }
                    Sound_PlaySfx(2, 0, 0);
                }
                else if (gShopEquipPromptActive == 0)
                {
                    gMenuPhase = gMenuSavedSelections[gMenuPage];
                    Menu_TransitionToPage(0xFF);
                    Sound_PlaySfx(2, 0, 0);
                }
            }
            else if (gKeysPressed & 1)
            {
                if (gMenuPhase <= 3)
                {
                    if (gShopSelectedItemPrice > gPartyGold)
                    {
                        Menu_ShowHintWithPalette(0xD, 11);
                        Sound_PlaySfx(3, 0, 0);
                        break;
                    }
                    else if (gPartyItemCounts[gShopSelectedItemId] >= 99)
                    {
                        Menu_ShowHintWithPalette(0xC, 11);
                        Sound_PlaySfx(3, 0, 0);
                        break;
                    }
                    else
                    {
                        gMenuSavedSelections[gMenuPage] = gMenuPhase;
                        gMenuPhase = 5;
                        Menu_TransitionToPage(0xFF);
                        gShopEquipPromptActive = 0;
                    }
                }
                else if (gShopEquipPromptActive == 0)
                {
                    if (gMenuPhase == 5)
                        gMenuPhase = gMenuSavedSelections[gMenuPage];
                    else
                    {
                        u8 position;

                        gPartyGold -= gShopSelectedItemPrice;
                        gShopTransactionOccurred = 1;
                        /* Truncate the party index before looking up its entry. */
                        if (gMenuSavedSelections[0] == 0
                            || !(position = gMenuSavedSelections[0] - 1,
                                gMenuEntries[position].flags & MENU_ENTRY_BLINK))
                        {
                            Party_AddItem(gShopSelectedItemId, 1);
                            gMenuPhase = gMenuSavedSelections[gMenuPage];
                        }
                        else
                            gShopEquipPromptActive = 1;
                    }
                    Menu_TransitionToPage(0xFF);
                }
                else
                {
                    Party_AddItem(gShopSelectedItemId, 1);
                    if (gMenuPhase == 4)
                        Menu_EquipItem(gShopPreviewEquipmentSlot, gShopSelectedItemId);
                    gShopEquipPromptActive = 0;
                    gMenuPhase = gMenuSavedSelections[gMenuPage];
                    Menu_TransitionToPage(0xFF);
                }
                Sound_PlaySfx(1, 0, 0);
            }
            break;

        case 3:
            Shop_UpdateSellScrollArrows();
            if (gKeysHeld & 0xF0)
            {
                if (gMenuPhase <= 3)
                {
                    if (gKeysHeld & 0x40)
                    {
                        if (gMenuPhase == 0)
                        {
                            changed = Menu_FindPreviousInventoryItem();
                            if (changed != 0)
                                gMenuInventoryStartItem = changed;
                        }
                        else
                        {
                            gMenuPhase--;
                            changed = 1;
                        }
                    }
                    else if (gKeysHeld & 0x80)
                    {
                        if (gMenuPhase == 3)
                        {
                            changed = Menu_FindInventoryItemAtOffset(4);
                            if (changed != 0)
                                gMenuInventoryStartItem = Menu_FindInventoryItemAtOffset(1);
                        }
                        else
                        {
                            changed = Menu_FindInventoryItemAtOffset(gMenuPhase + 1);
                            if (changed != 0)
                                gMenuPhase++;
                        }
                    }
                    gMenuSavedSelections[gMenuPage] = gMenuPhase;
                }
                else
                {
                    if (gKeysHeld & 0x20)
                    {
                        if (gMenuPhase == 5)
                        {
                            gMenuPhase--;
                            changed = 1;
                        }
                    }
                    else if (gKeysHeld & 0x10)
                    {
                        if (gMenuPhase == 4)
                        {
                            gMenuPhase++;
                            changed = 1;
                        }
                    }
                }
                if (changed != 0)
                {
                    Sound_PlaySfx(0, 0, 0);
                    Menu_TransitionToPage(0xFF);
                }
            }
            else if (gKeysPressed & 2)
            {
                if (gMenuPhase <= 3)
                {
                    Menu_ClearTextBufferInline(MENU_TEXT_ADDR(0, 0), 30, 20);
                    gMenuPhase = 0;
                    Menu_TransitionToPage(1);
                    Menu_MovePartyEntry(gMenuSavedSelections[0] - 1, 0);
                    {
                        u8 position = gMenuSavedSelections[0] - 1;
                        u8 index;
                        struct MenuEntry *entry;

                        if (gMenuContext != 0 && position == 0xFF)
                            position = 5;
                        entry = gMenuEntries;
                        for (index = 0; index <= 14; index++)
                        {
                            if (entry->flags != 0 && index != position)
                                entry->flags &= ~MENU_ENTRY_HIDDEN;
                            entry++;
                        }
                    }
                }
                else
                {
                    gMenuPhase = gMenuSavedSelections[gMenuPage];
                    Menu_TransitionToPage(0xFF);
                }
                Sound_PlaySfx(2, 0, 0);
            }
            else if (gKeysPressed & 1)
            {
                if (gMenuPhase <= 3)
                {
                    if (gPartyItemCounts[gShopSelectedItemId] != 0)
                    {
                        if (gShopSelectedItemPrice == 0)
                        {
                            Menu_ShowHintWithPalette(0x167, 11);
                            Sound_PlaySfx(3, 0, 0);
                            break;
                        }
                        else
                        {
                            gMenuSavedSelections[gMenuPage] = gMenuPhase;
                            gMenuPhase = 5;
                            Menu_TransitionToPage(0xFF);
                        }
                    }
                    else
                    {
                        Menu_ShowHintWithPalette(0x28, 11);
                        Sound_PlaySfx(3, 0, 0);
                        break;
                    }
                }
                else
                {
                    if (gMenuPhase == 4)
                    {
                        Party_RemoveItem(gShopSelectedItemId, 1);
                        gShopTransactionOccurred = 1;
                        Party_AddGold(gShopSelectedItemPrice);
                    }
                    gMenuPhase = gMenuSavedSelections[gMenuPage];
                    Menu_TransitionToPage(0xFF);
                }
                Sound_PlaySfx(1, 0, 0);
            }
            break;
        }
    }
    {
        struct SpriteNode *node = &gSpriteNodes[112];
        u32 attr0 = node->attr0 & 0xFF00;

        attr0 += (u8)gMenuCursor.y;
        node->attr0 = attr0;
        node->attr1 = (node->attr1 & 0xFE00) + ((gMenuCursor.x - 32) & 0x1FF);
        node->attr2 = (node->attr2 & 0xFC00) + tile;
        gSpriteDrawOrder[0] = node;
    }
}

/**
 * @brief 显示或擦除 buy/sell/exit 三个操作标签，并高亮当前选择
 *
 * @note 坐标和字形取自 gShopActionAndConfirmationTexts 的前三项；不可见时按文本长度用调色板 11 画空格，
 *       可见时当前项用 13、其余用 11。
 * @address 0x0801543C
 */
void Shop_SetActionLabelsVisible(u8 visible)
{
    u8 index;
    u8 palette;

    for (index = 0; index <= 2; index++)
    {
        if (index == gMenuPhase)
            palette = 13;
        else
            palette = 11;
        Menu_SetTextVisibleInline(gShopActionAndConfirmationTexts[index], palette, visible);
    }
}

/**
 * @brief 显示或擦除商店的两组确认选项文字
 *
 * @note 两组文字均为 YES/NO；0/1 擦除或显示列表区域确认，2/3 擦除或显示标题区域确认；当前选择决定高亮。
 * @address 0x080154E8
 */
void Shop_SetConfirmationLabels(u8 mode)
{
    u8 group;
    u8 visible;
    u8 index;
    u8 palette;

    switch (mode)
    {
    case 0:
        group = 0;
        visible = 0;
        break;
    case 1:
        group = 0;
        visible = 1;
        break;
    case 2:
        group = 1;
        visible = 0;
        break;
    case 3:
        group = 1;
        visible = 1;
        break;
    }
    for (index = 0; index <= 1; index++)
    {
        if (index == gMenuPhase - 4)
            palette = 13;
        else
            palette = 11;
        if (group == 0)
            Menu_SetTextVisibleInline(gShopActionAndConfirmationTexts[index + 3], palette, visible);
        else
            Menu_SetTextVisibleInline(gShopActionAndConfirmationTexts[index + 5], palette, visible);
    }
}

/**
 * @brief 绘制四行商品、价格、库存数量、角色适用状态及装备属性比较
 *
 * @note 单价单位乘十；标志 0x194 在商店 0x24 将价格设为零。FF 商品行跳过，选择零不预览角色；不适用物品以 FF 交给装备预览。
 * @address 0x08015658
 */
void Shop_DrawBuyList(void)
{
    u8 itemId;
    u8 index;
    u8 entryIndex;
    u8 value;
    u8 freeItems;
    u8 flag;
    struct PartyCharacter *character;

    flag = SystemFlags_GetMask(0x194);
    freeItems = 0;
    if (flag != 0 && gShopId == 0x24)
        freeItems = 1;
    /* The party selection is one-based; zero becomes the FF sentinel. */
    index = gMenuSavedSelections[0] - 1;
    Menu_ClearTextRectInline(5, 6, 3, 10);
    Menu_ClearTextRectInline(13, 6, 3, 4);
    Menu_ClearTextRectInline(18, 7, 8, 8);
    Menu_ClearTextRectInline(27, 7, 2, 8);

    itemId = gShopItemCatalogs[gShopId * 8
        + gMenuSavedSelections[gMenuPage] + gShopBuyWindowStart];
    gShopSelectedItemId = itemId;
    Menu_ClearTextRectInline(17, 4, 6, 2);
    if (freeItems == 0)
        gShopSelectedItemPrice = Party_GetItemBuyPriceUnits(gShopSelectedItemId) * 10;
    else
        gShopSelectedItemPrice = 0;
    Menu_DrawDecimal(MENU_TEXT_ADDR(23, 4), gShopSelectedItemPrice, 13);
    Menu_DrawGlyphInline(MENU_TEXT_ADDR(24, 4), 0xDC, 13);
    Menu_DrawGlyphInline(MENU_TEXT_ADDR(25, 4), 0xDD, 13);
    Menu_DrawGlyphInline(MENU_TEXT_ADDR(26, 4), 0xDE, 13);

    for (entryIndex = 0; entryIndex <= 3; entryIndex++)
    {
        value = gShopItemCatalogs[gShopId * 8 + entryIndex + gShopBuyWindowStart];

        if (value <= 0xFE)
        {
            u8 selection = gMenuSavedSelections[gMenuPage];
            u8 palette = 11;

            if (entryIndex == selection)
                palette = 13;
            Menu_DrawItemNameInline(value, 18, entryIndex * 2 + 7, palette);
            Menu_DrawDecimal(MENU_TEXT_ADDR(28, entryIndex * 2 + 7),
                gPartyItemCounts[value], 12);
        }
    }
    if (index != 0xFF)
    {
        /* After the list, reuse the entry index for the character record. */
        entryIndex = gPartyMembers[index];
        if (entryIndex != 0)
            entryIndex--;
        if (entryIndex <= 8)
        {
            u8 mask = 1 << entryIndex;
            const struct PartyItemInfo *item = &gPartyItemTable[itemId];

            if ((item->characterMask & mask) != 0)
            {
                u8 mode = 0xFF;
                u8 state = 1;
                u8 position = Menu_GetSelectedPartySlot();

                if (position == 0xFF)
                {
                    position = 5;
                    mode = 2;
                    state = 2;
                }
                Menu_SetPartyEntryState(mode, state, position);
            }
            else
            {
                u8 mode = 0xFF;
                u8 position = Menu_GetSelectedPartySlot();

                if (position == 0xFF)
                {
                    position = 5;
                    mode = 2;
                }
                Menu_SetPartyEntryState(mode, 2, position);
                itemId = 0xFF;
            }
        }
        else
        {
            u8 mode = 0xFF;
            u8 position = Menu_GetSelectedPartySlot();

            if (position == 0xFF)
            {
                position = 5;
                mode = 2;
            }
            Menu_SetPartyEntryState(mode, 2, position);
            itemId = 0xFF;
        }
        character = &gPartyCharacters[entryIndex];
        for (index = 0; index <= 6; index++)
            gMenuStatPreviewPalettes[index] = 11;
        /* Equipment type 4 uses slot 5; other non-equipment types use 6. */
        value = Party_GetItemEquipmentType(itemId);
        if (value == 4)
            value = 5;
        else if (value > 4)
            value = 6;
        gShopPreviewEquipmentSlot = value;
        Menu_PreviewEquipment(itemId, value, entryIndex);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 6),
            character->baseAtc + gPartyEquipmentAtcBonus, gMenuStatPreviewPalettes[0]);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 8),
            character->baseDef + gPartyEquipmentDefBonus, gMenuStatPreviewPalettes[1]);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 10),
            character->baseAgl + gPartyEquipmentAglBonus, gMenuStatPreviewPalettes[2]);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 12),
            character->baseMen + gPartyEquipmentMenBonus, gMenuStatPreviewPalettes[3]);
        Menu_DrawDecimal(MENU_TEXT_ADDR(7, 14),
            character->baseRes + gPartyEquipmentResBonus, gMenuStatPreviewPalettes[4]);
        Menu_DrawDecimal(MENU_TEXT_ADDR(14, 6),
            character->baseLuc + gPartyEquipmentLucBonus, gMenuStatPreviewPalettes[5]);
        Menu_DrawDecimal(MENU_TEXT_ADDR(14, 8),
            character->baseNoa + gPartyEquipmentNoaBonus, gMenuStatPreviewPalettes[6]);
    }
}

/**
 * @brief 根据商品窗口起点和商品表绘制或擦除上下闪烁箭头
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08015AF0
 */
void Shop_UpdateBuyScrollArrows(void)
{
    s32 next;
    s32 shopOffset;
    const u8 *catalogs;

    if (gShopBuyWindowStart != 0)
    {
        u16 tile = ((gMenuTextBlinkCounter >> 3) & 1) | 0x826;
        u16 *dest = MENU_TEXT_ADDR(21, 6);

        *dest = tile + 0xB240;
    }
    else
        Menu_SetTextTileInline(21, 6, 0x3F, 0xB240);
    catalogs = gShopItemCatalogs;
    shopOffset = gShopId * 8;
    next = gShopBuyWindowStart + 4;
    if (catalogs[shopOffset + next] == 0xFF || gShopBuyWindowStart > 3)
        Menu_SetTextTileInline(21, 15, 0x3F, 0xB240);
    else
        Menu_SetTextTileInline(21, 15, ((gMenuTextBlinkCounter >> 3) & 1) + 0x26, 0xB240);
}

/**
 * @brief 更新商店出售页四行物品列表的上下滚动箭头
 *
 * @note 由商店输入控制器调用；列表内容来自玩家库存。前项决定上箭头，offset=4 的后继决定下箭头，文字坐标为 (9,6)/(9,15)；共用库存查找助手和闪烁计数。
 * @address 0x08015B90
 */
void Shop_UpdateSellScrollArrows(void)
{
    if (Menu_FindPreviousInventoryItem() != 0)
    {
        u16 tile = ((gMenuTextBlinkCounter >> 3) & 1) | 0x826;
        u16 *dest = MENU_TEXT_ADDR(9, 6);

        *dest = tile + 0xB240;
    }
    else
        Menu_SetTextTileInline(9, 6, 0x3F, 0xB240);
    if (Menu_FindInventoryItemAtOffset(4) != 0)
        Menu_SetTextTileInline(9, 15, ((gMenuTextBlinkCounter >> 3) & 1) + 0x26, 0xB240);
    else
        Menu_SetTextTileInline(9, 15, 0x3F, 0xB240);
}

/**
 * @brief 绘制商店出售页的四行玩家库存、持有数量及卖价
 *
 * @note 卖价单位乘十后显示；零卖价绘制不可出售提示。数量来自玩家库存，不是本次交易数量；共用库存滚动起点。
 * @address 0x08015C18
 */
void Shop_DrawSellList(void)
{
    u8 itemId;
    u8 entryIndex;
    u32 quantity;
    u32 price;
    u8 palette;

    Menu_ClearTextRectInline(6, 7, 22, 8);

    itemId = gMenuInventoryStartItem;
    entryIndex = 0;
    do
    {
        quantity = gPartyItemCounts[itemId];
        if (quantity != 0)
        {
            price = Party_GetItemSellPriceUnits(itemId) * 10;
            if (entryIndex == gMenuSavedSelections[gMenuPage])
            {
                palette = 13;
                gShopSelectedItemId = itemId;
                gShopSelectedItemPrice = price;
            }
            else
            {
                palette = 11;
            }

            if (price == 0)
            {
                palette = 12;
                Menu_DrawTextAt(21, entryIndex * 2 + 7, 12, gShopCannotSellText);
            }
            else
            {
                s32 y = (entryIndex * 2 + 7);

                Menu_DrawDecimal(MENU_TEXT_ADDR(24, y)  , price, palette);
                Menu_DrawGlyphInline(MENU_TEXT_ADDR(25, y) , 0xDC, palette);
                Menu_DrawGlyphInline(MENU_TEXT_ADDR(26, y) , 0xDD, palette);
                Menu_DrawGlyphInline(MENU_TEXT_ADDR(27, y) , 0xDE, palette);
            }

            Menu_DrawItemNameInline(itemId, 6, entryIndex * 2 + 7, palette);
            Menu_DrawDecimal(MENU_TEXT_ADDR(15, entryIndex * 2 + 7), gPartyItemCounts[itemId], 12);
            entryIndex++;
        }
        else if (entryIndex == gMenuSavedSelections[gMenuPage])
        {
            gShopSelectedItemId = itemId;
            gShopSelectedItemPrice = quantity;
        }
        itemId++;
        if (itemId > 0xFE)
            return;
        if (entryIndex > 3)
            return;
    } while (1);
}

/**
 * @brief 在指定坐标直接绘制 FF 结尾双行字形
 *
 * @note FE 是固定特殊字形，不读取扩展字节。
 * @address 0x08015E1C
 */
void Menu_DrawTextAt(u8 x, u8 y, u8 palette, const u8 *text)
{
    u16 *dest = MENU_TEXT_ADDR(x, y);

    while (*text != 0xFF)
    {
        Menu_DrawGlyphInline(dest, *text, palette);
        dest++;
        text++;
    }
}

/**
 * @brief 把 I/O 状态设为读取并从第零个 0x800 字节块开始
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08015E88
 */
void Save_RequestRead(void)
{
    gSaveIoState = 1;
    gSaveIoBlockIndex = 0;
}

/**
 * @brief 打包奖励槽，启动全部十六个 SRAM 块写入并显示保存提示
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08015EA0
 */
void Save_RequestWriteAll(void)
{
    Save_PackBonusSlot();
    gSaveIoState = 3;
    gSaveIoBlockIndex = 0;
    gMenuSaveRequestKind = 1;
    Menu_ShowHintWithPalette(0x18, 0xB);
}

/**
 * @brief 只检查十二字节槽签名，0 有效、1 不匹配、FF 槽编号越界
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08015ED0
 */
u8 Save_CheckSlotSignature(u8 slot)
{
    const u8 *slotData;
    u8 index;

    if (slot > 3)
        return 0xFF;

    slotData = SAVE_SLOT_BUFFER + slot * SAVE_SLOT_SIZE;
    for (index = 0; index <= 0xB; index++)
    {
        if (*slotData != gSaveSlotSignature[index])
            return 1;
        slotData++;
    }

    return 0;
}

/**
 * @brief 重读并绘制三个普通存档槽的摘要
 *
 * @note 仅绘制槽 0..2；当前选中槽使用 palette 13，其他槽使用 11。
 * @address 0x08015F14
 */
void Menu_DrawSaveSlots(void)
{
    u8 slot;
    u8 palette;

    for (slot = 0; slot <= 2; slot++)
    {
        u8 selectedSlot;

        Save_ReadSlotSummary(slot);
        selectedSlot = gMenuSaveSlot;
        palette = 11;
        if (selectedSlot == slot)
            palette = 13;
        Save_DrawSlotSummary(slot, 8, slot * 2 + 5, palette);
    }
}

/**
 * @brief 按卡片编号的奇偶，从九十字节的高／低半字节返回持有数量
 *
 * @note 返回 0..15 的完整 u32；菜单调用显式截为 u8，脚本直接判零，均保留参考指令。
 * @address 0x08015F50
 */
u32 Collection_GetCardCount(u8 cardId)
{
    u8 count;
    u8 value = gCollectionPackedCardCounts[cardId >> 1];

    if ((cardId & 1) != 0)
        count = value >> 4;
    else
        count = value & 15;
    return count;
}

/**
 * @brief 设置八字节收集事件位图中的指定位
 *
 * @note 剧情脚本使用同一入口。
 * @address 0x08015F74
 */
void Collection_SetEventFlag(u8 flagId)
{
    gCollectionEventFlags[flagId >> 3] |= 1 << (flagId & 7);
}

/**
 * @brief 读取收集事件位，返回 0 或 1
 *
 * @note 画廊用映射表筛选已解锁图片。
 * @address 0x08015F94
 */
u8 Collection_GetEventFlag(u8 flagId)
{
    return (gCollectionEventFlags[flagId >> 3] >> (flagId & 7)) & 1;
}

/**
 * @brief 保存商店编号，进入上下文 40／场景状态 13，清本次交易标记及文本背景
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08015FB4
 */
void Shop_Open(u8 shopId)
{
    gShopId = shopId;
    gMenuContext = 40;
    gShopTransactionOccurred = 0;
    gShopActive = 1;
    gSceneState = 13;
    Menu_ClearTextRectInline(0, 0, 30, 20);
}

/**
 * @brief 按队员编号解压头像到 EWRAM 临时区
 *
 * @note partySlot 是队伍位置；FF 空队员不加载；资源使用原 ROM 指针表和 BIOS LZ77 WRAM 包装器。
 * @address 0x08016038
 */
void Menu_LoadPartyPortrait(u8 partySlot)
{
    u8 index;

    index = gPartyMembers[partySlot];
    if (index != 0xFF)
    {
        LZ77UnCompWram((void *)(gMenuSpriteGraphicsSources[index]), (void *)0x02020000);
    }
}

/**
 * @brief 把临时头像图块和对应调色板上传至该队伍位置的 OBJ VRAM／palette
 *
 * @note FF 空队员不上传；图块复制 0x6C0 字节，角色调色板每项 32 字节；两次 DMA 均保留硬件控制读回。
 * @address 0x08016068
 */
void Menu_UploadPartyPortrait(u8 partySlot)
{
    u8 index;

    index = gPartyMembers[partySlot];
    if (index != 0xFF)
    {
        DmaCopy(3, (void *)0x02020000, (partySlot * 0x600) + 0x06014000, 0x6C0, 32);
        DmaCopy(3, gMenuPartyPortraitPalettes[index], (partySlot << 5) + 0x05000260, 0x20, 16);
    }
}

/**
 * @brief 解压公共光标图块和菜单标签图块到两个临时图形区
 *
 * @note 公共图块取指针表第 11 项解压至 02020000，标签图块解压至 02020800。
 * @address 0x080160CC
 */
void Menu_LoadSharedSpriteGraphics(void)
{
    LZ77UnCompWram((void *)(gMenuSpriteGraphicsSources[11]), (void *)0x02020000);
    LZ77UnCompWram((void*)0x080A0B58, (void*)0x02020800);
}

/**
 * @brief 通过 DMA3 上传公共光标、标签图块及其调色板
 *
 * @note 五次 DMA 分别上传公共图块、公共 OBJ 调色板、标签图块、标签 OBJ 调色板和菜单 BG 调色板，保留硬件控制读回。
 * @address 0x080160F4
 */
void Menu_UploadSharedSpriteGraphics(void)
{


    DmaSet(3, 0x02020000, 0x06013800, 0x84000200);
    DmaCopy(3, 0x0809E644, 0x05000240, 0x20, 16);
    DmaSet(3, 0x02020800, 0x06017000, 0x84000400);
    DmaCopy(3, 0x080A12D0, 0x05000340, 0x40, 16);
    DmaCopy(3, 0x0808B7D4, 0x050001C0, 0x40, 16);
}

/**
 * @brief 按截断后的帧编号计算居中矩形，用 B001 填充展开或关闭中的菜单窗口
 *
 * @note 帧为零时不写入；半高与半宽先截断为十六位，再分别限制为 10 和 15。
 * @address 0x08016178
 */
void Menu_DrawWindowTransition(u16 frame)
{
    u16 halfHeight;
    u16 halfWidth;
    u16 row;
    u16 column;
    u16 *dest;
    u16 *rowStart;

    if (frame != 0)
    {
        halfHeight = (frame - 1) * (u32)frame + 1;
        if (halfHeight > 10)
            halfHeight = 10;
        halfWidth = frame * 8;
        if (halfWidth > 15)
            halfWidth = 15;

        dest = MENU_TEXT_ADDR(15 - halfWidth, 10 - halfHeight);
        halfWidth *= 2;
        halfHeight *= 2;
        for (row = 0; row < halfHeight; row++)
        {
            rowStart = dest;
            for (column = 0; column < halfWidth; column++)
                *dest++ = 0xB001;
            dest = rowStart + 32;
        }
    }
}

/**
 * @brief 在指定文本坐标绘制角色的四个姓名字形
 *
 * @note characterId 直接索引 ROM 姓名表；文字使用 palette 11；文本坐标以 tile 为单位。
 * @address 0x080161F4
 */
void Menu_DrawCharacterName(u8 characterId, u8 x, u8 y)
{
    u16 *dest;
    u16 index;

    if (characterId != 0)
        characterId--;
    characterId *= sizeof(gMenuCharacterNameTiles[0]);
    dest = MENU_TEXT_ADDR(x, y);
    for (index = 0; index <= 3; index++)
        *dest++ = ((const u8 *)gMenuCharacterNameTiles)[characterId + index] + 0xB240;
}

/**
 * @brief 使用默认调色板绘制三位右对齐数字
 *
 * @note 转交 Menu_DrawNumber3，paletteBits 固定为 B000；dest 指向个位。
 * @address 0x0801624C
 */
void Menu_DrawDefaultNumber3(s16 value, u16 *dest)
{
    Menu_DrawNumber3(value, dest, 0xB000);
}

/**
 * @brief 绘制角色等级标签和显示等级
 *
 * @note 内部等级加一后显示；角色编号 0 和 1 都访问第一条角色记录。
 * @address 0x08016260
 */
void Menu_DrawCharacterLevel(u8 characterId, u8 x, u8 y)
{
    u16 *dest;

    if (characterId != 0)
        characterId--;
    dest = gScriptTextTilemap + x + y * 32;
    *dest = 0xB257;
    dest += 3;
    Menu_DrawDefaultNumber3(gPartyCharacters[characterId].level + 1, dest);
}

/**
 * @brief 绘制角色当前 HP，并区分满 HP 的调色板
 *
 * @note 写 HP 标签和三位数；当前 HP 等于最大 HP 时用 F000，否则用 B000。
 * @address 0x080162A8
 */
void Menu_DrawCharacterHp(u8 characterId, u8 x, u8 y)
{
    u16 *dest;
    struct PartyCharacter *character;
    u16 paletteBits;

    if (characterId != 0)
        characterId--;
    dest = MENU_TEXT_ADDR(x, y);
    *dest = 0xB258;
    dest += 3;
    {
        struct PartyCharacter *records = gPartyCharacters;

        character = &records[characterId];
    }
    {
        u16 current = character->hp;

        paletteBits = 0xB000;
        if (current == character->maxHp)
            paletteBits = 0xF000;
        Menu_DrawNumber3((s16)character->hp, dest, paletteBits);
    }
}

/**
 * @brief 绘制角色当前 MP，并区分满 MP 的调色板
 *
 * @note 写 MP 标签和三位数；当前 MP 等于最大 MP 时用 F000，否则用 B000。
 * @address 0x08016308
 */
void Menu_DrawCharacterMp(u8 characterId, u8 x, u8 y)
{
    u16 *dest;
    u16 paletteBits;

    if (characterId != 0)
        characterId--;
    dest = MENU_TEXT_ADDR(x, y);
    *dest = 0xB259;
    dest += 3;

    paletteBits = gPartyCharacters[characterId].mp == gPartyCharacters[characterId].maxMp ? 0xF000 : 0xB000;
    
    Menu_DrawNumber3((s16)gPartyCharacters[characterId].mp, dest, paletteBits);
    
}

/**
 * @brief 将一个普通、扩展或空字形写成上下两行 tile
 *
 * @note 下行距上行三十二个半字；零字形清空两格；低字节 FE 的高字节选择扩展字形。
 * @address 0x08016368
 */
void Menu_DrawGlyph(u16 *dest, u16 glyph, u8 palette)
{
    u16 paletteBits;
    u16 tile;

    if (glyph != 0)
    {
        if ((glyph & 0xFF) == 0xFE)
        {
            paletteBits = palette << 12;
            tile = ((glyph & 0xFF00) >> 7) + 0x280;
            *dest = paletteBits + tile;
            dest += 32;
            tile++;
            *dest = paletteBits | tile;
        }
        else
        {
            paletteBits = palette << 12;
            tile = glyph * 2;
            *dest = paletteBits + tile;
            dest += 32;
            tile |= 1;
            *dest = paletteBits + tile;
        }
    }
    else
    {
        paletteBits = palette << 12;
        *dest = paletteBits + 1;
        dest += 32;
        *dest = paletteBits + 1;
    }
}

/**
 * @brief 按坐标和调色板记录绘制一组菜单文字
 *
 * @note 记录格式为 x,y,palette,text...FF，整个布局以 x=FF 结束；FE 后读取扩展字节。
 * @address 0x080163CC
 */
void Menu_DrawLayout(const u8 *layout)
{
    Menu_DrawLayoutInline(layout);
}

/**
 * @brief 通过连续减法提取一位十进制数并保留余数
 *
 * @note divisor 为正；返回减法次数，value 原位保留余数；返回计数按八位截断。
 * @address 0x08016424
 */
u8 Menu_ExtractDecimalDigit(s32 *value, s32 divisor)
{
    u8 digit = 0;

    goto subtract;
incrementDigit:
    digit++;
subtract:
    *value -= divisor;
    if (*value >= 0)
        goto incrementDigit;
    *value += divisor;
    return digit;
}

/**
 * @brief 绘制场景名称并追加菜单右括号
 *
 * @note 返回位置由 Menu_DrawSceneName 得到；仅追加右括号 C9，括号固定使用 palette 11。
 * @address 0x08016444
 */
void Menu_DrawSceneNameWithClosingBracket(u16 *dest, u16 sceneId, u8 palette)
{
    dest = Menu_DrawSceneName(dest, sceneId, palette);
    Menu_DrawGlyph(dest, 0xC9, 11);
}

/**
 * @brief 查找并绘制场景名称，返回文字结束位置
 *
 * @note sceneId 按连续 FF 结尾名称编号；FE 后读取扩展字节；返回下一可写半字地址。
 * @address 0x08016460
 */
u16 *Menu_DrawSceneName(u16 *dest, u16 sceneId, u8 palette)
{
    const u8 *text = gMenuSceneNames;
    u16 index = 0;

    while (index != sceneId)
    {
        if (*text++ == 0xFF)
            index++;
    }
    while (*text != 0xFF)
    {
        if (*text == 0xFE)
        {
            text++;
            Menu_DrawGlyph(dest++, (*text << 8) | 0xFE, palette);
        }
        else
            Menu_DrawGlyph(dest++, *text, palette);
        text++;
    }
    return dest;
}

/**
 * @brief 建立菜单提示文本的分组起始指针
 *
 * @note 每六十四条 FF 结尾提示保存一个 bank 指针；提示绘制前需要完成初始化。
 * @address 0x080164C0
 */
void Menu_InitHintBanks(void)
{
    const u8 *text = gMenuHintText;
    u32 index;
    const u8 **banks;

    gMenuHintBanks[0] = text;
    index = 0;
    banks = gMenuHintBanks;
    do
    {
        while (*text != 0xFF)
            text++;
        text++;
        index++;
        if ((index & 0x3F) == 0)
            banks[index >> 6] = text;
    } while (*text != 0xFF);
}

/**
 * @brief 使用默认调色板显示指定编号的提示
 *
 * @note 转交 Menu_ShowHintWithPalette，文字 palette 固定为 11。
 * @address 0x080164F8
 */
void Menu_ShowHint(u16 hintId)
{
    Menu_ShowHintWithPalette(hintId, 11);
}

/**
 * @brief 按提示编号和指定调色板绘制菜单提示
 *
 * @note 高位选择每组六十四条的 bank，低六位在组内扫描；bank 由 Menu_InitHintBanks 建立。
 * @address 0x08016508
 */
void Menu_ShowHintWithPalette(u16 hintId, u8 palette)
{
    const u8 *text = gMenuHintBanks[hintId >> 6];
    u16 index;

    hintId &= 0x3F;
    index = 0;
    while (index != hintId)
    {
        if (*text++ == 0xFF)
            index++;
    }
    Menu_DrawHintText(text, palette);
}

/**
 * @brief 绘制或擦除一条包含文本坐标的菜单文字记录
 *
 * @note 记录以 x,y 开头，文字以 FF 结束；visible=0 用 palette 11 清空。
 *       s32 保留原 ABI 的 r0；函数故意不返回值，调用者必须忽略结果。
 * @address 0x0801654C
 */
s32 Menu_SetTextVisible(const u8 *text, u8 palette, u8 visible)
{
    u8 length;
    u8 x = *text++;
    u8 y = *text++;
    u16 *dest = MENU_TEXT_ADDR(x, y);

    if (visible == 0)
    {
        length = 0;
        while (*text != 0xFF)
        {
            text++;
            length++;
        }
        while (length != 0)
        {
            Menu_DrawGlyph(dest++, 0, 11);
            length--;
        }
    }
    else
    {
        while (*text != 0xFF)
            Menu_DrawGlyph(dest++, *text++, palette);
    }
}

/**
 * @brief 把保存的角色选择转换成队伍槽索引
 *
 * @note 返回保存选择减一并按八位截断；选择零返回 FF，表示尚未选择队员。
 * @address 0x080165B8
 */
u8 Menu_GetSelectedPartySlot(void)
{
    return (u8)(gMenuSavedSelections[0] - 1);
}

/**
 * @brief 以 B001 清指定矩形，行跨度保持三十二个半字
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x080165C8
 */
void Menu_ClearTextRect(u8 x, u8 y, u8 width, u8 height)
{
    u16 *ptr = MENU_TEXT_ADDR(x, y);
    u16 row;
    u16 column;

    for (row = 0; row < height; row++)
    {
        u16 *start = ptr;

        for (column = 0; column < width; column++)
            *ptr++ = 0xB001;
        ptr = start + 32;
    }
}

/**
 * @brief 显示或隐藏指定位置之外的活动条目
 *
 * @note 商店 FF 例外保留第一标签。
 * @address 0x08016628
 */
void Menu_SetOtherEntriesVisible(u8 position, u8 mode)
{
    u8 index;
    struct MenuEntry *entry;

    if (gMenuContext != 0 && position == 0xFF)
        position = 5;
    entry = gMenuEntries;
    for (index = 0; index <= 14; index++)
    {
        if (entry->flags != 0 && index != position)
        {
            if (mode != 0)
                entry->flags &= 0xBF;
            else
                entry->flags |= 0x40;
        }
        entry++;
    }
}

/**
 * @brief 仅隐藏第 5–14 条活动文字标签，保留前五个队伍条目
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x0801667C
 */
void Menu_HideLabelEntries(void)
{
    struct MenuEntry *entry = gMenuEntries + 5;
    u8 index;

    for (index = 5; index <= 14; index++)
    {
        if (entry->flags != 0)
            entry->flags |= 0x40;
        entry++;
    }
}

/**
 * @brief 在指定坐标绘制物品名称
 *
 * @note 编号零不绘制；物品名称占八字节、以零结束；palette 为调色板编号。
 * @address 0x080166A4
 */
void Menu_DrawItemName(u8 itemId, u8 x, u8 y, u8 palette)
{
    Menu_DrawItemNameInline(itemId, x, y, palette);
}

/**
 * @brief 在指定坐标绘制技能名称
 *
 * @note 技能编号从一开始，FF 不绘制；名称最多八字节、以零结束。
 * @address 0x080166FC
 */
void Menu_DrawSkillName(u8 skillId, u8 x, u8 y, u8 palette)
{
    Menu_DrawSkillNameInline(skillId, x, y, palette);
}

/**
 * @brief 按方向和文字闪烁位绘制单格滚动箭头
 *
 * @note mode 0/1/2/3 为上/下/左/右；计数器 bit 3 选择两帧，其余模式写 B27F。
 * @address 0x08016758
 */
void Menu_DrawScrollArrow(u8 x, u8 y, u8 mode)
{
    u16 tile;
    u16 *dest;
    u32 frame = (gMenuTextBlinkCounter >> 3) & 1;

    switch (mode)
    {
    case 0: tile = 0x826 | frame; break;
    case 1: tile = 0x26 + frame; break;
    case 2:
        tile = 0x428 | frame;
        break;
    case 3:
        tile = 0x28 + frame;
        break;
    default:
        tile = 0x3F;
        break;
    }
    // dest = MENU_TEXT_ADDR(x, y);
    // *dest = tile + 0xb240;
    // SetTile(x, y, tile, 0xB);
    Menu_SetTextTileInline(x, y, tile, 0xB240);
}

/**
 * @brief 找到当前选中的队伍位置后设置条目状态
 *
 * @note FF 未选择时跳过。
 * @address 0x080167D4
 */
void Menu_SetSelectedPartyEntryState(u8 mode, u8 state)
{
    u8 slot = Menu_GetSelectedPartySlot();

    if (slot != 0xFF)
        Menu_SetPartyEntryState(mode, state, slot);
}

/**
 * @brief 由队形位置中的角色编号查队伍位置
 *
 * @note 未在前五槽找到时返回 5。
 * @address 0x080167F8
 */
u8 Menu_FindPartySlotForFormationSlot(u8 position)
{
    u8 characterId = gPartyCharacterSlots[position];
    u8 index = 0;

    if (gPartyMembers[index] != characterId)
    {
        do
        {
            index++;
            if (index > 4)
                break;
        } while (gPartyMembers[index] != characterId);
    }

    return index;
}

/**
 * @brief 从当前装备页面选择提取候选并计算预览
 *
 * @note 候选行为 phase-6；装备槽取当前页保存选择，角色取保存的队伍选择。
 * @address 0x0801682C
 */
void Menu_PreviewSelectedEquipment(void)
{
    u8 index = gPartyMembers[(u8)(gMenuSavedSelections[0] - 1)];

    if (index != 0)
        index--;
    Menu_PreviewEquipment(gMenuEquipmentCandidates[gMenuPhase - 6],
        gMenuSavedSelections[gMenuPage], index);
}

/**
 * @brief 从装备页面保存的槽和当前候选行取物品，转交 Menu_EquipItem 并返回成功标志
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08016878
 */
s32 Menu_EquipSelectedItem(void)
{
    return Menu_EquipItem(gMenuSavedSelections[gMenuPage],
        gMenuEquipmentCandidates[gMenuPhase - 6]);
}

/**
 * @brief 把当前战术编辑队员的行动和编号载入编辑状态
 *
 * @note 读取角色记录的 +34/+35；队伍位置由战术编辑状态指定。
 * @address 0x080168A8
 */
void Menu_LoadTacticsForEditing(void)
{
    u8 index = gPartyMembers[gMenuTacticsPartySlot];

    if (index != 0)
        index--;
    gMenuTacticsAction = gPartyCharacters[index].tacticsAction;
    gMenuTacticsActionId = gPartyCharacters[index].tacticsActionId;
}

/**
 * @brief 将战术编辑中的行动和编号写回所选队员
 *
 * @note 写角色记录的 +34/+35；不会更改其他角色的行动设置。
 * @address 0x080168EC
 */
void Menu_CommitTactics(void)
{
    u8 index = gPartyMembers[gMenuTacticsPartySlot];

    if (index != 0)
        index--;
    gPartyCharacters[index].tacticsAction = gMenuTacticsAction;
    gPartyCharacters[index].tacticsActionId = gMenuTacticsActionId;
}

/**
 * @brief 从编辑队员的技能数组读取滚动位置加偏移
 *
 * @note 大于 7 或逃离技能 26 返回 FF。
 * @address 0x08016930
 */
u8 Menu_GetTacticsSkillAtOffset(u8 offset)
{
    s32 target = offset + gMenuTacticsScroll;
    u8 index;
    u8 skill;

    if (target > 7)
        return 0xFF;
    index = gPartyMembers[gMenuTacticsPartySlot];
    if (index != 0)
        index--;
    skill = gPartyCharacters[index].skills[target];
    if (skill == 0x26)
        return 0xFF;
    return skill;
}

/**
 * @brief 返回第一个有库存的白名单索引加一
 *
 * @note 0 表示没有物品。
 * @address 0x08016978
 */
u8 Menu_GetFirstTacticsItemSelection(void)
{
    u8 index;

    for (index = 0; index <= 15; index++)
    {
        if (gPartyItemCounts[gTacticsItemIds[index]] != 0)
            return index + 1;
    }
    return 0;
}

/**
 * @brief 从当前白名单滚动位置之前寻找有库存的索引
 *
 * @note 未找到返回 FF。
 * @address 0x080169AC
 */
u8 Menu_FindPreviousTacticsItemIndex(void)
{
    u8 index = gMenuTacticsScroll - 1;

    while (index != 0xFF)
    {
        if (gPartyItemCounts[gTacticsItemIds[index]] != 0)
            return index;
        index--;
    }
    return 0xFF;
}

/**
 * @brief 将有效且有库存的白名单索引转换为物品编号
 *
 * @note 其他情况返回 FF。
 * @address 0x080169EC
 */
u8 Menu_GetTacticsItemAtIndex(u8 index)
{
    u8 itemId;

    if (index > 15)
        return 0xFF;
    itemId = gTacticsItemIds[index];
    if (gPartyItemCounts[itemId] == 0)
        return 0xFF;
    return itemId;
}

/**
 * @brief 按奖励字段表从第四槽恢复额外标志、卡片数量和收集事件位
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08016A14
 */
void Save_UnpackBonusSlot(void)
{
    u8 *buffer = SAVE_SLOT_BUFFER + 3 * SAVE_SLOT_SIZE;
    u16 offset = 12;
    u16 index = 0;
    u16 count = gSaveBonusFieldSizes[0];

    while (count != 0)
    {
        u8 *dest = gSaveBonusFieldPointers[index];
        while (count != 0)
        {
            *dest = buffer[offset];
            offset++;
            dest++;
            count--;
        }
        index++;
        count = gSaveBonusFieldSizes[index];
    }
}

/**
 * @brief 寻找编号 1–FD 中首个有库存物品，保存为库存滚动起点
 *
 * @note 没有则为 0。
 * @address 0x08016A6C
 */
void Menu_SelectFirstInventoryItem(void)
{
    u8 itemId;

    for (itemId = 1; itemId <= 0xFD; itemId++)
    {
        if (gPartyItemCounts[itemId] != 0)
        {
            gMenuInventoryStartItem = itemId;
            return;
        }
    }
    gMenuInventoryStartItem = 0;
}

/**
 * @brief 从库存起点之前寻找物品编号，未找到返回 0
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08016AA0
 */
u8 Menu_FindPreviousInventoryItem(void)
{
    u8 itemId = gMenuInventoryStartItem;

    if (itemId == 1)
        return 0;

    while (itemId != 0)
    {
        itemId--;
        if (gPartyItemCounts[itemId] != 0)
            return itemId;
    }

    return 0;
}

/**
 * @brief 从当前库存起点数过 offset 个有库存物品，再返回下一项
 *
 * @note 无项为 0。
 * @address 0x08016AD4
 */
u8 Menu_FindInventoryItemAtOffset(u8 offset)
{
    u8 itemId = gMenuInventoryStartItem;
    u8 found = 0;

    while (found < offset)
    {
        if (gPartyItemCounts[itemId] != 0)
            found++;
        itemId++;
        if (itemId == 0xFF)
            return 0;
    }
    while (itemId != 0xFF)
    {
        if (gPartyItemCounts[itemId] != 0)
            return itemId;
        itemId++;
    }
    return 0;
}

/**
 * @brief 判断库存是否足够让当前角色预定一个战术物品
 *
 * @note characterIndex 为零基记录索引；统计其他队员同物品预定数；库存大于该数返回一，否则零。
 * @address 0x08016B30
 */
u8 Menu_CanReserveTacticsItem(u8 characterIndex, u8 itemId)
{
    u16 slot = 0;
    u8 reservedCount = 0;
    u8 index;
    struct PartyCharacter *character;

    while (slot <= 4 && (index = gPartyMembers[slot]) != PARTY_NO_MEMBER)
    {
        if (index != 0)
            index--;
        if (index != characterIndex)
        {
            character = &gPartyCharacters[index];
            if (character->tacticsAction == 2 && character->tacticsActionId == itemId)
                reservedCount++;
        }
        slot++;
    }
    if (reservedCount >= gPartyItemCounts[itemId])
        return 0;
    return 1;
}

/**
 * @brief 打包第四槽并安排从 SRAM 块 12 开始的奖励数据写入
 *
 * @note 设置 I/O 状态 3、起始块 12、请求种类 0 并显示保存提示；传输由 Save_UpdateIo 推进，本入口只提交请求。
 * @address 0x08016BB0
 */
void Save_RequestBonusWrite(void)
{
    Save_PackBonusSlot();
    gSaveIoState = 3;
    gSaveIoBlockIndex = 0xC;
    gMenuSaveRequestKind = 0;
    Menu_ShowHintWithPalette(0x18, 0xB);
}

/**
 * @brief 将 FF 结尾的单行文字转换为 palette<<12 加 200 再加字符编号的半字 tile
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08016BE0
 */
void Menu_DrawSingleRowText(u16 *dest, const u8 *text, u8 palette)
{
    while (*text != 0xFF)
    {
        *dest = (palette << 12) + 0x200 + *text;
        dest++;
        text++;
    }
}

/**
 * @brief 按 FF 结尾文字长度写 F200，擦除对应单行文字
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08016C10
 */
void Menu_EraseSingleRowText(u16 *dest, const u8 *text)
{
    while (*text != 0xFF)
    {
        *dest++ = 0xF200;
        text++;
    }
}

/**
 * @brief 返回 02005800 加二倍 x+32*y 的文本 tilemap 指针
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08016C2C
 */
u16 *Menu_GetTextAddress(u8 x, u8 y)
{
    return ((u16 *)0x02005800 + ((y) * 32 + (x)) );
}

/**
 * @brief 将光标坐标清零，初始化第 112 个软件精灵并转至标题第零页
 *
 * @note 语义按原 ROM 的参数、读写和调用者确认。
 * @address 0x08016C44
 */
void TitleMenu_CreateCursorSprite(void)
{
    struct SpriteNode *spr = &gSpriteNodes[112];

    gMenuCursor.y = 0;
    gMenuCursor.x = 0;
    Sprite_InitNode(spr, 1, 0, 0x81E0, 0x21C0);
    gSpriteDrawOrder[0] = spr;
    Menu_TransitionToPage(0);
}

